window.HB_TR["exodus"]["ks"]=["1. وۅنۍ چھہِ یِم بنی اسرائیل کین ناو، یُس مصرس منز آو۔ پریتھ انسان تہ تسند گرہ اوس یعقوبس سیتۍ یوان۔\n2. روبن، شمعون، لیوی تہٕ یہوداہ،\n3. اِساکر، زبولُن تہٕ بنیمن،\n4. دان، تہٕ نفتالی، گاڈ تہٕ آشر۔\n5. تہٕ یعقوب سٕندِ کمرٕ منزٕ یِم سٲری روح دراو تِم ٲسۍ ستتھ روح: کیازِ یوسف اوس مصرس مَنٛز۔ {loins: Heb. ران}\n6. تہٕ یوسف موٗد تہٕ تٔمۍ سٕندِ سٲری بٲے تہٕ سٲرۍسٕے نسل۔\n7. تہٕ بنی اسرائیل گٔیہٕ پھلدار تہٕ گٔیہٕ واریاہ زیادٕ، تہٕ بٔڑۍ تہٕ زیادٕ بڑاونہٕ۔ تہٕ زمین ٲس تِمو سٍتۍ بٔرِتھ۔\n8.\\tوۅنۍ ووت مصرس پیٹھ اکھ نۆو بادشاہ، یُس نہٕ یوسفس زانان اوس۔\n9.\\tتہٕ تٔمۍ ووٚن پننِس قومس زِ وُچھو، بنی اِسرٲیلٕکۍ قوم چِھ اسہِ کھوتہٕ زیادٕ تہٕ طاقتور آسان:\n10. پٔکِو أسۍ تِمن سٍتـ̡ دانشمندی سان سٍتـ̡ س� یێلہِ یێلہِ کانہہ جنگ سپدِ، تِم گژھن سانین دُشمنن سٍتـ̡ رٔلِتھ تہٕ اسہِ خلاف لڑان تہٕ یِمن زمینہٕ منزٕ نیبر نیرِ۔\n11. تَمہِ کِنۍ کٔر تِمو تِمن پیٹھ ٹاسک ماسٹر مقرر تاکہ تِمن پنُن بوجھ دِنہٕ۔ تہٕ تِمو بنٲو فرعونس خٲطرٕ خزانہٕ شہر، پتھوم تہٕ رامسیس۔\n12.\\tمگر یوت یوت تِمو تِمن مُتٲثِر کٔرِتھ، تیوٗت گٔیہِ تِم بٔڈِتھ تہٕ بٔڈۍ۔ تہٕ تِم گٔیہِ بنی اِسرٲیلِس سٍتـ̡ غم۔ {مگر...: ہیب۔ تہٕ یِتھٕ پٲٹھۍ تِمو تِمن مُتٲثِر کٔرۍ، تِتھۍ گٔیہِ تِم بٔڈِتھ وغیرہ۔\n13. تہٕ مصریو بنوو بنی اسرائیل سختی سان خدمت کرنہٕ۔\n14. تہٕ تِمو بنٲو پنٕنۍ زندگی سختی غلامی سٍتۍ، مورٹرس منز، سیرن منز، تہٕ میدانس مَنٛز پرٮ۪تھ قسمٕچ خدمتہٕ سٍتـ̡ تلخ ۔\n15.\\tتہٕ مصرٕکۍ بادشاہن کٔر عبرانی دٲین سٍتـ̡ کتھ ، یێمہِ سُند ناو اوس شفرا تہٕ بییِس پواہُک ناو:\n16.\\tتہٕ تٔمۍ ووٚن، ییلہ تم عبرانی زنانن ہٕندِ دٲی ہُند کٲم کران چھِو، تہٕ تِمن وُچھِو سٹولس پیٹھ۔ اگر یہِ {نیچو} آسہِ، تیلہِ کٔرِو سُہ مٲرِتھ، مگر اگر یہِ {کورِ} آسہِ، تیلہِ گژھہِ سۄ زندٕ۔\n17.\\tمگر دٲی گٔیہِ خدایہ سُند خوف تہٕ مصرٕکۍ بادشاہن ہُند حُکُم کٔرِکھ نہٕ، مگر بچٲوِکھ مردن ہٕندِ شُرِ زِندٕ۔\n18.\\tتہٕ مصرٕکۍ بادشاہن بُلوو دٲی تہٕ تِمن وونُن، ژیہ کیازِ کور یہِ کٔرِتھ، تہٕ بچٲوِکھ مردن ہٕندِ شُرِ زِندٕ۔\n19.\\tتہٕ دٲیو ووٚن فرعونس تکیازِ عبرٲنی زنانہٕ چھے نہٕ مصری زنانن ہٕندۍ پٲٹھۍ۔ تِکیازِ تِم چھِ زندٕ روزان، تہٕ دٲی یِنہٕ برٛونٛہٕے چھِ دٲی یِوان دِنہٕ۔\n20. تێمہِ کِنۍ کٔر خداین دٲین سٍتـ̡ رٔژ سٍتـ̡ تہٕ لُکھ گٔیہِ بٔڈِتھ تہٕ گٔیہِ سٮ۪ٹھاہ طاقتور۔\n21.\\tتہٕ سپُد سپُد، تِکیازِ دٲی ٲس خدایہ سُند خوف تھاوان، تٔمۍ بنوو تِم مکانہٕ۔\n22.\\tتہٕ فرعونن دِژ پننین سارنٕے لُکن ہُند حُکُم زِ یُس پرٮ۪تھ کانہہ نیچو پٲدٕ سپدِ، تہٕ پرٮ۪تھ کُنہِ کورِ زِندٕ بچٲوِو۔","1.\\tتہ گۆو لاوی سٕندِس گرس منز اکھ مرد، تہٕ ہیوٚتُن لاوی سٕنز کورِ نِش خاندار۔\n2.\\tتہٕ زنانہِ ہُند حٲملہٕ تہٕ نیچو زیٚوُن، تہٕ ییلہ أمِس وُچھ زِ سُہ چُھہ اصل شُر، تٔمۍ کٔر سُہ تریہ ریتھ ژوٗر۔\n3.\\tتہٕ ییلہ سۅ أمِس ژوٗرِ تھٲوِتھ ہیوٚک نہٕ، تٔمۍ نِش نِش بُلُن ہُند اکھ صندوق تہٕ لٔگِتھ تہٕ کوٚرُن شُر اَتھ مَنٛز ۔ تہٕ تٔمۍ ترٛٲو دریاو کِس بٹھس پیٹھ جھنڈن منٛز۔\n4.\\tتہٕ تٔمۍ سٕنز بینہِ ٲس دوٗر کھڑا، یہ زِ أمِس کیا ییہِ کرنہٕ۔\n5. تہٕ فرعون سٕنز کورِ آیہِ دریاوس نِش پان چھلنہٕ خٲطرٕ۔ تہٕ تٔمۍ سٕنزِ کۅکرِ ٲس دریاو کِس بٹھس کُن پکان۔ تہٕ ییٚلہ تٔمۍ جھنڈن درمیان صندوق وُچھ، تٔمۍ سوز پنٕنۍ نونہٕ یہٕ اننہٕ خٲطرٕ۔\n6.\\tتہٕ ییلہ تٔمۍ کھول، أمِس وُچھ شُر: تہٕ وُچھ شُرِ وُچھ۔ تہٕ أمِس اوس أمِس پیٹھ رحم تہٕ وونُن، یہِ چُھ عبرانین ہٕندٮ۪ن شُرین مَنٛز اکھ۔\n7. اَمہِ پتہٕ ووٚن تٔمۍ سٕنزِ بینہِ فرعون سٕنزِ کورِ زِ بہٕ گژھٕ تہٕ ژےٚ نِش عبرٲنی زنانہِ ہٕنز اکھ دٲیرٕ بُلاونہٕ یُتھ سُہ کرِ تۅہہِ ہٕندِ خٲطرٕ شُرِس دۄدٕ دِنہٕ۔\n8. تہٕ فرعون سٕنزِ کورِ ووٚن أمِس گژھ۔ تہٕ دٲر گٔیہِ شُرۍ سٕنزِ موج بُلان۔\n9. تہٕ فرعون سٕنزِ کورِ ووٚن أمِس زِ یہِ شُر نِش نِش تہٕ میانہِ خٲطرٕ دِیُن تہٕ بہٕ دِیہٕ تُہند معاوضہٕ۔ تہٕ زنانہِ رٔٹ شُر، تہٕ دِژ أمِس دۄد۔\n10. تہٕ شُر گوٚو بٔڑِتھ تہٕ سُہ أنۍ فرعون سٕنزِ کورِ نِش، تہٕ سُہ بنیوو تٔمۍ سُند نیٚچُو۔ تہٕ تٔمۍ ووٚن تٔمۍ سُند ناو موسیٰ تہٕ تٔمۍ ووٚن، کیازِ مے کٔر سُہ آبہٕ منزٕ نیبر۔ {موسیٰ: یعنی ڈرا آؤٹ}\n11.\\tتہٕ تِمن دۅہن سپد ییلہ موسیٰ بٔڈِتھ گوو، سُہ گۆو پننین باین نِش تہٕ تِمن ہٕندِس بورس وُچھان تہٕ تٔمۍ وُچھ أکِس مصری یُس پننِس أکِس بٲے سٍتـ̡ ماران اوس۔\n12.\\tتہٕ تٔمۍ وُچھ اَتھ کُن تہٕ ییلہ تٔمۍ وُچھ زِ {اَتہِ} چُھنہٕ کانہہ انسان، تٔمۍ مور مصری تہٕ ژوٗرِ سُہ سیٚکہِ مَنٛز۔\n13.\\tییلہ سُہ دوٚیمہِ دۅہہ نیبر نیرِ، وُچھ عبرانیو ہٕندِس زٕ نفرو رٔلِتھ لٔگِتھ تہٕ تٔمۍ ووٚن أمِس یُس غلط کورمُت، کیازِ چُھکھ ژے پنُن سٲتھی؟\n14.\\tتہٕ ووٚن، ژے کٔمۍ بنوو اسہِ پیٹھ شہزادہ تہٕ قاضی؟ ژے چھکھ میہ مارُن، یتھہ پاٹھۍ ژے مصری قتل کورمُت؟ تہٕ موسیٰ گوٚو خوف، تہٕ ووٚنُن، یقینا چُھ یہ چیز معلوم۔ {اکھ شہزادہ: ہیب۔ اکھ مرد، اکھ شہزادہ}\n15.\\tییلہ فرعونن یہ کتھ بوز، تٔمۍ کٔر موسیٰ سُند قتل کرنچ کوشش۔ مگر موسیٰ ژوٚل فرعون سٕندِ بُتھِ نِش تہٕ روٗد مِدیان کِس سرزمینس مَنٛز، تہٕ بیوٹھ أکِس کۄرِس نِش۔\n16.\\tوۅنۍ ٲس مدیان کِس پادٕرس ستھ کورِ: تہٕ تِمو آیہِ تہٕ آب کٔرِتھ بٔرِتھ پننِس مٲلہِ سٕندِس کھورِ آب دِنہٕ خٲطرٕ۔ {پادری: یا، شہزادہ}\n17.\\tتہٕ گٔیہِ پٔرِتھ تہٕ ژٔلِتھ ژٔلِتھ تہٕ دِژُن تِمن ہٕندِس کھورِ سٍتـ̡ تہٕ دِژُن تِمن ہٕندِس کھورِ سٍتـ̡ آب دِنہٕ۔\n18.\\tتہٕ ییلہ تِم پننِس مٲلِس رِویلس نِش آیہ، تٔمۍ ووٚن زِ ژیہ کِتھہ پٲٹھۍچھِو یُتھ دۅہہ یُتھ جلدی آمُت؟ {Reuel: یتھ جیتھرو تہِ ونان چھہِ}\n19.\\tتہٕ تِمو ووٚن، أکۍ مصری کٔر اسہِ چرواہِ ہٕندِ اتھہٕ نِش نِش نِش تہٕ دِژُن سانہِ خٲطرٕ سٮ۪ٹھاہ آب تہٕ دِژُن ریوُس آب۔\n20. تہٕ تٔمۍ ووٚن پننین کورن تہٕ سُہ کتہِ چُھ؟ {یہ} کیازِ چھُکھ یہِ {یہ} ژےٚ نفر ترٛٲومُت؟ أمِس بُلاو تاکہ سُہ گژھِ روٹی کھٮ۪نہٕ۔\n21.\\tتہٕ موسیٰ اوس أمِس شخصس سٍتـ̡ روزنہٕ خٲطرٕ راضی، تہٕ تٔمۍ دِژ موسیٰ زِپوراہس پنٕنۍ کوٗر۔\n22.\\tتہٕ أمِس زاے اکھ نیچو، تہٕ تٔمۍ ووٚن گرشوم ناو، تکیازِ تٔمۍ ووٚن بہٕ چُھس أکِس اجنبی زمینس مَنٛز اجنبی گومُت۔ {گرشوم: یعنی اکھ اجنبی}\n23. تہٕ ووت وقتس سٍتـ̡ سپدُن زِ مصرُک بادشاہ مٔرِتھ تہٕ بنی اسرٲیلِیو کٔر غلامی کِس وجہہ سٍتـ̡ شۅنگہٕ تہٕ تِمو روُد، تہٕ تِہُند فریاد ووت غلامی کِنہِ خدایس نِش۔\n24. تہٕ خداین بوز تِہٕنزِ کرٛٮ۪کہٕ تہٕ خداین کوٚر ابراہیم، اسحاق تہٕ یعقوبس سٍتـ̡ پنُن عہد یاد۔\n25.\\tتہٕ خداین کٔر بنی اسرائیلس وُچھان تہٕ خداین کٔر تمن ہُند احترام۔ {had...: Heb. زانہ}","1. وۅنۍ تھوو موسیٰ یتھرو سُند ریوُن یُس مدیانُک پادٕرۍ اوس، تہٕ سُہ رٔژھ ریگستانہٕ کِس پٔتِمس کُن تہٕ ووت خدایہ سٕندِس پہاڑس کُن، حوربس کُن۔\n2.\\tتہٕ خداوند سُند فرشتہ آو أمِس کُنہِ کُنہِ نارس منز نمودار، تہٕ تٔمۍ وُچھ تہٕ وُچھِتھ گٔیہِ کُنہ\n3.\\tتہٕ موسىٰ ووٚن بہٕ وُنہِ پتھ کُن تہٕ وُچھِتھ یہِ عظیم نظارہٕ زٲلِتھ کیازِ چھُنہٕ دزنہٕ آمُت۔\n4. تہٕ ییلہ خداوند وُچھ زِ سُہ وُچھنہٕ خٲطرٕ پھیُر، خداین بُلوو أمِس کُنہِ تہٕ تٔمۍ ووٚن، یتھے {am} I.\n5.\\tتہٕ تٔمۍ ووٚن، یور نہٕ یور کٔرِتھ: پَنٕنۍ کھۄرٕ نِش ترٲوِو پَنٕنۍ کھۄرٕ نِش، تِکیازِ یَتھ جایہِ تُہۍ کھڑا چھِو سُہ چھُ مقدس زمین۔\n6.\\tامہِ علاوہ ووٚن بہٕ چُھس تہندِس مٲلہِ سُند خدا، ابراہیم سُند خدا، اسحاق سُند خدا تہٕ یعقوب سُند خدا۔ تہٕ موسیٰ کٔر پَنُن بُتھ ژوٗر۔ تکیازِ سُہ اوس خدایس کُن نظر تراونہٕ نِش کھوژان۔\n7. تہٕ خداوند ووٚن زِ میہ چُھ پٔزۍ پٲٹھـ̡ پننین لوکن ہُند مصیبت وُچھمُت یُس مصرس مَنٛز چُھہ، تہٕ چُھس تِہٕندِس ٹاسک مالہٕ سٍتـ̡ تِہٕنزِ فریاد بوزمٕژ۔ تکیازِ بہٕ چُھس تِہُند غم زانان۔\n8. تہٕ بہٕ ووت تِم مصری ہٕندِ اتھہٕ نِش نجات دِنہٕ خٲطرٕ، تہٕ تِم اَتھ زمینہٕ منزٕ أکِس اصل زمینس تہٕ بٔڈِس زمینس مَنٛز اننہٕ خٲطرٕ، یُس دۄد تہٕ ماچھ سٍتـ̡ وسان آسہِ۔ کنعانی، حتی، اموری، تہٕ پیرزی، تہٕ حِوی تہٕ یبوسی ہٕنزِ جایہ۔\n9.\\tتێلہِ وُچھو وُچھِو بنی اِسرٲیلِچ فریاد میانہِ نِش آمٕژ، تہٕ مے وُچھمُت سُہ ظُلم تہِ یێمہِ سٍتـ̡ مصری یِمن سٍتـ̡ ظلم کران چھُ۔\n10.\\tتێلہِ یێلہِ یێلہِ تہٕ بہٕ سوزٕ ژے فرعونس نِش، یُتھ ژٕ میانین لوکن مصرہٕ منزٕ بنی بنی اسرائیل نیبر کڈِ۔\n11. تہٕ موسىٰ ووٚن خدایس زِ بہٕ کُس چُھس، بہٕ گژھ فرعونس نِش گژھُن، تہٕ بہٕ کرٕ بنی اسرائیل مصرہٕ منزٕ نیبر نیرُن۔\n12.\\tتہٕ ووٚنُن، یقینا بہٕ آسہٕ ژےٚ سٍتـ̡ ۔ تہٕ یہِ آسہِ تۅہہِ خٲطرٕ اکھ نشانہٕ، یُس مے ژے سوزمُت چھُ: ییلہ ژے مصرہٕ منزٕ لُکھ نیبر کٔرِو، تۅہہ کٔرِو یَتھ پہاڑس پیٹھ خدایہ سٕنز خدمت۔\n13. تہٕ موسىٰ ووٚن خدایس زِ یێلہِ بہٕ یێلہِ بہٕ بنی اسرٲیلِس نِش یِوان تہٕ تِمن وَنُن زِ تہندٮ۪ن آباؤ اجدادن ہٕندِ خداہِ سٕندِ خداہِ چُھہ مے ژےٚ نِش سوزمُت۔ تہٕ تِم وَنَن مے زِ تٔمۍ سُند ناو کیا چُھ؟ بہٕ کیا وَنُن تِمَن؟\n14. تہٕ خداین ووٚن موسیٰ سٍتـ̡ بہٕ چُھس یُس بہٕ چُھس، تہٕ تٔمۍ ووٚن، یِتھٕ پٲٹھـ̡ چُھہ تُہۍ بنی اِسرٲیلِس وَنُن زِ بہٕ چُھس پانس نِش سوزمُت۔\n15. تہٕ خداین ووٚن موسیٰ سٍتـ̡ تہٕ یِتھٕ پٲٹھـ̡ چُھہ تُہٕندِس آباؤ اجدادن ہُند خدا، ابراہیم سُند خدا، اسحاق سُند خدا، تہٕ یعقوب سُند خدا، تہٕ یعقوب سُند خدا، چُھہ مے ژے نِش سوزمُت: یێہے چُھہ میٲنۍ ناو ہمیشہٕ خٲطرٕ، تہٕ یہِ چُھہ سارنٕے نسلن ہٕندِ خٲطرٕ میٲنۍ یادگار۔\n16. گژھ تہٕ اسرٲیلٕکۍ بزرگن جمع کٔرِتھ تہٕ تِمن وَنُن، تہٕ تُہٕندِس آباؤ اجدادن ہُند خدا، ابراہیم سُند خدا، اسحاق تہٕ یعقوب سُند خدا، آو میہ برونہہ کُن ظٲہر تہٕ وُچھمُت یُس مصرس مَنٛز چُھہ کرنہٕ آمُت:\n17. تہٕ مے چُھس ووٚنمُت، بہٕ واتناوٕ ژے مصر کِس مصیبت منزٕ کنعانی، حتی، اموری تہٕ پیرزی، حِوی تہٕ یبوسی ہٕندِس سرزمینس منز، یُس دۄد تہٕ ماچھ سٍتـ̡ وسان آسہِ۔\n18. تہٕ تِم گژھن تُہٕنز آواز بوزنہٕ، تہٕ تُہۍ یِن، تہٕ اسرٲیلِکۍ بزرگ، مصرٕکِس بادشاہس نِش یِن، تہٕ تُہۍ وَنُن زِ عبرانیَن ہُند خداوند چُھ اسہِ سٍتـ̡ مُلاقات کورمُت، تہٕ وۅنۍ گژھو أسـ̡ تێلہِ ترٚین دۅہن ہُند سفر بیابانس مَنٛز، یُتھ أسۍ پننِس خداہس سٍتـ̡ قربان کٔرِتھ۔\n19. تہٕ مےٚ چُھ یقین زِ مصرُک بادشاہ دِیہ نہٕ ژےٚ نیرُن، نہٕ نہٕ زورٕ اتھہٕ سٍتـ̡ نہٕ۔ {نہ...: یا، مگر مضبوٗط اتھہٕ سٍتۍ}\n20. تہٕ بہٕ کٔرٕ پنُن اَتھٕ پھٔہلٲوِتھ تہٕ پَنٕنـ̡ سارِنٕے عجائب سٍتـ̡ مِصرس سٍتـ̡ مارٕ یُس بہٕ اَتھ مَنٛز کرِ، تہٕ اَمہِ پَتہٕ دِیہِ سُہ ژےٚ یِنہٕ۔\n21. تہٕ بہٕ دِیہٕ یِمن لوکن مصرن ہٕندِس نظرس منز احسان تہٕ یہ سپدِ زِ ییلہ تہٕ ژیہ نیرِو، تہٕ یێلہِ گژھہِ نہٕ خٲلی گژھُن:\n22. مگر پرٮ۪تھ کُنہِ زَنان گژھِ پننِس ہمساین تہٕ یُس تٔمِس گرس منز روزان آسہِ، رۄپہٕ ہٕندِ جوٲہر، تہٕ سۄنہٕ سٕندِ جوٲہرات تہٕ پلو نِن، تہٕ تُہۍ پَنٕنٮ۪ن نیٚچوٮ۪ن تہٕ کورِ ہٕندِس پٲٹھۍ۔ تہٕ تُہۍ کٔرِو مصری خراب کرنہٕ۔ {مصری: یا، مصر}","1. تہٕ موسىٰ دِژ جواب تہٕ ووٚنُن، مگر یِم چھِنہٕ میانہِ کتھہِ پیٹھ یقین کٔرِتھ، تہٕ میانہِ آوازِ بوزنہٕ یِوان، تِکیازِ تِم وَنَن زِ خداوند چُھنہٕ ژےٚ ظٲہر گومُت۔\n2. تہٕ خداوند ووٚن أمِس زِ یہِ کیا چُھہ تُہندِس اتھس منز؟ تہٕ أمۍ ووٚن، اکھ راڈ۔\n3.\\tتہِ ووٚن یہ زمینس پیٹھ تراوُن۔ تہٕ تٔمۍ ترٛٲو یہِ زٔمیٖنس پیٹھ، تہٕ یہِ بنیوو ناگ۔ تہٕ موسیٰ ژوٚل امہِ برونہہ کُن۔\n4. تہٕ خداوند ووٚن موسیٰ سٕندِس اتھہٕ تہٕ رٔٹِتھ رٔٹِتھ رٔٹِو۔ تہٕ تٔمۍ کٔر پنُن اتھہٕ تہٕ رٔٹتھ تہٕ یہ بنیوو أمۍ سٕنٛدس اتھس منٛز اکھ لور:\n5. یێلہِ تِم پژھ کٔرِتھ زِ تِمن ہُند خدا، ابراہیم سُند خدا، اسحاق سُند خدا، تہٕ یعقوب سُند خدا چُھہ توے برونہہ کُن ظٲہر گومُت۔\n6.\\tتہٕ خداوند ووٚن أمِس بییہِ تہِ زِ پَنُن اَتھٕ تھاوُن پنہٕ نِس سٍتـ̡ ۔ تہٕ تٔمۍ تروو پنُن اَتھٕ پننِس سینس منٛز، تہٕ ییٚلہ تٔمۍ یہِ کٔڑ، وُچھ تٔمۍ سُنٛد اَتھٕ اوس شینہٕ ہیوٗ کوڑھ۔\n7. تہٕ تٔمۍ ووٚن پنُن اَتھٕ دُبارٕ پننِس سینس مَنٛز۔ تہٕ تٔمۍ تروو بییہ پننس سینس منز اتھہ۔ تہٕ تُلُن سُہ پننہِ چھۅکہٕ منز، تہٕ وُچھِن یہِ دُبارٕ أمۍ سٕندِس {باقی} ماز سٕندِس پٲٹھۍ۔\n8. تہٕ یێلہِ نہٕ تِم تۅہہِ پیٹھ پژھ کرن، تہٕ نہ گژھن گۄڈنِچہِ نشانہٕ سٕنزِ آوازِ پیٹھ پژھ پٲٹھۍ۔\n9.\\tتہٕ یێلہِ یێلہِ نہٕ تِم یِمن دۅن علامتن پیٹھ تہِ یقین کرِ، تہٕ تُہٕنزِ آواز بوزنہٕ یِن، زِ ژے کٔرِو دریاوُک آب نِش تہٕ خشک زمینس پیٹھ تراوُن، تہٕ یُس آب ژے دٔریاوٕ منزٕ نیران چُھ، سُہ گژھہِ خشک زمینس پیٹھ خون۔ {گژھہِ بنہِ: ہیب۔ آسہِ تہٕ آسہِ}\n10. تہٕ موسىٰ ووٚن خداوند سٍتـ̡، اے میانہِ آقا، بہٕ چُھس نہٕ فصاحت کٔرِتھ، نہ از تام تہٕ نہ چُھہ ژے پننِس خادمس سٍتـ̡ کتھ کٔرمٕژ، مگر بہٕ چُھس سُست کتھ تہٕ لوٚت زبانہٕ سٍتـ̡ ۔ {فصاحت: ہیب۔ لفظن ہند آدم} {امہ برونہہ کُن: ہیب۔ راتھ پیٹھ، نہ تریمہِ دۅہہ پیٹھ}\n11. تہٕ خداوند ووٚن أمِس زِ کٔمۍ چُھ انسان سُند ٲس؟ یا کُس چُھ گونگ، زر، یا وچھن وٲل، یا انہِ بناوان۔ کیا میہ چھہ نہ خداوند؟\n12.\\tتێلہِ گژھ وۅنۍ تہٕ بہٕ روزٕ چانہِ ٲسس سٍتـ̡ تہٕ ژے کیا ونُن ہیچھناوُن۔\n13.\\tتہٕ وۆنُن اے خداوند، سوزُن، بہٕ چھُس ژے دُعا کٔرِتھ یُس ژے سوزان چھُ۔ {وِلٹ: یا، پَزِ پَزِ}\n14.\\tتہٕ خداوند سُند غصہٕ آو موسیٰ سٕندِس سٍتـ̡ دِنہٕ، تہٕ تٔمۍ ووٚنُن، کیا ہارون لاوی چُھہ نہٕ تُہند بوے ؟ میہ چھیہ پتاہ زِ سہ ہیکہِ جان پاٹھۍ کتھ کٔرتھ۔ تہٕ وُچھِتھ چُھ سُہ ژےٚ مِلنہٕ خٲطرٕ نیران، تہٕ ییلہ سُہ ژےٚ وُچھِ، سُہ گژھہِ دِلس منز خۄش۔\n15.\\tتہٕ ژٕ کٔرِو أمِس سٍتـ̡ کتھ تہٕ تێہہِ سٍتـ̡ کٔرِتھ تہٕ تێلہِ ہیچھناوٕ ژے کیا کرُن۔\n16. تہٕ سُہ آسہِ تُہند ترجمان تہٕ سُہ آسہِ تۅہہِ سٍتـ̡ ٲسِتھ تہٕ خدایہ سٕندِ بدلہٕ تہٕ تُہٕندِس سٍتـ̡ بٔنِتھ۔\n17. تہٕ ژے رٔٹِو یہِ لٔر پننِس اتھس منٛز، یَتھ سٍتـ̡ ژے نشانہٕ کٔرِو۔\n18.\\tتہٕ موسیٰ گۆو تہٕ پننِس مٲلس جیتھرو نِش واپس، تہٕ وونُن تٔمِس نیرُن، بہٕ چھُس ژےٚ دُعا کران تہٕ پننین باین نِش واپس، یِم مصرس مَنٛز چھِ، تہٕ وُچھِن زِ تِم چھا وُنہِ تہِ زندٕ۔ تہٕ جیتھروَن ووٚن موسیٰ سٕندِس سٍتـ̡ گژھِ۔ {جیتھرو: ہیب۔ جیتھر}\n19. تہٕ خداوند ووٚن مدیانس مَنٛز موسیٰ ہس مَنٛز، گژھ مصرس مَنٛز واپس، تکیازِ سٲری انسان چِھ مٔرۍمٕتۍ، یِمو تُہند زُو ژھاران چھُ۔\n20. تہٕ موسىٰ رٔٹِتھ پنٕنۍ زنانہِ تہٕ نیچوۍ تہٕ تھووُن أکِس گَرَس پیٹھ، تہٕ سُہ آو مصرٕچ سرزمینس منز واپس۔ تہٕ موسىٰ رٔٹِتھ رٔٹِتھ خدایہِ سٕنز لٔر پننِس اتھس منز۔\n21. تہٕ خداوند ووٚن موسیٰ سٕندِس سٍتـ̡ ییلہ تہٕ ژٕ مصرس مَنٛز واپس گژھنہٕ خٲطرٕ گژھِ، وُچھ تہٕ ژے کٔرِو فرعونس برونہہ کُن تِم سٲری عجائب یُس مے تۅہہِ ہٕندِس اتھس مَنٛز تھوومُت چُھ، مگر بہٕ کَرٕ تٔمۍ سُند دِل سخٕت تہٕ سُہ دِیہِ نہٕ لُکن ہُند دِل دِنہٕ۔\n22. تہٕ ژٕ چُھہ فرعونس وَنُن، یِتھٕ پٲٹھۍ چُھ خداوند فرماوان زِ اسرٲیِل چُھ میون نیچو، {حتیٰ کہ} میون گۄڈنیُک زامُت:\n23. تہٕ بہٕ چُھس ژے ونان زِ میون نیچو تراوُن، یُتھ سُہ میانہِ خدمت کرِ، تہٕ اگر ژے أمِس تراونس انکار کٔرِو، وُچھِتھ بہٕ مارٕ تُہند نیچو، تہٕ تُہند گۄڈنیُک شُر تہِ۔\n24.\\tتہٕ سراءِ ہٕندِس وتہِ کِنۍ سپُد خداوند أمِس سمکھیوو، تہٕ أمِس مارنٕچ کوٗشش۔\n25.\\tاَمہ پتہٕ ژٔٹِتھ دِژُن تٔمۍ سٕندِس قدمن پیٹھ، تہٕ وونُن، یٔقیٖنی طور چھُکھ اکھ خونریز خانٛدار۔ {تیز...: یا، چھُر} {کاسٹ...: ہیب۔ بنیوو اَتھ ٹچ}\n26.\\tتێلہِ دِژ أمِس یێلہِ تێلہِ وۆنُن، ختنہ کِنـ̡ سٍتـ̡ چُھہ خونریز خانٛدار۔\n27. تہٕ خداوند ووٚن ہارونس زِ موسیٰ سٕندِس سمکھنہٕ خٲطرٕ گژھ بیابانس مَنٛز۔ تہٕ سُہ گۆو تہٕ خدایہ سٕندِس پہاڑس منز سمکھیوو أمِس تہٕ کوٚرُن أمِس بوس۔\n28.\\tتہٕ موسىٰ ووٚن ہارونس خداوند سٕندِ سٲری کلام یُس أمِس سوزمُت اوس، تہٕ تِم سٲری نشانہٕ یِم تٔمِس حکم دِژمٕژ ٲس۔\n29. تہٕ موسیٰ تہٕ ہارون گٔیہِ تہٕ بنی اِسرٲیلِکۍ سارِنٕے بُزرگ جمع کٔرِتھ:\n30. تہٕ ہارونن کٔر تِم سٲری لفظ یِم خداوند موسیٰ ہس سٍتـ̡ کٔرۍمٕتۍ، تہٕ کٔرٕن لُکن ہٕندِس نظرس مَنٛز نشانہٕ۔\n31.\\tتہٕ لُکھ کٔر پَنُن پَنُن پٲٹھـ̡ تہٕ یێلہِ تِمو کلہٕ نوٚمُت تہٕ کٔرٕکھ عبادت۔","1. تہٕ اَمہِ پَتہٕ گٔیہِ موسیٰ تہٕ ہارون اَندٕر، تہٕ ووٚنُن فرعونس زِ یِتھٕ پٲٹھۍ چُھ اسرٲیلُک خداوند خدا، میانین لُکن تراوُن، یُتھ تِم بیابانن مَنٛز میانہِ خٲطرٕ دعوت مناون۔\n2. تہٕ فرعونن ووٚن، خداوند کُس چُھ، زِ بہٕ پزِ تسٕنزِ آوازِ ہٕنز اطاعت کرٕن، یُس اسرٲیلِس تراوُن دِنہٕ خٲطرٕ؟ بہٕ چُھس نہٕ خداوند زانان، تہٕ بہٕ دِیہٕ اسرٲیلِس تراوُن۔\n3. تہٕ تِمو ووٚن، عبرانین ہُند خدایہ چُھ اسہِ سٍتـ̡ مُلاقات کٔرِتھ: أسـ̡ چُھہ تێلہِ دُعا کٔرِتھ، ترٚین دۅہن ہُند سفر صحراہس مَنٛز، تہٕ کٔرِو خداوند سٕندِس خداہس سٍتـ̡ قربانی۔ نتہ گژھہِ سُہ اسہِ پیٹھ وبا یا تلوار سٍتۍ پییہِ۔\n4. تہٕ مصرٕکۍ بادشاہن ووٚن تِمَن زِ موسیٰ تہٕ ہارون کیازِ چھِو لُکن تِمن ہٕندِ کامہِ نِش تراوان۔ پَنٕنِس بوجَس تام واتناوُن۔\n5.\\tتہٕ فرعونن ووٚن زِ وُچھِو زمینٕکۍ لُکھ وُنہِ واریاہ تہٕ تِمن ہٕندِس بوجھہٕ نِش آرام دِوان۔\n6. تہٕ فرعونن دِژ امی دۅہہ لوکن ہٕندِس ٹاسک ماسٹرز تہٕ تِہندین افسرن حکم دِتھ وونُن،\n7.\\tتہٕ یِتھٕ پٲٹھـ̡ لُکن سٍتـ̡\n8. تہٕ سیرن ہٕنز دٔلیلہٕ، یُس تمو امہ برونہہ بنوومُت اوس، تِمن پیٹھ تراوُن۔ تۅہہ گژھ نہ اتھ منز کمی کرُن: تکیازِ تم چھہِ بیکار روزان۔ تَمہِ کِنۍ چھِ تِم وَنان زِ أسۍ گژھو پننِس خدایہِ سٕندِ خٲطرٕ قربانی۔\n9.\\tمردن پیٹھ گژھن مزید کٲم کرنہٕ، یُتھ زن تِم اتھ منز محنت کرٕنۍ۔ تہٕ تِم گژھن نہٕ فضول لفاظن ہُند خیال تھاوُن۔ {تتہِ کرُن...: ہیب۔ کٲم گژھہِ مردن پیٹھ بوب}\n10.\\tتہٕ لُکن ہٕندِس مٲلکَس تہٕ تِہٕندِس افسرَن دِژ نٮ۪بر، تہٕ تِمو دِژ لُکن سٍتـ̡ کتھ تہٕ وَنُن یِتھٕ پٲٹھۍ چُھس فرعون ونان زِ بہٕ دِیہ نہٕ ژےٚ گاسہٕ۔\n11.\\tگژھ ژیہ کُنہِ کامہِ سٍتـ̡ یێلہِ تہِ میلہِ، توتہِ گژھہِ نہٕ تۅہہِ کامہِ ہُند کامہِ کم گژھُن۔\n12.\\tیێلہِ گٔیہِ لُکھ سارِنٕے مصرٕکِس سرزمینس مَنٛز پھٔہلِتھ گاسہٕ بجایہ کُلہٕ جمع کرنہٕ مۅکھہٕ۔\n13.\\tتہٕ ٹاسک ماسٹرو کٔر جلدی کٔرِتھ ونان، پنٕنۍ کامہِ پورٕ، یِتھٕ پٲٹھۍ ییلہ گاسہٕ آسہِ۔ {تُہند روزنامہٕ...: ہیب۔ تمۍ سندِ دۅہس منز اکھ دۅہک معاملہ}\n14.\\tتہٕ بنی اسرائیلٕکۍ افسر، یِم فرعون سٕندِس مٲلکَن تِمن پیٹھ مقرر کٔرۍمٕتۍ، مار دِنہٕ، تہٕ پرژھنہٕ آمُت، کیازِ چُھہ نہٕ راتھ تہٕ از سیر بناونٕچ کٲم پورٕ کٔرمٕژ۔\n15.\\tاَمہِ پَتہٕ آیہ بنی اِسرٲیلِکۍ افسر تہٕ وونُکھ فرعونس نِش کُن زِ ژے کیازِ چُھکھ پننین خادمَن سٍتـ̡ یِتھ سلوک کٔرِتھ؟\n16.\\tتہندٮ۪ن خادمَن چُھنہٕ کانہہ گاسہٕ دِنہٕ آمُت، تہٕ تِم چھِ اسہِ ونان زِ سیرِ بناوُن: تہٕ وُچھِو تُہٕندِس خادمَس مارنہٕ آمٕتۍ۔ مگر غلطی چھیہ تۅہہِ پننین لوکن منز۔\n17. مگر تٔمۍ ووٚن، تۅہہ چُھہ بیکار تہٕ تہٕ چُھہ خداوند سٕندِ خٲطرٕ قربانی دِوان۔\n18.\\tتَمہِ کِنۍ گژھِو وُن، {تہٕ} کامہِ؛ تکیازِ ژیہ ییہ نہ کانہہ گاسہ دِنہٕ، توتہِ کٔرِو سیرن ہٕنز دٔلیل۔\n19.\\tتہٕ بنی اسرائیل ہٕندِس افسرَو وُچھ {یہ} زِ تِم ٲسۍ بد کارس مَنٛز، یێلہِ یہِ وننہٕ آمُت زِ تِم گژھِ نہٕ پنہٕ نٕنـ̡ کامہِ ہٕنزِ سیرِ سٍتـ̡ ژٔٹِتھ کٔرِتھ۔\n20. تہٕ تِمو سمکھیو موسیٰ تہٕ ہارونس سٍتۍ، یُس فرعونس نشہِ نیرِتھ وتہِ کھڑا اوس۔\n21. تہٕ تِمو ووٚن تِمَن زِ خداوند چُھہ تُہہِ وُچھان تہٕ انصاف کرُن۔ تکیازِ تۅہہ چھہ فرعون سٕنزِ نظرِ تہٕ تٔمۍ سٕندٮ۪ن خدمتگارن ہٕنزِ نظرِ منز سانہِ ذائقہٕ بٔنِتھ تہٕ تٔمۍ سٕندِس خادمَن ہٕنزِ نظرِ منز اسہِ مارنہٕ خٲطرٕ تلوار ترٲوِتھ تہٕ تِمن ہٕندِس اتھس منز تلوار ترٲومٕژ۔ {to be...: Heb. بدبو}\n22. تہٕ موسیٰ آو رب نِش واپس، تہٕ وونُن، خداوند، ژے کیازِ کٔر اتھ لوکَس سٍتـ̡ بد خواہش؟ یہِ کیازِ چھُکھ ژےٚ سوزمُت؟\n23. یێلہِ بہٕ چُھس فرعونس نِش تُہٕندِس ناوٕ سٍتـ̡ کتھ کرنہٕ خٲطرٕ آمُت، تٔمۍ کٔر یِمن لُکن سٍتـ̡ بُرٕ۔ نہ چُھکھ ژے پنٕنۍ لوٗکھ بالکل بچٲومٕژ۔ {نہ تہِ...: ہیب۔ ڈلیوری کٔرِتھ چُھہ نہٕ ژے دِژمُت}","1. اَمہِ پَتہٕ ووٚن خداوند موسیٰ سٍتـ̡ وُچھِتھ زِ بہٕ کیا کرٕ فرعونس سٍتـ̡ یێلہِ سُہ مضبوٗط اتھہٕ سٍتـ̡ یێلہِ یێلہِ تِم دِیہِ تہٕ مضبوٗط اتھہٕ سٍتـ̡ کٔرِن تِم پننہِ زمینہٕ منزٕ کڈنہٕ۔\n2. تہٕ خداین کٔر موسیٰ سٍتـ̡ کتھ تہٕ تٔمِس وونُن، بہٕ چُھس خداوند چُھس: {خداوند: یا، یہوواہ}\n3. تہٕ بہٕ آو ابراہیم، اسحاق تہٕ یعقوب سٕندِس ناوس سٍتـ̡ ظٲہر کرنہٕ، مگر بہٕ اوسُس نہٕ پننہِ ناوٕ ییہوواہ سٍتـ̡ تِمن سٍتـ̡ زانان۔\n4. تہٕ مے چُھ تِمن سٍتـ̡ پنُن عہد تہِ قایم کورمُت، یێلہِ تِمن ہٕنزِ زیارتٕچ سرزمین دِنہٕ خٲطرٕ، یێلہِ تِم اجنبی ٲسۍ۔\n5.\\tتہٕ مے بوزمُت اسرٲیلِکۍ بنی ہُند کرٛٮ۪کھ تہِ، یِمن مصری غلامی منز تھاوان چھِ۔ تہٕ مے چُھ پنُن عہد یاد۔\n6. اَمہِ مۄکھٕ چُھس بنی اِسرٲیلِس وَنُن، بہٕ چُھس خداوند تہٕ بہٕ کَرٕ ژےٚ مصری ہٕندِس بوجھہٕ نِش نِش نیبر، تہٕ بہٕ کَرٕ ژےٚ تِہٕنزِ غلامی نِش آزاد تہٕ بہٕ کَرٕ ژےٚ نٔرِ نٔر تہٕ بٔڈۍ فیصلہٕ سٍتـ̡ نجات دِنہٕ۔\n7. تہٕ بہٕ نِہ ژے پانس نِش أکِس لُکہٕ سٕندِ خٲطرٕ، تہٕ بہٕ بنہٕ تہٕ ژے ہُند خدا تہٕ ژے گژھہِ معلوم زِ بہٕ چُھس خداوند تُہند خدا، یُس ژے مصرین ہٕندِس بوجھس تل نیران چُھ۔\n8.\\tتہٕ بہٕ اَنُن ژے اَتھ زمینس مَنٛز، یَتھ مُتعلِق مےٚ یہِ ابراہیم، اسحاق تہٕ یعقوبس دِنُک قسم اوس دِنہٕ آمُت۔ تہٕ بہٕ دِیہ یہ ژے أکِس وراثتس خٲطرٕ: بہٕ چُھس خداوند ۔ {قسم: ہیب۔ تُلِو میون اتھہٕ}\n9. تہٕ موسىٰ کٔر بنی اسرائیلس سٍتـ̡ یۅہے کتھ کرنہٕ، مگر تِمو کٔر نہٕ موسیٰ سٕندِ روحٕچ اذیت تہٕ ظالمانہٕ غلامی ہٕندِ خٲطرٕ بوز۔ {Anguish: Heb. کوتاہی، یا، تنگ پن}\n10. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن،\n11.\\tاژُن، مصر کِس بادشاہ فرعونس سٍتـ̡ کتھ کرٕن، یُس سُہ دِیہِ بنی اسرائیلـ̡ پنہٕ نِس زمینہٕ منزٕ نٮ۪بر نیرُن۔\n12. تہٕ موسىٰ وۆن خداوند سٕندِس برونہہ کُن کتھ زِ وُچھِو نہٕ بنی اسرٲیلِیو میانہِ کتھہِ بوزمٕژ۔ تیلہِ کِتھہ کٔنۍ بوزِ فرعون میہ یُس ختنہ نہ وُچھن وول چھُ۔\n13. تہٕ خداوند کٔر موسیٰ تہٕ ہارونس سٍتـ̡ کتھ تہٕ دِتُن تِمن بنی اسرٲیلِس تہٕ مصرٕکِس بادشاہ فرعونس سٍتـ̡ دِیُتُن زِ تِم کٔرِن بنی اسرائیل سٍتـ̡ مصر کِس سرزمینہٕ منزٕ نِنہٕ۔\n14.\\tیِم چھِ پننین مٲلن ہٕندِس گرن ہٕندِس سربراہ سٍتـ̡ روبن سٕندِ نیچوۍ، یُس اسرٲیلُک گۄڈنیُک زامُت چُھ؛ ہنوک، تہٕ پلو، ہیزرون تہٕ کارمی: یم {be} روبن سٕند خاندان۔\n15. تہٕ شمعون سٕندِ نیٚچوۍ۔ جیموئیل، تہٕ یامین تہٕ اوہد، تہٕ یَچن تہٕ زوہار، تہٕ شاؤل یُس کنعانی زنانہِ ہُند نیچو چھُ: یِم چھِ شمعون سٕندِ خاندان۔\n16.\\tتہٕ یِم چھِ لیوی سٕندٮ۪ن نیچوٮ۪ن ہٕندِ ناو، یِمن ہٕندِ نسلہٕ مُطٲبِق۔ گرشون، تہٕ کوہتھ، تہٕ میراری: تہٕ لیوی سٕنزِ زندگی ہٕندۍ ؤری ٲسۍ ہتھ ترہ ستھ ؤری۔\n17. گیرشون سٕندۍ نیٚچوۍ۔ لبنی تہٕ شِمی، تِہنٛدِ عیالَن مُطٲبِق۔\n18.\\tتہٕ کوہات سٕندِ نیٚچوۍ۔ امرام، تہٕ ازہر، تہٕ حبرون تہٕ عزیل: تہٕ کوہات سٕنزِ زندگی ہٕندۍ ؤری ٲسۍ ہتھ ترہ ترہ ؤری۔\n19.\\tتہٕ میراری سٕندِ نیچو۔ مہلی تہٕ موشی: یم {چِھ} پننہٕ نسلہٕ مطٲبق لیوی سٕندِ خاندان۔\n20.\\tتہٕ امرامن نیو أمِس مٲلہِ سٕنزِ بینہِ جوچبید زنانہٕ کٔرِتھ۔ تہٕ أمِس زاے ہارون تہٕ موسیٰ: تہٕ امرام سٕنزِ زندگی ہٕندِ ؤری ٲسۍ ہتھ ترہ ستھ ؤری۔\n21.\\tتہٕ ازہر سٕندِس نیٚچوۍ۔ کورہ، تہٕ نیفیگ، تہٕ زکری۔\n22. تہٕ عزیل سٕندِ نیچو۔ مشایل، تہٕ الزافان، تہٕ زیتھری۔\n23.\\tتہٕ ہارون نیو أمِس نشون سٕنزِ بینہِ امناداب سٕنز کورِ الیشبع زنانہٕ۔ تہٕ أمِس دِژ أمِس نادب، تہٕ ابیہو، الیعازر تہٕ اِتھمار۔\n24.\\tتہٕ کورہ سٕندِ نیچو۔ عسیر، تہٕ الکانہ، تہٕ ابیاصف: یم {چِھ} کورہین ہٕندۍ خاندان۔\n25. تہٕ الیعازر ہارون سٕندِ نیچِوِ بنیوو سُہ پُٹیئل سٕنزِ کورِ منزٕ اکھ زنانہٕ۔ تہٕ تٔمۍ دِژ أمِس فینہاس: یِم چھِ تِہندِ عیالہٕ مُطٲبق لاوی ہٕندِس مٲلِس سٕندِ کلہٕ۔\n26. یِم ہارون تہٕ موسیٰ یِمن ہٕندِس لشکرس مُطٲبق کٔرِو اسرٲیلِچ اولاد مصر کِس سرزمینہٕ منزٕ نیبر۔\n27.\\tیِم چھِ تِم یِم مصرٕکِس بادشاہ فرعونس سٍتـ̡ کتھ کٔرِتھ، یِم چھِ موسیٰ تہٕ ہارون۔\n28.\\tتہٕ سُہ سپُد تمہِ دۅہہ سپدُن یێلہِ خداوند مصر کِس سرزمینس مَنٛز موسىٰ سٕندِس سٍتـ̡ کتھ کٔر،\n29.\\tیُس خداوند موسیٰ سٍتـ̡ کتھ کٔرِتھ وونُن زِ بہٕ چُھس خداوند چُھس، سُہ کتھ کٔرِو مصرٕکِس بادشاہ فرعونس سٍتـ̡ یُس بہٕ ژے وَنُن چُھس۔\n30. تہٕ موسىٰ ووٚن خداوند سٕندِس برونہہ کُن، وُچھ بہٕ چُھس نہٕ ختنہ کرنہٕ آمُت، تہٕ فرعون کِتھہ کٔنۍ کرِ میانہِ کتھ بوزنہٕ؟","1. تہٕ خداوند ووٚن موسیٰ سٕندِس سٍتـ̡ وُچھمُت، مے بنوو ژے فرعونس خٲطرٕ دیوتا تہٕ ہارون تُہند بوے بنہِ تُہند پیغمبر۔\n2. یُس بہٕ چُھس حُکُم کَرُن تہٕ ہارون کَرِ تُہُند بٲے فرعونس سٍتـ̡ کتھ زِ سُہ سٍتـ̡ اِسرٲیلـ̡ پنہٕ نِس سرزمینہٕ منزٕ نیبر نیرُن۔\n3. تہٕ بہٕ کٔرٕ فرعون سُند دِل سخت، تہٕ کٔرٕ پنٕنۍ نشانہٕ تہٕ عجائبات مصر کِس سرزمینس مَنٛز۔\n4. مگر فرعون کرِ نہٕ تۅہہِ بوزُن، یُتھ بہٕ ہێکہٕ مصرس پیٹھ پنُن اتھہٕ تھٲوِتھ، تہٕ پنٕنۍ لشکر تہٕ پننین لوکن ہٕندِس بنی اسرٲیلِس بٔڈۍ فیصلن سٍتـ̡ مصر کِس سرزمینہٕ منزٕ نٮ۪بر کٔرِتھ۔\n5. تہٕ مصری گژھہِ معلوم زِ بہٕ چُھس خداوند چُھس، یێلہِ بہٕ مصرس پیٹھ پنُن اتھہٕ پھٔہلٲوِتھ تہٕ بنی اسرائیلٕچ اولاد تِمن منزٕ کڈِتھ کڈِ۔\n6. تہٕ موسیٰ تہٕ ہارونن کٔر خداوند سُند حُکُم تہٕ تِمو تہِ کٔر۔\n7. تہٕ موسیٰ اوس ژور وُہُر تہٕ ہارون اوس ژور وُہُر تہٕ تریہ وُہُر، ییلہ تمو فرعونس سٍتۍ کتھ کٔر۔\n8. تہٕ خداوند کٔر موسیٰ تہٕ ہارونس سٍتـ̡ وَنُن،\n9.\\tییلہ فرعون تۅہہِ سٍتـ̡ کتھ کرِ، تہٕ وَنُن تہٕ تُہٕندِس خٲطرٕ ہٲوِو اکھ معجزہٕ، تیلہِ گژھہِ ہارونس ونُن، پنٕنۍ لٔر رٔٹِتھ تہٕ تراوُن فرعونس برونہہ کُن، تہٕ سُہ گژھہِ ناگ بنہِ۔\n10. تہٕ موسیٰ تہٕ ہارون گٔیہِ فرعونس نِش، تہٕ یِمو کٔر خداوند سٕندِ حُکُم مُطٲبِق۔ تہٕ ہارونن ترٛٲو فرعونس برونہہ کُن تہٕ پننین خدمتگارن برونہہ کُن، تہٕ سُہ بنیوو ناگ۔\n11.\\tفرعونن بُلووُن دانا تہٕ جادوگر تہِ: وۅنۍ اوس مصرٕکۍ جادوگر تہِ یِتھے پٲٹھۍ پننین جادوگرن سٍتـ̡ کٔرِتھ۔\n12.\\tتکیازِ تِمو ترٛٲو پرٮ۪تھ أکِس انسانس پنٕنۍ لٔرۍ، تہٕ تِم بنییہِ ناگ، مگر ہارون سٕنزِ لٔرِ گِلہِ تِہٕنزِ لٔرۍ۔\n13.\\tتہٕ تٔمۍ کٔر فرعون سُند دِل سخٕت زِ تٔمۍ کٔر نہٕ تِمن ہٕنز کتھ بوزنہٕ۔ یتھہ پاٹھۍ رب اوس وونمُت۔\n14. تہٕ خداوند ووٚن موسیٰ سُند دِل چُھ سخٕت گومُت، سُہ چُھ لُکن تراونہٕ نِش انکار کران۔\n15. صُبحَس گژھ فرعونس نِش۔ لو، سُہ چُھ آبس کُن نیران۔ تہٕ تُہۍ گژھِو دریاو کِس بٹھس پیٹھ کھڑا أمِس یِنہٕ خٕلاف۔ تہٕ سُہ لٔر یُس ناگ بنیومُت اوس، سُہ رٔٹِو ژے اتھس منز۔\n16. تہٕ تُہۍ چُھہ أمِس وَنُن، عبرانین ہٕندِ خداہِ چُھہ مے ژے نِش سوزمُت، یہِ وَنُن زِ میانہِ لُکھ گژھ تراوُن، یُتھ تِم بیابانن مَنٛز میانہِ خدمتہٕ کٔرِتھ، تہٕ وُنہِ تام چُھہ نہٕ توے بوزان۔\n17. یِتھٕ پٲٹھۍ چُھ خداوند فرماوان، اَتھ مَنٛز گژھہِ ژے معلوم زِ بہٕ چُھس خداوند چُھس، یُس بہٕ دٔریاوس مَنٛز {چُھ} آبس پیٹھ لٔج دِنہٕ یُس {چُھ} چُھ، تہٕ یِم گژھن خونس منز تبدیل کرنہٕ۔\n18. تہٕ یُس گاڈٕ دریاوَس مَنٛز چُھہ مَرُن، تہٕ دٔریاوَس مَنٛز گژھہِ بدبو۔ تہٕ مصری گژھن دریاوُک آب چیٚنہٕ خٲطرٕ ناپسند۔\n19. تہٕ خداوند چُھ موسیٰ سٕندِس سٍتـ̡ وَنُن زِ پَنُن لٔر رٔٹِتھ تہٕ پَنُن اَتھٕ پھٔہلٲوِو مصر کِس آبس پیٹھ، تِہٕندِس نالن پیٹھ، تہندِس دریاوَن پیٹھ، تہٕ تِہندین سارِنٕے آبہٕ سٍتـ̡ یُتھ تِمن ہُند خون۔ تہٕ {یہ} سٲرۍسٕے مصرٕکِس سرزمینس منز ہیکہِ خوُن آسُن، لٔکرِ ہٕندِس برتن منز، تہٕ {کنن ہٕندِس برتن منز﴾۔ {پولس...: ہیب۔ تِہُند آبُک جمع کرُن}\n20. تہٕ موسیٰ تہٕ ہارونن کٔر خداوند سُند حُکُم۔ تہٕ تٔمۍ تُل لاٹھ، تہٕ لوٚگُن دریاوس منٛز، فرعون سٕندِس نظرس منٛز، تہٕ پننین خدمتگارن ہٕندِس نظرس منٛز۔ تہٕ دریاوس منز موجود سٲری آب آو خونس منز تبدیل۔\n21.\\tتہٕ سُہ گاڈ یُس دریاوس منز اوس، سُہ موٗد۔ تہٕ دٔریاوُک دٔرِیاو تہٕ مصری ہیوٚک نہٕ دٔریاوُک آب چِھتھ۔ تہٕ سٲرۍسٕے مصرٕچ سرزمینس منز اوس خون۔\n22. تہٕ مصرٕکۍ جادوگرو کٔر یہِ پننہِ طلسمو سٍتـ̡ تہٕ فرعون سُند دِل گۆو سخٕت، تہٕ تٔمۍ کٔر تِمن ہٕنز کتھ بوزنہٕ۔ یتھہ پاٹھۍ رب اوس وونمُت۔\n23. تہٕ فرعون گوٚو پھیُر تہٕ ژاو پننِس گرس منز، تہٕ نہ کٔر أمِس تہِ دِل دِنہٕ۔\n24.\\tتہٕ سارِوٕے مصری کٔر دریاوس اندۍ پکھۍ آب چنہٕ خٲطرٕ۔ تکیازِ تِم ہیوٚک نہٕ دریاوُک آب چیٚتھ۔\n25. تہٕ سَتھ دۅہ گٔیہِ پوٗرٕ، تمہِ پتہٕ اوس خداوند دٔریاوس دٔرِتھ۔","1. تہٕ خداوند کٔر موسیٰ سٍتـ̡ کتھ زِ فرعونس نِش گژھ تہٕ أمِس وَنُن، یِتھٕ پٲٹھـ̡ چُھ خداوند ونان زِ میانہِ لُکھ گژھ یُتھ تِم میانہِ خدمت کٔرِتھ۔\n2. تہٕ اگر ژے یِمن تراوُن نِش انکار کٔرِو، وُچھِو بہٕ ژےٚ سارِنٕے سرحدن نِلہٕ مۄنٛڑجہِ سٍتـ̡ مارٕ دِنہٕ:\n3. تہٕ دٔریاو نیلہٕ نِلہٕ نِلہٕ وارِیاہ نِلہٕ نیلہٕ، یِم تُہٕندِس گَرَس مَنٛز، تہٕ تُہٕندِس بسترس منز، تہٕ تُہٕندِس بسترس منز، تہٕ تُہٕندِس بسترَس مَنٛز، تہٕ تُہٕندِس بسترَس مَنٛز، تہٕ تُہٕندِس بسترَس مَنٛز۔\n4. تہٕ نِلہٕ مۄنٛڑجہِ یِن تۅہہِ پیٹھ، تہٕ تُہٕندِس لوکَس پیٹھ، تہٕ تُہٕندِس سارِنٕے خادمَن پیٹھ۔\n5. تہٕ خداوند کٔر موسیٰ ہس سٍتـ̡ کتھ زِ ہارونس وَنُن زِ پَنُن لٔر پَنُن لٔر پَنُن اَتھٕ کٔرِتھ نالن پیٹھ، دریاوَن تہٕ تالابَن پیٹھ، تہٕ نِلہٕ مۄنٛڑجہِ ہٲوِن مصر کِس سرزمینس پیٹھ۔\n6. تہٕ ہارونن تروو مصر کِس آبس پیٹھ پنُن اتھہٕ۔ تہٕ نِلہٕ مۄنٛڑجہِ آیہِ تہٕ لٔگِتھ مصرٕچ سرزمین۔\n7. تہٕ جادوگرو کٔر یہِ پننہِ جادو سٍتۍ، تہٕ أنِکھ مصرٕچ سرزمینس پیٹھ نِلہٕ مۄنٛڑٕ۔\n8. اَمہِ پَتہٕ کٔر فرعونن موسیٰ تہٕ ہارونس بُلاونہٕ تہٕ ووٚنُن، خداوند کٔرِو دُعا زِ سُہ کٔرِن میانہِ نِش تہٕ میانین لوکن نِش نِش نِلہٕ نِنہٕ۔ تہٕ بہٕ دِیہٕ لوٗکن تراوُن، یُتھ تِم خداوند سٕندِ خٲطرٕ قربانی دِن۔\n9.\\tتہٕ موسىٰ ووٚن فرعونس زِ میانہِ خٲطرٕ کٔر بہٕ ژے تہٕ چانہِ خدمتگارن تہٕ تہندٮ۪ن لوکن ہٕندِ خٲطرٕ کٔرٕ ژےٚ نِلہٕ تہٕ تُہٕندِس گَرَن ہٕندِس نِلہٕ مۄنٛڑجہِ تباہ کرنہٕ خٲطرٕ، یُتھ زن تِم دریاوس مَنٛز روزن۔ {عظمت...: یا، یہ عزت تھاو میہ پیٹھ، وغیرہ} {کب: یا، کَمہِ خٕلاف} {تباہ کرنہٕ خٲطرٕ: ہیب۔ کَٹُن کَرُن}\n10.\\tتہِ ووٚن پگہہ تام۔ تہٕ تٔمۍ ووٚن، {یہِ} تہٕ تُہٕندِس کلامَس مُطٲبِق: یُتھ ژے زانہِ زِ {چُھہ} چُھہ نہٕ سٲنِس خداہس ہیوٗ کانہہ تہِ۔ {پوٚت کُن: یا، پوٚگس خلاف }\n11. تہٕ نِلہٕ نِلہٕ نِش تہٕ تُہٕندِس گَرَو نِش، تہٕ تُہٕندِس خادمَن نِش تہٕ تُہٕندِس لُکہٕ نِش نیرٕنۍ۔ تِم روزن صرف دریاوس منز۔\n12. تہٕ موسیٰ تہٕ ہارون درٛاو فرعونس نِش تہٕ موسیٰ کٔر فرعونس نِش نِنہٕ آمٕژ نِلہٕ مۄنٛڑجہِ سٍتۍ۔\n13. تہٕ خداوند کٔر موسیٰ سٕندِ کلامَس مطٲبق۔ تہٕ نِلہٕ مۄنٛڑجہِ موٗدۍ گَرَو منٛز، گامو منٛزٕ تہٕ کھہَو منٛز۔\n14.\\tتہٕ تِمو جمع کٔرِتھ تِم ڈھیرن پیٹھ جمع تہٕ زمینہٕ گٔیہِ بدبو۔\n15.\\tمگر ییلہ فرعونن وُچھ مہلت میلہِ، تٔمۍ کٔر پنُن دِل سخٕت تہٕ تِمن بوزُن نہٕ۔ یتھہ پاٹھۍ رب اوس وونمُت۔\n16. تہٕ خداوند ووٚن موسیٰ سٕندِس نِش زِ ہارونس وَنُن پَنُن لٔر پھٔہلٲوِتھ تہٕ زمینہِ ہٕندِس مٔژِس سٍتـ̡ ژٔٹِھتھ یُتھ سٲرۍسٕے مصرٕچ زمینہٕ سٍتـ̡ جوُن بٔنِتھ۔\n17. تہٕ تِمو کٔر یہِ۔ تکیازِ ہارون کٔر پنُن اتھہٕ پننہِ لٔرِ سٍتـ̡ تہٕ دِژُن زمینہِ ہٕنزِ گردِ تہٕ سُہ بنیوو انسانس تہٕ درندس مَنٛز جوُن۔ سٲرۍسٕے مصرٕچ زمینہٕ بنییہِ سٲرۍسٕے سرزمینس منز جوُن۔\n18.\\tتہٕ جادوگرو کٔر پننیو جادوو سٍتۍ جوُن نیرنہٕ خٲطرٕ، مگر تِم ہیوٚک نہٕ ہیوٚک: یِتھے پٲٹھۍ ٲسۍ انسانس پیٹھ تہٕ درندن پیٹھ جوُن۔\n19. اَمہِ پتہٕ ووٚن جادوگرو فرعونس زِ یہِ چُھ خدایہِ سٕنز اوٚنٛگٕج تہٕ فرعون سُند دِل گوٚو سخٕت تہٕ تٔمۍ کٔر نہٕ تِمن ہٕنز کتھ بوزنہٕ۔ یتھہ پاٹھۍ رب اوس وونمُت۔\n20.\\tتہٕ خداوند ووٚن موسیٰ سٕندِس سُلہِ وۅتھُن تہٕ فرعونس برونہہ کُن کھڑا گژھُن۔ لو، سُہ چُھ آبس کُن نیران۔ تہٕ أمِس وَنُن چُھ، یِتھٕ پٲٹھۍ چُھ خداوند ونان زِ میانہِ لُکھ گژھ یُتھ تِم میانہِ خدمت کٔرِتھ۔\n21. نتہٕ اگر نہٕ ژے میانین لوکن تراوُن، وچھ بہٕ ژے پیٹھ، تہٕ پننین خادمَن پیٹھ، تہٕ پننین لوکن پیٹھ، تہٕ تہندین گھرن پیٹھ، تہٕ مصرین ہٕندِ گرٕ گژھن جھنڈو سٍتۍ بٔرِتھ، تہٕ تتھ زمینس پیٹھ تہِ یِم [چھِ}۔ {swarms...: یا، شورن ہند مرکب بیترِ}\n22. تہٕ بہٕ ژٔٹِتھ تمہِ دۅہہٕ گوشنُک سرزمین، یَتھ مَنٛز میانہِ لُکھ روزان چھِ، یُتھ نہٕ کانہہ تہِ جھنڈ آسہِ۔ ٲخرس تام گژھہِ ژیہ پتاہ زِ بہٕ چُھس زمینس منز خداوند ۔\n23. تہٕ بہٕ کٔرٕ پننین لوکن تہٕ تہندٮ۪ن لوکن درمیان اکھ تقسیم: پگہہ گژھہِ یہ نشانہٕ۔ {اکھ تقسیم: ہیب۔ اکھ نجات } {پوٚت کُن: یا، بذریعہ مورو}\n24. تہٕ خداوند کٔر یہِ ۔ تہٕ فرعون سٕندِس گرس منز، تہٕ تٔمۍ سٕندٮ۪ن نوکروں ہٕندِس گرس منز، تہٕ سارِنٕے مصرٕکِس سرزمینس مَنٛز، یہِ زمین گٔیہِ مَژٕ سٍتـ̡ خراب گٔیہِ۔ {کرپٹڈ: یا، تباہ گومُت}\n25. تہٕ فرعونن بُلوو موسیٰ تہٕ ہارونس تہٕ وونُن، گژھ زمینس منز پننِس خداہس خٲطرٕ قربانی۔\n26.\\tتہٕ موسىٰ ووٚن زِ یہ کرُن چُھہ نہٕ پورٕ سپدان۔ تِکیازِ أسۍ کٔرِو مصرن ہٕنز مکروہ قربانی یُس خداوند پننِس خداہس سٍتـ̡ قربان کٔرِتھ، تہٕ کیا تِم کٔرِو نہٕ اسہِ کٔنہِ کٔرِتھ؟\n27. أسۍ گژھو ترٚین دوہن ہُند سفر بیابانس مَنٛز، تہٕ یِتھ کٔنۍ سُہ اسہِ حُکُم کرِ۔\n28. تہٕ فرعونن ووٚن، بہٕ تراوٕ ژے تراوُن، یُتھ ژٕ بیابانس مَنٛز خداوند پنُن خدایہ سٕندِ خٲطرٕ قربان کٔرِتھ۔ صرف ژیہ گژھ نہ زیادہ دور گژھتھ: میانہِ خاطرہ کرو التجا ۔\n29. تہٕ موسىٰ ووٚن زِ وُچھ، بہٕ ژےٚ نِش نیران، تہٕ بہٕ کَرٕ خداوند سٕندِس نِش درخواست زِ فرعونس نِش، تٔمۍ سٕندِس خادمَن نِش تہٕ تٔمۍ سٕندِس لُکہٕ نِش گژھن پگہہ تام نیرُن، مگر فرعون گژھِ نہٕ مزید دھوکہ دِتھ زِ لُکن گژھہِ نہٕ خداوند سٕندِ خٲطرٕ قربانی کرنہٕ خٲطرٕ۔\n30. تہٕ موسیٰ دراو فرعونس نِش تہٕ کٔرٕن خداوند سٕنز التجا ۔\n31. تہٕ خداوند کٔر موسیٰ سٕندِ کلامَس مطٲبق۔ تہٕ تٔمۍ کٔر فرعونس نِش، پننین خدمتگارن تہٕ پننین لوکن نِش مکھٮ۪ن ہٕندۍ جھنڈ ہٹۍ۔ اکھ تہِ روٗد نہٕ۔\n32.\\tتہٕ فرعونن کٔر امہِ وِزِ تہِ پنُن دِل سخت، تہٕ نہ دِژ سُہ لُکن نیرُن۔","1. تێمہِ پَتہٕ خداوند ووٚن موسیٰ سٕندِس نِش گژھ فرعونس نِش، تہٕ وَنُن زِ یِتھٕ پٲٹھۍ چُھ عبرانین ہُند خدا، میانین لُکن گژھن یُتھ تِم میانہِ خدمت کرن۔\n2. تکیازِ اگر ژیہ تمن تراونس انکار کرِ، تہٕ تمن تھپھ کٔرِتھ،\n3.\\tوُچھِو خداوند سُند اَتھٕ چُھہ تُہٕندِس چارواین پیٹھ، یُس کھاہس مَنٛز، گُرَن پیٹھ، گُرَن پیٹھ، اونٹن پیٹھ، بیلن پیٹھ، تہٕ دانٛدن پیٹھ، {اتہِ آسہِ} سٮ۪ٹھاہ خوفناک موران۔\n4. تہٕ خداوند کرِ اسرٲیلٕکۍ چارواین تہٕ مصرٕکۍ چارواین درمِیان ژٹُن، تہٕ اِسرٲیلٕکۍ بچہٕ سارِنٕے سٍتـ̡ گژھِ نہٕ کانہہ تہِ مَرُن۔\n5.\\tتہٕ خداوند کوٚر اکھ مقرر وقت مقرر کٔرِتھ یہِ ونُن زِ پَگہہ خداوند کرِ یہِ کٲم زمینس مَنٛز۔\n6.\\tتہٕ خداوند کٔر پگہٕ سٍتـ̡ یہِ کٲم تہٕ مصرٕکۍ سارِنٕے چاروٲے موٗد، مگر بنی اسرٲیلـ̡ ہٕندِس چارویو سٍتـ̡ موٗد نہٕ اکھ تہِ۔\n7. تہٕ فرعونن سوٗز، تہٕ وُچھ اوس نہٕ اسرٲیلِیو ہٕندِس چارواین منز کانہہ تہِ موٗدمُت۔ تہٕ فرعون سُند دِل گوٚو سخت، تہٕ تٔمۍ دِژ نہٕ لُکن یلہٕ۔\n8. تہٕ خداوند ووٚن موسیٰ تہٕ ہارونس زِ پانس نِش نِو بھٹہٕ ہٕندِ سوٗر تہٕ موسیٰ دِیُن فرعونس سٕندِس نظرس منز آسمانس کُن چھُکُن۔\n9.\\tتہٕ یہِ گژھہِ سارِنٕے مصرٕچ سرزمینس مَنٛز لۄکٕٹ گرد بنہِ، تہٕ سٲرۍسٕے مصرٕچ سرزمینہٕ سٍتـ̡ انسانس تہٕ درندَس سٍتـ̡ پھٔٹِتھ پھٔہلِتھ بٔنِتھ۔\n10. تہٕ تِمو رٔٹِتھ بٹھہِ ہُند سوٗر تہٕ کھٔڑۍ فرعونس برونہہ کُن۔ تہٕ موسیٰ کٔر یہِ آسمانس کُن چھُکُن۔ تہٕ یہ بنیوو انسانس تہٕ درندس پیٹھ پھٔٹتھ پھٔٹۍ۔\n11. تہٕ جادوگر ہیوٚک نہٕ موسیٰ سٕندِس برونہہ کُن کھڑا گٔژھِتھ۔ تکیازِ یہ پھۅپھ اوس جادوگرن تہ سارنٕے مصرین پیٹھ۔\n12. تہٕ خداوند کٔر فرعون سُند دِل سخٕت تہٕ تٔمۍ کٔر نہٕ تِمن ہٕنز کتھ بوز۔ یِتھ کٔنۍ خداوند اوس موسیٰ سٕندِس سٍتـ̡ کتھ کٔرمٕژ۔\n13. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ صبحٲے وۅتھان تہٕ فرعونس برونہہ کُن کھڑا گژھُن تہٕ أمِس وَنُن یِتھٕ پٲٹھۍ چُھ عبرانین ہُند خدا، میانہِ قوم گژھن یُتھ میانہِ خدمت کرٕنۍ۔\n14.\\tکیازِ بہٕ سوز اتھ وِزِ پنٕنۍ سٲری آفت چانہِ دِلس پیٹھ، تہٕ چانہِ خدمتگارن تہٕ تہندِس لوکن پیٹھ۔ تاکہ ژیہ گژھہِ پتاہ زِ سارِنٕے زمینس منز چھہ نہ میہ ہیو کانہہ تہِ۔\n15. فی الحال بہٕ پَنُن اَتھٕ بڑاوُن، یُتھ بہٕ ژے تہٕ تُہٕندِس لُکن ہٕندِس وَباہٕ سٍتـ̡ مارٕ دِتھ۔ تہٕ ژیہ گژھہِ زمینہِ نِش ژٹنہٕ۔\n16.\\tتہٕ اَمہ کامہِ سٍتـ̡ چُھہ میہ ژے تُلِتھ تُلِتھ تہٕ ژے پنُن طاقت ہاونہٕ مۅکھہٕ۔ تہٕ یہ زِ میون ناو گژھہِ سٲرۍسٕے زمینس منز اعلان کرنہٕ۔ {بٔرِتھ...: ہیب۔ تم کھڑا کٔرتھ}\n17.\\tتوے چھکھ میانین لوکن خلاف پنُن پان بلند کران، یُتھ نہٕ تِمن تراوُن؟\n18.\\tوچھو پگہہ امہ وقتہ بہٕ اَتھ سٍتـ̡ سٮ۪ٹھاہ سٮ۪ٹھاہ ژالہ پیوٚو، یُس نہٕ مصرس مَنٛز وُنیُک تام اوسُکھ نہٕ۔\n19. لہذا سوز وۅنۍ پنُن چاروٲے تہٕ یُس تہِ کھاہس منز موجود چھُ، جمع کرُن۔ {تکیازِ} پریتھ انسان تہٕ جانور یُس میدانس منز لبنہٕ ییہِ، تہٕ یِم یِن نہٕ گرٕ اننہٕ، تِمن پیٹھ پیٚیہِ ڈولہٕ تہٕ تِم مرن۔\n20. یُس فرعون سٕندِس خادمَن مَنٛز خداوند سٕندِس کلامَس سٍتـ̡ خوفزدہ گوٚو، تٔمِس کٔرِن پنٕنـ̡ خادمَن تہٕ تٔمۍ سٕندِس چاروٲے گَرَن مَنٛز ژٔلِتھ:\n21.\\tیُس نہٕ خداوند سٕندِس کلامَس سٍتـ̡ پى۪ٹھ {غور کرنہٕ آمُت...: ہیب۔ تٔمۍ سُند دِل کٔرِو نہٕ تھاوُن}\n22. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ پَنُن اَتھٕ اسمانس کُن پھٔہلٲوِتھ یُتھ سٲرۍسٕے مصرٕکِس سرزمینس مَنٛز، انسانس پیٹھ، تہٕ درندَس پیٹھ، تہٕ کھہٕ کِس پرٮ۪تھ کُنہِ\n23. تہٕ موسیٰ کٔر پنٕنۍ لٔر آسمانس کُن تہٕ خداوند دِژ گرٛاے تہٕ ڈولہٕ تہٕ نار ووت زمینس پیٹھ۔ تہٕ خداوندَن ووت مصرٕکِس سرزمینس پیٹھ ڈولہٕ برس۔\n24.\\tیێلہِ گۆو ژالہ تہٕ نار رٔلِتھ گۆو سٮ۪ٹھاہ خوفناک، یُتھ زن سٲرۍسٕے مصرس منز اوس نہٕ یُتھ کانہہ تہِ قوم بنیوو۔\n25.\\tتہٕ ووت سارِنٕے مصرٕچ زمینہٕ سٲرۍسٕے سٍتـ̡ یُس میدانس مَنٛز اوس، انسان تہٕ جانور دِنہٕ۔ تہٕ ڈولہٕ لوٚگ کھہٕ کِس پرٮ۪تھ کُلِس تہٕ کھہہٕ کِس پرٮ۪تھ کُلِس لٔگِتھ۔\n26.\\tصرف گوشن کِس سرزمینس منز، ییتہِ بنی اسرائیل ٲس، اوس نہٕ کانہہ ڈولہٕ۔\n27. تہٕ فرعونن سوٗز، تہٕ موسیٰ تہٕ ہارونس بُلووُن تہٕ تِمن وونُن، مے چُھ یمہِ لٹہِ گۅناہ کورمُت: خداوند چُھہ نیک تہٕ بہٕ تہٕ میٲنۍ قوم چِھہ بدکار۔\n28.\\tخداوند سٕندِس سٍتـ̡ کٔرِو (یێلہِ {یہِ} سٍتـ̡ سٍتـ̡ گُرجہٕ تہٕ ژلہٕ سٍتـ̡ گٔژھِتھ تہٕ ژٔلِتھ گٔژِھھتھ تہٕ ژٔلِتھ گٔژِھھ تہٕ بہٕ تراوٕ ژےٚ نیرُن، تہٕ ژٕ روزٕ نہٕ وۄنۍ روزُن۔ {mighty...: Heb. خدایہ سٕنز آواز}\n29. تہٕ موسىٰ ووٚن أمِس زِ یێلہِ بہٕ شہرٕ نیبر نیرِ، بہٕ پھٔہلِتھ پَنُن اَتھٕ خداوند سٕندِ خٲطرٕ۔ {تہٕ}گرٛاے گژھہِ بند، نہ گژھہِ بییہ کانہہ ڈولہٕ۔ یێلہِ ژے زانہِ زِ زمین کِتھہ پٲٹھـ̡ چُھہ خداوند سٕنز۔\n30. مگر ژے تہٕ تُہٕندِس خادمَن ہٕندِس سٍتـ̡ چُھہ بہٕ زانان زِ تُہہِ چُھہ نہٕ وُنہِ تہِ خداوند خدایہِ سٕندِ سٍتـ̡ کھوژان۔\n31.\\tتہٕ وُشتہٕ تہٕ وُشکہٕ آو دِنہٕ: تکیازِ وُشکہٕ اوس کنس منز، تہٕ کُنہِ\n32.\\tمگر کٕنُک تہٕ کُنُک گٔیہِ نہٕ مارنہٕ: تِکیازِ تِم ٲسۍ نہٕ بٔڈۍ گٔمٕتۍ۔ {نہ بڑیوم...: ہیب۔ پوشیدہ یا اندھیر}\n33. تہٕ موسیٰ دراو فرعونس نِش شہرٕ نیبر، تہٕ پَنُن اتھہٕ پھٔہلٲوِتھ خداوند کُن، تہٕ گرٛاے تہٕ ڈولہٕ ووت تہٕ زمینس پیٹھ ووت نہٕ روٗد۔\n34. تہٕ ییلہ فرعونن وُچھ روٗد تہٕ ڈولہٕ تہٕ گرٛاے بند گٔیہ، تٔمۍ کٔر بییہ تہِ گۅناہ تہٕ کوٚرُن پنُن دِل سخت۔\n35. تہٕ فرعون سُند دِل گوٚو سخت، تہٕ نہ دِژ سُہ بنی اِسرٲیلِس نیرُن۔ یِتھ کٔنۍ خداوند اوس موسیٰ سٕندِ کتھ کٔرمٕژ۔ {از موسیٰ: ہیب۔ موسیٰ سٕندِ اتھہٕ سٍتۍ}","1. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ گژھ فرعونس نِش اژُن، یێلہِ مے چُھس تٔمۍ سُند دِل تہٕ تٔمۍ سٕندِس خادمَن ہُند دِل سخٕت کورمُت، یُتھ بہٕ ہٲوِتھ پنٕنـ̡ نشانہٕ أمِس برونہہ کُن ہٲوِتھ:\n2. تہٕ یُتھ تہٕ ژٕ پننِس نیچوِس تہٕ پننِس نیچوِس سٕندِس نیچوِس کِس کنن مَنٛز ؤنِتھ زِ مے کیا کٔرِمٕژ مصرس مَنٛز کٔرمٕژ تہٕ میٲنۍ نشانہٕ یِم مے تِمن مَنٛز کٔرمٕژ چھِ۔ یێلہِ ژیہ زانہِ زِ بہٕ کِتھہ پٲٹھـ̡ چُھس خداوند چُھس۔\n3. تہٕ موسیٰ تہٕ ہارون آیہِ فرعونس نِش، تہٕ وونُن تٔمِس یِتھٕ پٲٹھۍ چُھہ عبرانِیَن ہُند خدا، یێلہِ کُنہِ کالس کٔرِو ژے میانہِ برونہہ کُن عاجزی کرنہٕ نِش انکار۔ میانین لوکن گژھن گژھن، تاکہ تم گژھن میانہِ خدمت۔\n4.\\tنتہٕ اگر ژے میانین لوکن نیرنس انکار کٔرِتھ، وچھ بہٕ پگہہ تہٕ بہٕ اَننہٕ ٹِڈی پننہِ ساحلس پیٹھ۔\n5. تہٕ تِم کرِ زمینہِ ہٕندِس بُتھِس ؤلِتھ، یُس نہٕ زمینہٕ وُچھِتھ ہێکہ، تہٕ تِم کھٮ۪ن تُہٕندِس باقیاتس سٍتـ̡ یُس ژۅہہِ ہٕندِ خٲطرٕ کھٮ۪نہٕ آمُت چُھ، تہٕ کھٮ۪وان پرٮ۪تھ کُلِس یُس تۅہہِ خٲطرٕ کھٮ۪نہٕ آمُت چُھ: {بُتھ: ہیب۔ أچھ}\n6. تہٕ تِم بٔرِن تُہٕندِس گَرَس تہٕ تُہٕندِس سارِنٕے خادمَن ہٕندِس گَرٕ تہٕ سارِنٕے مصری ہٕندِس گَرٕ سٍتـ̡ بٔرِتھ۔ یُس نہ تہندیو مٲلو تہٕ نہ تہندین مٲلن ہٕندیو مٲلو وُچھمُت چُھ، تمہ دۅہہ پیٹھٕ ییلہ تم از تام زمینس پیٹھ ٲسۍ۔ تہٕ سُہ پھیُر پان تہٕ فرعونس نِش درٛاو۔\n7.\\tتہٕ فرعون سٕندٮ۪و خادمَو ووٚن أمِس زِ یہِ نفر کٲتِس کالس روزِ اسہِ ہٕندِ خٲطرٕ جال۔ یێلہِ تِم گژھن خداوند سٕندِس خدایہِ سٕنزِ خدمت: کیا ژے چُھہ نہٕ وُنیُک تام پتاہ زِ مصر چُھ تباہ گومُت؟\n8. تہٕ موسیٰ تہٕ ہارون آو فرعونس نِش دُبارٕ اننہٕ، تہٕ تٔمۍ ووٚن تِمن نِش گٔژھِو، یِم کُس چھِ نیرن؟ {کُس...: ہیب۔ کُس تہٕ کُس وغیرہ}\n9. تہٕ موسیٰ ووٚن زِ أسۍ گژھو پننین بچن تہٕ بُزرگَن سٍتۍ، پننین نیچوٮ۪ن تہٕ کورٮ۪ن سۭتۍ، پننین چاروَن تہٕ پننین چاروَن سٍتۍ۔ تکیازِ اسہِ پزِ خداوند سٕندِ خٲطرٕ دعوت منعقد۔\n10.\\tتہٕ تٔمۍ ووٚن تِمن سٍتـ̡ خداوند تہٕ یێلہِ بہٕ تہٕ تُہٕندِس لۄکٹِس سٍتـ̡ یێلہِ دِیہِ تہٕ تێہٕندِس لۅکٹِس سٍتـ̡ وُچھِو۔ تکیازِ بد {چُھ} چُھہ تۅہہِ برونہہ کُن۔\n11.\\tتۂ نہٕ: وۅنۍ گژھو تم {یُس} انسان، تہٕ خداوند سٕنز خدمت کرو۔ امہ مۅکھہ ٲس ژیہ یژھان۔ تہٕ تِم کٔرِکھ فرعون سٕنزِ موجودگی نِش کڑنہٕ۔\n12. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ پَنُن اتھہٕ مصرٕچ زمینہِ پیٹھ پھٔہلٲوِتھ یُتھ زن تِم مصر کِس سرزمینس پیٹھ یِن تہٕ یِم تہٕ یُس ژۅکہٕ وُچھمُت چُھ، سُہ تہِ کھٮ۪ن۔\n13.\\tتہٕ موسیٰ کٔر پنٕنۍ لٔر مصرٕچ زمینس پیٹھ، تہٕ خداوند اوٚن تمہِ سارِوٕے دۅہہٕ تہٕ سارِنٕے رٲژ زمینس پیٹھ مشرقُک واو۔ {تہٕ} ییٚلہِ صُبح اوس، مشرقی واو أنۍ ٹِڈِ۔\n14.\\tتہٕ ٹِڈی گٔیہِ مصرٕکِس سارِنٕے سرزمینس پیٹھ تہٕ مصر کِس سارِنٕے ساحلن مَنٛز آرام کٔرِتھ: سٮ۪ٹھاہ غمگسار ٲسۍ۔ تِمن برونہہ ٲس نہٕ تِمن ہِش ٹِڈی تہٕ نہ یِمن پتہٕ یِژھ آسہِ۔\n15.\\tتکیازِ تِمو اوس سٲرۍسٕے زمینہِ ہُند بُتھ ؤلِتھ تہٕ زمینہٕ گٔیہِ گٔیہِ۔ تہٕ تِمو کھیوٚو زمینُک پرٮ۪تھ کُلۍ تہٕ کُلٮ۪ن ہُند سٲری پھل یِم ڈولہٕ ترٲومٕتۍ ٲسۍ، تہٕ سٲرۍسٕے مصرٕچ سرزمینس منز اوس نہٕ کُلٮ۪ن یا کھاہن ہٕندِس جڑی بوٹین منز کانہہ سبز چیز رودمُت۔\n16. اَمہِ پَتہٕ کٔر فرعونن جلدی کٔرِتھ موسیٰ تہٕ ہارونس بُلاونہٕ۔ تہٕ تٔمۍ ووٚن، میہ چُھہ خداوند تہندِس خداہس سٍتـ̡ تہٕ ژے سٍتـ̡ گۅناہ کورمُت۔ {وننہٕ آمُت: ہیب۔ کال کرنس منز جلدی کٔرتھ}\n17. تێمہِ کِنۍ کٔرِو معاف، بہٕ چُھس ژے پنُن گۅناہ صرف اَکہِ لٹہِ دُعا کٔرِتھ، تہٕ خداوند پنُن خدایہ سٕندِس سٍتـ̡ دُعا کٔرِتھ زِ سُہ کرِ میانہِ نِش یہ موت، یُس صرف یہِ موت نِش نِش نِنہٕ۔\n18.\\tتہٕ سُہ دراو فرعونس نِش تہٕ کٔرٕن خداوند سٕنز التجا ۔\n19.\\tتہٕ خداوند کٔر اَکھ زبردست مغرِبی واو یٔمۍ ٹِڈی نِتھ تہٕ ترٛٲوِن بحرِ احمرس مَنٛز۔ مصر کین تمام ساحلن منز رود نہٕ اکھ ٹِڈی تہِ۔ {کاسٹ: ہیب۔ بند}\n20. مگر خداوند کٔر فرعون سُند دِل سخت، یُتھ زن سُہ دِیہِ نہٕ بنی اِسرٲیلِس تراوُن۔\n21. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ پَنُن اَتھٕ اسمانس کُن، یُتھ زن مصرٕکِس سرزمینس پؠٹھ انہِ گوٚٹ آسہِ، یُس تہِ گژھہِ محسوٗس کرنہٕ۔ {حتیٰ کہ...: ہیب۔ تاکہ کٲنسہِ گژھہِ انہِ گوٚٹ محسوس کرنہٕ}\n22. تہٕ موسىٰ کٔر اسمانس کُن اتھہٕ۔ تہٕ مصر کِس سارِنٕے سرزمینس منز اوس تریہ دۅہہٕ گٔنۍ گوٚٹ گوٚٹ:\n23.\\tتِمو وُچھ نہٕ اَکھ أکِس أکِس سٍتـ̡ تہٕ نۂ وُچھ تٔمِس جایہ ترٚین دۅہن تام، مگر سارِنٕے بنی اِسرٲیلِس ہٕندِس مکانس مَنٛز گاش ٲس۔\n24. تہٕ فرعونن بُلوو موسیٰ ہس تہٕ ووٚنُن، گژھ خداوند سٕنز عبادت کرٕنۍ۔ صرف گژھن پنٕنۍ کھورِ تہٕ پنٕنۍ کھیٚلہٕ روزٕنۍ: پنٕنۍ لۄکٹۍ تہِ گژھن پانس سۭتۍ۔\n25. تہٕ موسىٰ ووٚن زِ ژے پزِ اسہِ قربانی تہٕ زالنہٕ نذرانہ تہِ دِنۍ، یُتھ أسۍ پننِس خداہس سٍتـ̡ قربان کٔرِتھ۔ {اس: ہیب۔ سانہِ اتھس منز}\n26. سانہِ چارو تہِ گژھن اسہِ سٍتۍ۔ کُنہِ کھُر گژھہِ نہ پتھ کُن تراوُن۔ تکیازِ اسہِ پزِ پننس خدایہ سٕنز خدمت کرٕنۍ۔ تہٕ أسۍ چھِنہٕ پتاہ زِ اسہِ کیاہ سٍتـ̡ پزِ رب سٕنز خدمت کرٕن، یوتام نہٕ أسۍ تتہِ وٲتِو۔\n27.\\tمگر خداوند کٔر فرعون سُند دِل سخٕت تہٕ سُہ دِژ نہٕ تِمن نیرُن۔\n28.\\tتہٕ فرعونن ووٚن أمِس زِ ژے نِش نِش نیرُن، پانس نِش گژھ ہوشیار تہٕ وُچھُن نہٕ میون بُتھ ۔ تکیازِ تمہِ دۅہہ ژیہ میون بُتھ وچھان چھکھ ژے مرُن۔\n29. تہٕ موسىٰ ووٚن ژے چُھہ رٔژ کتھ کٔرمٕژ، بہٕ وُچھٕ نہٕ تُہند بُتھ دُبارٕ وُچھان۔","1. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ تہٕ بہٕ اَنہٕ فرعونس تہٕ مصرس پیٹھ اَکھ وُپھ۔ امہ پتہ دِیہ سُہ ژیہ یێلہِ دِیہِ، سُہ دِیہِ یێلہِ ژیہ یێلہِ دِیہِ، سُہ دِیہِ یێلہِ کُنہ\n2.\\tوۅنۍ کرو لوکن ہندین کنن منز کتھ تہ پریتھ مرد گژھہِ پننس ہمساین تہ ہمساین ہٕنزِ زنانہِ ہٕندِس زیورات تہٕ سۄنہٕ سٕندِ جواہرات نِنہٕ۔\n3. تہٕ خداوند دِژ مصرن ہٕندِس نظرس منز لوکن پیٹھ عنایت ۔ امہِ علاوہ اوس موسیٰ سُند انسان مصر کِس سرزمینس منز، فرعون سٕندِس خادمَن ہٕنزِ نظرِ تہٕ لُکن ہٕندِس نظرس منز سٮ۪ٹھاہ بٔڈ۔\n4. تہٕ موسىٰ ووٚن یِتھٕ پٲٹھۍ چُھس خداوند فرماوان زِ نصف رٲژ گژھہٕ بہٕ مصرس مَنٛز نیران۔\n5. تہٕ مصرٕچ سرزمینس مَنٛز سارِوٕے گۅڈٕ زامُت یُس فرعون سٕندِس تختس پیٹھ بِہِتھ چُھ، حتیٰ کہ گِلہِ پَتہٕ بِہنہٕ وٲلِس نوکرِ سٕندِس گۄڈنِکِس زامتس تام۔ تہٕ سارِنٕے درندَن ہٕندِس گۄڈنِکِس زامُت۔\n6.\\tتہٕ سٲرۍسٕے مصرٕچ سرزمینس منز گژھہِ اکھ بٔڈ فریاد یُتھ زن نہ کانہہ تہِ اوس تہٕ نہ آسہِ امہِ ہیوٗ تہِ۔\n7.\\tمگر بنی اسرائیل کِس کُنہِ تہِ سٍتـ̡ ہُند ہُرراوُن، انسانس یا درندس خلاف، یُتھ تۅہہِ زانہِ زِ خداوند کِتھہ پٲٹھـ̡ چُھ مصری تہٕ اسرٲیلِس درمیان فرق کران۔\n8.\\tتہٕ یِم سٲری خادم گژھن میانہِ نِش بۄن تہٕ میانہِ برونہہ کُن سجدہ کٔرِتھ ونُن، ژے نیٚبر نیرِو، تہٕ یِم سارِنٕے لُکھ یِم تۅہہِ پتہٕ نیرِ۔ تہٕ سُہ درٛاو فرعونس نِش سٮ۪ٹھاہ شَرارتہٕ سٍتـ̡ ۔ {یُس امہ پتہٕ...: ہیب۔ یۅہے چھہ تۅہہِ قدمن پیٹھ} {اکھ عظیم...: ہیب۔ شرارتُک گرمی}\n9.\\tتہٕ خداوند ووٚن موسیٰ زِ فرعون کرِ نہٕ تۅہہ بوزنہٕ۔ یُتھ زن میٲنۍ عجائبات مصر کِس سرزمینس منز بڑاونہٕ یِن۔\n10. تہٕ موسیٰ تہٕ ہارونن کٔر فرعونس برونہہ کُن یِم سٲری عجائب تہٕ خداوند کٔر فرعون سُند دِل سخٕت، یُتھ نہٕ سُہ دِیہِ نہٕ بنی اِسرٲیلِس پنہٕ نِس سرزمینہٕ منزٕ نیبر نیرُن۔","1. تہٕ خداوند کٔر مصر کِس سرزمینس مَنٛز موسیٰ تہٕ ہارونس سٍتـ̡ کتھ ،\n2. یہِ ریتھ آسہِ تۅہہِ خٲطرٕ ریتن ہُند آغاز: یہِ آسہِ تۅہہِ خٲطرٕ ؤریُک گۄڈنیُک رٮ۪تھ۔\n3.\\tاسرٲیلٕچ سارِنٕے جمٲژ سٍتـ̡ کتھ کرٕن، یێمہِ ریتہٕ کِس دٔہمہِ دۅہس مَنٛز نِن تِم پرٮ۪تھ أکِس انسانس نِش اکھ کۅکرٕ کُن، یێلہِ ہٕندِس گرس مُطٲبق یێلہِ کُنہ\n4. تہٕ یێلہِ گرٕ کۅکرِ ہٕندِ خٲطرٕ واریاہ کم آسہِ، سُہ تہٕ تٔمۍ سٕندِس مکانس سٍتـ̡ رٔٹِتھ رٔٹِتھ۔ پرٮ۪تھ کانہہ انسان کرِ پننہِ کھٮ۪نہٕ مُطٲبق تُہند گنزراونہٕ یُن۔\n5.\\tتُہُند کُلہٕ کُنہِ اَکہِ ؤرۍ یُک نیٚچُو}\n6.\\tتہٕ تُہۍ تھاوِو امی ریتہٕ کِس ژۄدٲہمہِ دۅہہِ تام تہٕ اسرٲیلٕچ جماعت ہٕنز سورٕے مجلس کرِ شامس یہ مار۔ {منز...: ہیب۔ دۄن شامن درمیان}\n7.\\tتہٕ تِم رٔٹِن خون، تہٕ دِژن دۄن طرفن تہٕ مکانن ہٕندِس پیٹھمِس دروازس پیٹھ، یَتھ مَنٛز تِم کھٮ۪ن۔\n8. تہٕ تِم گژھن تَمہِ رٲژ ماز کھٮ۪ن، نارس سٍتـ̡ تہٕ خمیر روٚس روٹی کھٮ۪ن۔ {تہٕ}تلخ {جڑی بوٹی} سٍتۍ کھٮ۪ن تِم کھٮ۪ن۔\n9.\\tاتھ منز گژھ نہ خام کھیوٚن، نہ آبہٕ سٍتـ̡ رٔٹِتھ بٔلکہِ سٍتـ̡ سٍتـ̡ تٔمۍ سُند کلہٕ پننیو زنگہٕ سٍتۍ، تہٕ تٔمۍ سٕنزِ پاکیزگی سٍتۍ۔\n10. تہٕ صبحس تام گژھ نہٕ اتھ منز کانہہ تہِ روزُن۔ تہٕ یُس صبحس تام اتھ منز باقی روزِ، سُہ گژھہِ نارس سٍتۍ دزان۔\n11.\\tتہٕ یِتھٕ پٲٹھۍ کھیوٚو یہ۔ {ہٮ۪تھ} پنٕنۍ کمر گٔنڈِتھ، کھورِ کھورِ تہٕ پنٕنۍ لٔرِ اتھس منٛز۔ تہٕ تُہۍ کھیوٚو یہِ جلدی سٍتـ̡ کھٮ۪وان: یہِ چُھہ خداوند سُند فسح ۔\n12.\\tکیازِ بہٕ گژھہٕ از رٲژ مصرٕچ سرزمینہٕ مٔنزۍ نیران، تہٕ کرٕ مصرٕچ سرزمینہٕ کِس سارنٕے گۅڈنِکِس زامتس مَنٛز، انسان تہٕ جانور دۄشوٕے مارٕ۔ تہٕ مصر کین سارنٕے دیوتاہن خلاف بہٕ کرٕ فیصلہٕ: بہٕ چُھس خداوند ۔ {دیوتا: یا، شہزادے}\n13.\\tتہٕ یێلہِ بہٕ خون وُچھِتھ تہٕ یێلہِ بہٕ ژے نِش ژٔلِتھ تہٕ یێلہِ بہٕ یێلہِ بہٕ ژے ژے سٍتـ̡ تباہ کٔرِتھ تہٕ یێلہِ بہٕ مصرٕچ سرزمینس پیٹھ مارٕ دِیہ، تہٕ یێلہِ بہٕ ژے سٍتـ̡ تباہ کرُن، یێلہِ بہٕ مصر کِس سرزمینس پیٹھ مارٕ دِیہِ۔ {تباہ کرنہٕ خٲطرٕ...: ہیب۔ تباہی خٲطرٕ}\n14. تہٕ یہ دۅہ آسہِ تۅہہِ خٲطرٕ یادگار۔ تہٕ تُہۍ تھاوِو یہِ پَنٕنـ̡ پَنٕنـ̡ پى۪ٹھ تُہۍ تھاوِو یہِ ہمیشہٕ خٲطرٕ أکِس آرڈیننس سٍتـ̡ دعوت تھاوُن۔\n15. سَتھ دۅہہٕ کھیوٚو خمیر روٚس روٹی۔ گۅڈنچہ دۅہہ تہِ کٔرِو تۅہہ پننیو گَرَو منزٕ خمیر کٔرِتھ، یُس تہِ گۅڈنچہ دۅہہ پیٹھٕ سٔتِمہِ دۅہس تام خمیر کھیوٚن، سُہ روح گژھہِ اسرٲیلِس نِش ژٹنہٕ۔\n16.\\tگۅڈنِکِس دۅہس مَنٛز گژھہِ اَکھ مُقدس کانووکیشن، تہٕ سٔتِم دۅہہ گژھہِ تۅہہِ خٲطرٕ اکھ مقدس کانووکیشن۔ تِمن منز گژھِ نہٕ کانہہ تہِ کٲم کرنہٕ یِنۍ، سوائے {یہ} یُس پرٮ۪تھ أکِس انسانس کھیوٚن پزِ، یُس صرف تۅہہِ ہُند کرنہٕ یُن۔ {مرد: ہیب۔ روح}\n17. تہٕ تُہۍ کٔرِو خمیرٕ روٚس روٹی ہُند دعوت۔ تِکیازِ اَتھ دۅہہٕ چُھس بہٕ تُہٕندِس لشکر مصرہٕ منزٕ نٮ۪بر کٔرِمٕتۍ، تَمہِ مۄکھٕ پَنٕنـ̡ پى۪ٹھـ̡ چُھہ یہِ دۅہ ہمیشہٕ خٲطرٕ مناونہٕ آمُت۔\n18.\\tگۅڈنِکِس ریتس مَنٛز، ژۄدٲہمہِ دۅہہٕ تہٕ وُہمہِ دۅہہٕ تام گژھِو خمیر روٚس روٹی کھٮ۪وان۔\n19. تہندٮ۪ن گَرن مَنٛز گژھِ نہٕ سَتھ دۅہہٕ خمیر لبنہٕ، یُس تہٕ یُس خمیر کھٮ۪یہِ، سُہ تہِ گژھِ اسرٲیلِچ جماعت نِش ژٹنہٕ، چاہے سُہ اجنبی آسہِ، یا زمینس مَنٛز زامُت آسہِ۔\n20. تم گژھ نہٕ خمیر کھیوٚن۔ پَنٕنٮ۪ن سارِنٕے بَسَن مَنٛز کھیٚیُن خمیر روٚس روٹ۔\n21. اَمہِ پَتہٕ کٔر موسىٰ سارِنٕے اِسرٲیلٕکۍ زِٹھہٕ بُلاونہٕ تہٕ تِمن وونُن زِ پَنٕنـ̡ عیال مُطٲبِق کٔرِو اکھ کٹہٕ کٔرِتھ تہٕ فسح مارُن۔ {لیمب: یا، بچہ}\n22.\\tتہٕ تُہۍ کٔرِو ہِسپُک اکھ گُنڈ تہٕ تُہۍ چھِو خوٗنس مَنٛز ڈباونہٕ یُس {چُھ} چُھ، تہٕ لِنٹلس تہٕ دۅن طرفن ہٕندِس خوٗنہٕ سٍتۍ ٹاس دِیُن یُس بیسنس منز چُھ۔ تہٕ صُبحَس تام گژھِ نہٕ تٔمۍ سٕندِس مکانہٕ کِس دروازس پیٹھ نیرُن۔\n23.\\tکیازِ خداوند گژھہِ مصرن پیٹھ مارنہٕ خٲطرٕ۔ تہٕ یێلہِ سُہ لِنٹلس پیٹھ تہٕ دۄن طرفن پیٹھ خون وُچھِ، خداوند گژھہِ دروازٕ پیٹھ، تہٕ دِیہِ نہٕ تباہ کرن وٲلِس تہندِس گَرَس مَنٛز اژنہٕ خٲطرٕ۔\n24. تہٕ تُہۍ کٔرِو یہِ کتھ پانس تہٕ پننٮ۪ن نیٚچوٮ۪ن ہٕندِ خٲطرٕ ہمیشہٕ خٲطرٕ اَکھ حکم نامہٕ مُطٲبِق۔\n25. تہٕ یێلہِ یێلہِ تُہۍ تتھ زمینس مَنٛز وٲتِو یُس خداوند دِیہِ، یُس تٔمۍ سُند وعدٕ چُھ کوٚرمُت، تہٕ یێلہِ تُہۍ کٔرِو یہِ خدمت پورٕ۔\n26.\\tتہٕ یێلہِ گژھہِ تۅہہِ سٍتـ̡ یێلہِ تہٕ تُہٕندِس شُرِ وَنُن زِ تۅہہِ کیا چُھہ یێمہِ خدمتہٕ سٍتـ̡ مطلب۔\n27.\\tیُس تُہۍ وَنُن زِ یہِ چُھ خداوند سٕندِ فسح سٕنز قربانی یُس مصرس مَنٛز بنی اسرٲیلِن ہٕندِس گَرَن پیٹھٕ گٔژھمُت اوس، یێلہِ تٔمۍ مصرن ہٕندِس گَرَن ہٕندِس گَرَس مَنٛز گٔژھِتھ تہٕ سٲنـ̡ گَرٕ رٲچھ کٔرِتھ۔ تہٕ لوٗکو کٔر کلہٕ نوٚم تہٕ پوجا کٔرٕن۔\n28. تہٕ بنی اسرائیل گٔیہ، تہٕ یِتھٕ پٲٹھۍ کٔرٕکھ خداوند موسیٰ تہٕ ہارونس حکم دِتمُت، تِمو تہِ کٔر۔\n29.\\tتہٕ سپُد یہِ زِ نصف رٲژ دِژ خداوند مصر کِس سرزمینس مَنٛز سارنٕے گۅڈٕ زامُت، فرعون سٕندِس گۅڈنِکِس زامتس پیٹھٕ یُس تہندِس تختس پیٹھ بِہِتھ اوس، یُس قٲد سٕندِس گۅڈنِکِس زامتس تام یُس تہٕ کوٹھس مَنٛز اوس۔ تہٕ چارواین ہٕندِس سارِنٕے گۅڈنِچ اولاد۔ {ڈنجن: ہیب۔ ہاؤس آف دی پٹ}\n30.\\tتہٕ فرعون ووٚتھ رٲژ سُہ تہٕ تٔمۍ سٕندِس سارِنٕے خادمَن تہٕ سارِنٕے مصری۔ تہٕ مصرس منز گۆو اکھ زبردست فریاد ۔ تکیازِ {اتہِ} اوس نہٕ کانہہ مکانہ ییتہِ {اتہِ} اوس نہٕ اکھ تہِ مُرد۔\n31.\\tتہٕ تٔمۍ بُلوو راتس موسیٰ تہٕ ہارونس تہٕ ووٚنُن، وۅتھٕ ووٚتھ، تہٕ تُہۍ کٔرِو میانہِ قومہٕ منز، تم تہٕ بنی اسرائیل۔ تہٕ گژھِو، خداوند سٕنز خدمت کٔرِو، یِتھہٕ کٔنۍ ژے وَنُن چُھ۔\n32.\\tپَنٕنۍ گٔژھ تہٕ پَنٕنۍ کھیٚلہٕ نِیُن، یِتھہٕ کٔنۍ ژےٚ وَننہٕ آمٕژ چھِ، تہٕ نیرِو۔ تہٕ مےٚ تہِ کرٕ دعا۔\n33.\\tتہٕ مصری ٲسۍ عوامس پیٹھ زور دِوان زِ تِم گژھن جلدٕے زمینہٕ منزٕ نٮ۪بر کٔرِتھ۔ تکیازِ تِمو ووٚن، أسۍ {be} سٲری موٗدۍ {انسان}۔\n34.\\tتہٕ لُکھ لوٚگ پنُن ڈو خمیر گژھنہٕ برونہہ، تِہٕندِس پلوس منز گٔنڈِتھ گٔژھِتھ گٔژھِتھ۔ {گُنڈن: یا، ڈوف}\n35.\\tتہٕ بنی اسرائیلو کٔر موسیٰ سٕندِ کلامَس مطٲبق۔ تہٕ تِمو ہیوٚت مصری نِش رۄپہٕ ہٕندۍ جوٲہر، تہٕ سۄنہٕ تہٕ پلوٕکۍ جوٲہر:\n36.\\tتہٕ خداوند دِژ مصرن ہٕندِس نظرس مَنٛز لُکن پیٹھ عنایت، یُتھ تِمو دِژ تِمن دِنہٕ۔ تہٕ تمو کٔر مصری خراب۔\n37.\\tتہٕ بنی اسرائیل گٔیہِ رمیسیس پیٹھٕ سوکوتھس تام سفر، یُس شُرین سٍتـ̡ پیدل شیہ لچھ نفر ٲسۍ۔\n38.\\tتہٕ یِمن سٍتـ̡ گٔیہِ رلہٕ مِلہٕ ہُند ہجوم تہِ۔ تہٕ ریوڑ، تہٕ کھیٚلہٕ، {حتیٰ کہ} واریاہ چارو۔ {اکھ مخلوط ...: ہیب۔ اکھ زبردست مرکب}\n39.\\tتہٕ تِمو بَنوو خمیرٕ روٚس کیک یُس تمو مصرہٕ منزٕ کڈنہٕ آمُت، تکیازِ یہِ اوس نہٕ خمیر۔ تِکیازِ تِم آیہ مصرہٕ منزٕ کڑنہٕ آمٕتۍ، تہٕ ہیوٚک نہٕ روزِتھ، تہٕ نہ ٲسۍ تِمو پانس خٲطرٕ کانہہ تہِ چیز تیار کٔرمٕژ۔\n40.\\tوۅنۍ اوس مصرس منز روزان اسرٲیلِکۍ بچہِ ہُند قیام ژور ہتھ ترہ ؤری۔\n41.\\tتہٕ ژۅن ہتھ ترہن ؤرین ہٕندِس ٲخرس پیٹھ سپُد، یێمہِ دۅہہ سپُد یێلہِ سٍتـ̡ خداوند سٕندِ سارِنٕے لشکر گٔیہِ مصرہٕ کِس سرزمینہٕ پى۪ٹھ۔\n42. یہِ چُھ اَکھ رٲژ یُس خداوند سٕندِ خٲطرٕ یِم مصرٕچ سرزمینہٕ پى۪ٹھہٕ نٮ۪بر کٔرِتھ روزُن: یہِ چُھ خداوند سٕنز سُہ رٲژ یُس تِمن سارِنٕے اِسرٲیلِیَن ہٕندِس زمانس مَنٛز مناونہٕ یُن۔ {اکھ رات...: ہیب۔ مشاہدن ہٕنٛز اکھ رات}\n43. تہٕ خداوند ووٚن موسیٰ تہٕ ہارونس زِ یہِ چُھہ فسح ہُند حکم: اَمہ سٍتـ̡ گژھِ نہٕ کانہہ اجنبی کھٮ۪ن:\n44.\\tمگر پریتھ انسان سُند نوکر یُس پونسہٕ خٲطرٕ ہینہ آسہِ، یُس تہِ ختنہ کرِ، تیلہِ گژھہِ سُہ کھیوٚن۔\n45.\\tغیر ملکی تہٕ کرایہ دار نوکر گژھِ نہٕ اَمہ سٍتۍ کھٮ۪ن۔\n46.\\tأکِس گَرَس مَنٛز گژھہِ کھٮ۪نہٕ یُن۔ ژے گژھ نہٕ ماز نیبر نیرُن۔ نہ پھُٹرٲوِو تِمن ہٕنز اکھ ہڈی تہِ۔\n47. اسرٲیلٕچ سارِنٕے جماعت تھاوٕنـ̡ یہِ رژھرٕنـ̡ ۔ {کیپ...: ہیب۔ کٔرِو یہِ}\n48. تہٕ یێلہِ اَکھ اَکھ اجنبی ژےٚ سٍتـ̡ روزِ، تہٕ خداوند سٕندِس سٍتـ̡ فسح تھاوُن، تٔمِس سارِنٕے نَرَن ہُند ختنہٕ کرنہٕ یُن، تہٕ پَتہٕ گژھہِ سُہ نِش یِنہٕ تہٕ رژھرُن۔ تہٕ سُہ گژھہِ تِتھۍ یُس زمینس منز زامُت آسہِ، تکیازِ کانہہ تہِ ختنہ نہ گژھہِ نہ اتھ منز کھٮ۪نہٕ۔\n49.\\tاکھ شریعت آسہِ تٔمِس سٍتـ̡ یُس گرِ زامُت آسہِ، تہٕ یُس اجنبی سٍتـ̡ یُس توے منزٕ روزان آسہِ۔\n50. یِتھٕ پٲٹھۍ کٔر بنی اسرائیلٕکۍ سارِنٕے بٔنِس سٍتـ̡ یِتھٕ کٔنۍ خداوند موسیٰ تہٕ ہارونس حکم دِیُت، تِتھے کٔنۍ کوٚر تِمو تہِ۔\n51.\\tتہٕ سپُد امی دۅہہٕ سپُد، {یێلہِ} خداوند کٔر بنی اسرائیل تِہندِ فوجہٕ سٍتـ̡ مصر کِس سرزمینہٕ منزٕ نیبر۔","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2. یُس تہِ اسرٲیلِس مَنٛز یُس رحم کھولان چُھ، یُس انسان تہٕ جانور سٕندِس دۅشوے سٍتـ̡ کھولان چُھ، سُہ چُھ میٲنۍ {چُھ}۔\n3. تہٕ موسىٰ ہن ووٚن لُکن زِ یہ دۅہ یاد تھاوُن یُس تم مصرہٕ منزٕ غلامی ہٕندِ گرٕ منزٕ نیبر نیرِو۔ تِکیازِ اَتھٕ کہِ طاقتہٕ سٍتـ̡ دِژ خداوند یَتھ {جایہِ} پى۪ٹھہٕ نِش نیبر۔ {غلامی: ہیب۔ خادم}\n4.\\tیہ دۅہ آو تم ابیبس ماہ مَنٛز نیران۔\n5. تہٕ یێلہِ یێلہِ خداوند تۅہہِ کنعانی، حِتی، امورِی، حِویو تہٕ یبوسی ہٕندِس ملکس مَنٛز انِ، یُس سُہ پننین مٲلن سٍتـ̡ دِنہٕ خٲطرٕ قسم چُھ دِنہٕ آمُت، یُس دۄدٕ تہٕ ماچھ سٍتـ̡ وسان آسہِ، تہٕ یێمہِ ریٚتس مَنٛز روزِ یہِ خدمت۔\n6. سَتھ دۅہہٕ گژھِ تُہۍ خمیر روٚس روٹی کھٮ۪وان، تہٕ سٔتِم دۅہہٕ گژھہِ خداوند سٕندِ خٲطرٕ دعوت۔\n7. خمیرٕ روٚس روٹی گژھہِ ستن دۅہن کھٮ۪نہٕ۔ تہٕ ژے سٍتـ̡ گژھہِ نہٕ خمیر وُچھنہٕ یِنہٕ تہٕ نہ گژھہِ ژے سٍتـ̡ سارِنٕے محلن مَنٛز خمیر وچھنہٕ۔\n8.\\tتہٕ تۅہہ ہٲوِو تَمہِ دۅہہٕ پنُن نیچو تہٕ ونُن، {یہِ چُھہ کرنہٕ آمُت} ییمہِ سٍتـ̡ خداوند میہ سٍتـ̡ کورمُت ییلہ بہٕ مصرہٕ منزٕ نیبر نیران اوس۔\n9. تہٕ یہِ گژھہِ تۅہہِ ہٕندِس اَتھَس پؠٹھ اَکہِ نشانہٕ خٲطرٕ، تہٕ تُہنزن اچھن مَنٛز یادگار آسُن، یُتھ خداوند سُند شریعت آسہِ تُہٕندِس ٲسِس مَنٛز، یِکیازِ خداوند چُھ ژےٚ مضبوٗط اَتھٕ سٍتـ̡ ژےٚ مصرہٕ منزٕ نیبر کڈمُت۔\n10.\\tتێلہِ تھاوُن یہ حکم ؤری پتہٕ ؤری پننِس موسمس مَنٛز۔\n11. تہٕ یێلہِ یێلہِ خداوند تۅہہِ کنعانین ہٕندِس سرزمینس مَنٛز انِ، یێلہِ سُہ تہٕ تُہٕندِس مٲلِس سٍتـ̡ قسم دِیہِ، تہٕ دِیہِ تہٕ دِیہِ تہٕ دِیہِ۔\n12. یُس تہٕ یُس درندٕ کھولان چُھ، تہٕ پرٮ۪تھ کانہہ گۅڈٕ یُس درندٕ سٕندِ سٍتـ̡ یُس ژے رٔٹِتھ چُھ، تہٕ یُس ژے رٔٹِتھ چُھ، سُہ چُھہ خداوند سٕندِ خٲطرٕ الگ کرُن۔ نَر آسہِ خداوند سٕندِ۔ {سیٹ...: ہیب۔ وجہ}\n13. تہٕ گَرٕ سُند پرٮ۪تھ کُنہِ تہٕ یێلہِ نہٕ تۅہہ یہ چھُکھ چھُکھ دِژمُت، تێلہِ کٔرِو تٔمۍ سٕنز گردن پھُٹراوُن، تہٕ تُہٕندِس شُرٮ۪ن مَنٛز کٔرِو سارِنٕے انسانہٕ سٕندِس گۄڈنِکِس زُوٕے سٍتـ̡ نجات دِنہٕ۔ {لیمب: یا، بچہ}\n14.\\tتہٕ یێلہِ گژھہِ تُہند نیچو یِنہٕ وٲلِس وقتس سٍتـ̡ پرژھہِ، یہِ کیا چُھہ؟ یُس تُہۍ أمِس وَنُن، اَتھٕ کہِ طاقتہٕ سٍتـ̡ کٔر خداوند اسہِ مصرہٕ پى۪ٹھ، غلامی ہٕندِس گرٕ پى۪ٹھہٕ نِش نیبر۔ پگہہ کُن}\n15. تہٕ سپُد یہِ سپدُن، یێلہِ فرعون اسہِ مشکل سان تراوُن، زِ خداوند کٔر مصرٕچ سرزمینس مَنٛز سارِنٕے گۅڈٕ زامُت، یُس انسانہٕ سُند گۄڈنیُک زامُت تہٕ درندٕ سُند گۅڈنیُک زامُت، تێمہِ کِنۍ چُھس بہٕ خداوند سٕندِ خٲطرٕ سارِنٕے قُربان۔ مگر میانین شُرین ہٕندِ سارِنٕے گۄڈنِکِس شُرِس چھُس بہٕ چھُس نجات دِوان۔\n16. تہٕ یہِ گژھہِ تۅہہِ ہٕندِس اتھس پیٹھ تہٕ تۅہہِ أچھن درمِیان بُتھِ ہٕندِس نشانہٕ خٲطرٕ، تکیازِ خداوند کٔر اسہِ اتھہٕ سٍتـ̡ نیبر نیرنہٕ۔\n17.\\tتہٕ سپُد ییلہ فرعونن لُکن تراوُن، خداین کٔر نہٕ تِمن فلسطینن ہٕنزِ سرزمینہٕ کِس وتہِ پى۪ٹھ، حالانکہ سُہ اوس نزدیک۔ تکیازِ خداین ووٚن زِ جنگ وُچھِتھ گژھن لوکھ توبہ کٔرِتھ تہٕ تِم واپس مصرس کُن واپس۔\n18.\\tمگر خداین کٔر لوکن بحر احمر کِس بیابانن ہٕنزِ وتہِ کُن رہنمٲیی تہٕ بنی اسرائیل گٔیہِ مصر کِس سرزمینہٕ منزٕ نیبر۔ {ہارن: یا، أکِس درجس منٛز پانژو ذریعہٕ}\n19. تہٕ موسىٰ نِیہِ یوسف سٕنزِ أڈجہِ پانس سٍتـ̡ ، تکیازِ تٔمۍ اوس بنی اسرٲیلِس سٍتـ̡ قَسم کورمُت زِ خدا کرِ یٔژ تۅہہِ سٍتـ̡ ۔ تہٕ تُہۍ کٔرِو میٲنۍ أڈجہِ پانس سٍتۍ نِنہٕ۔\n20. تہٕ تِمو کٔر سُکوتھ پٮ۪ٹھٕ پنُن سفر، تہٕ بیابان کِس اندس مَنٛز، ایتھمس مَنٛز ڈیرٕ ترٲو۔\n21.\\tتہٕ خداوند اوس تِمن برونہہ کُن دۅہہٕ اوبرٕ کِس تھمَس منز تِمن وتہِ پکناونہٕ خٲطرٕ۔ تہٕ رٲژ نارٕ کِس ستونس منز، تِمن گاش دِنہٕ خٲطرٕ؛ دۅہ تہٕ رٲژ گژھُن:\n22.\\tتٔمۍ ہیوٚت نہ دۅہلہِ اوٚبرُک تھم، تہٕ نہ رٲژ نارُک تھم، لُکن برونہہ کُن۔","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2.\\tبنی اسرٲیلِس کٔرِو کتھ زِ تِم پھیرن تہٕ پیہروتھس برونہہ کُن، مگڈول تہٕ سمندرس درمِیان بعلزیفونس خٕلاف۔\n3. تِکیازِ فرعون وَنُن بنی اِسرٲیلِس مُتلِق زِ تِم چھِ زمینس مَنٛز پھٔلِتھ بٔرِتھ، بیابان چُھ تِم بند کٔرِتھ۔\n4. تہٕ بہٕ کَرٕ فرعون سُند دِل سخٕت، یُتھ سُہ یِمن پَتہٕ۔ تہٕ بہٕ کٔرٕ فرعونس تہٕ تٔمۍ سٕندِس سارِنٕے لشکرس پیٹھ عزت۔ یُتھ زن مصری گژھن پتاہ زِ بہٕ چُھس خداوند چُھس۔ تہٕ تِمو کوٚر یہِ۔\n5. تہٕ مصرٕکِس بادشاہس آو وننہٕ زِ لُکھ ژٔلِتھ تہٕ فرعون تہٕ تٔمۍ سٕندٮ۪ن خدمتگارن ہُند دِل آو لُکن خلاف تہٕ تِمو ووٚن، اسہِ کیازِ چُھ یہِ کورمُت، زِ اسہِ دِژ اسرٲیلِس پننہِ خدمت کرنہٕ نِش۔\n6. تہٕ تٔمۍ بنوو پنُن رتھ تیار، تہٕ نِیہِ پنٕنۍ لوٗکھ پانس سٍتۍ:\n7.\\tتہٕ تٔمۍ رٔٹۍ شیہ ہتھ ژٲرِتھ رتھ، تہٕ مصرٕکۍ سارِنٕے رتھ، تہٕ یِمو منزٕ پرٮ۪تھ أکِس پیٹھ کپتان۔\n8.\\tتہٕ خداوند کٔر مصرُک بادشاہ فرعون سُند دِل سخت، تہٕ سُہ لوٚگ بنی اسرٲیلِس پَتہٕ۔ تہٕ بنی اسرٲیلِس درٛاو تھدِ اتھہٕ سٍتـ̡ درٛاو۔\n9.\\tمگر مصری لوٚگ تِمن پَتہٕ، فرعون سٕندِ سارِنٕے گُرِ تہٕ تٔمۍ سٕندِس گُرِ سوارِ تہٕ تٔمۍ سٕندِس لشکرس پَتہٕ تہٕ لٔگِکھ سمندرس نِش بعلزیفونس برونہہ کُن سمندرس نِش ڈیرٕ ترٲوِتھ۔\n10.\\tییلہ فرعون نزدیک ووت، بنی اسرٲیلیو کٔر أچھ تُل، تہٕ وُچھِتھ گٔیہِ مصری تِمن پَتہٕ پَتہٕ۔ تہٕ تِم گٔیہِ خوفہٕ: تہٕ بنی اسرٲیلِو کٔر خداوند کُن فریاد کرنہٕ۔\n11.\\tتہٕ تِمو ووٚن موسیٰ سٍتـ̡ کیازِ مصرس مَنٛز ٲس نہٕ کانہہ قبر، کیا ژے چھکھ اسہِ بیابانن مَنٛز مرنہٕ خٲطرٕ نِمٕتۍ؟ تۅہہ کیازِ کور اسہِ سٍتـ̡ یۅہے سٍتـ̡ سٍتـ̡ اسہِ سٍتـ̡ مصرہٕ منزٕ نٮ۪بر نِنہٕ خٲطرٕ؟\n12.\\tکیا یہ لفظ چھہ نہ اسہِ مصرس منز وونمت زِ اسہِ گژھہِ مصرن ہنز خدمت کرنہ خاطرہ اسہِ کُنہ تکیازِ اسہِ خٲطرٕ اوس بہتر زِ اسہِ گژھہِ بیابانن منز مرُن۔\n13. تہٕ موسىٰ ووٚن لُکن زِ خوفہٕ نہٕ گژھو، رٔٹِو رٔٹِو، تہٕ وُچھِو خداوند سٕنز نجات یُس سُہ از تہِ ہٲوِ، یُس سُہ از تہِ ہٲوِو، تِمن ہٕندِ خٲطرٕ یِم تۅہہ از وُچھمٕتۍ، تِمن ہٕندِ خٲطرٕ یِم نہٕ ہمیشہٕ خٲطرٕ وُچھِو۔ {for the...: یا، ییلہ زن ژیہ از تام مصری وچھمٕتۍ}\n14. خداوند کرِ تۅہہِ خٲطرٕ لڑان، تہٕ تُہۍ روزِ پنُن سکون۔\n15.\\tتہٕ خداوند ووٚن موسیٰ سٍتـ̡ کیازِ چُھکھ میہ سٍتـ̡ فریاد دِوان؟ بنی اسرٲیلِس کٔرِو کتھ زِ تِم گژھن برونہہ کُن:\n16.\\tمگر پَنٕنۍ لٔر تُلِتھ تہٕ پَنُن اَتھٕ پھٔہلٲوِو سمندرس پیٹھ، تہٕ کرُن اِسرٲیلٕکۍ بَرِ سمندرس مَنٛز۔\n17. تہٕ بہٕ کٔرٕ بہٕ مصرن ہٕندِ دِل سخٕت تہٕ تِم گژھن تِمن پتہٕ، تہٕ بہٕ کَرٕ فرعونس تہٕ تٔمۍ سٕندِس سارِنٕے لشکرس پیٹھ، تٔمۍ سٕندِس رتھَن تہٕ تٔمۍ سٕندِس گُرِ سوارَن پیٹھ عزت۔\n18.\\tتہٕ مصری گژھہِ معلوم زِ بہٕ چُھس خداوند آسان، یێلہِ بہٕ فرعونس پیٹھ، تٔمۍ سٕندِس رتھَن تہٕ تٔمۍ سٕندِس گُرِ سوارَن سٍتـ̡ عزت حٲصل کٔرِ۔\n19.\\tتہٕ خدایہِ سُند فرشتہٕ یُس اسرٲیلِس کِس خٲمس برونہہ کُن گۆو، ہیوٚت تہٕ تِمن پَتہٕ گٔیہِ۔ تہٕ اوٚبرُک تھم دراو تہندِس بُتھِس برونہہ کُن، تہٕ کھڑا تِمن پَتہٕ:\n20. تہٕ یہِ آو مصری ہٕندِس خٲمس تہٕ اسرٲیلِس کِس خٲمس درمِیان ۔ تہٕ یہ اوس اوٚبر تہٕ انہِ گوٚٹ {تمن خٲطرٕ}، مگر یہ اوس رٲژ گاش دِوان: تاکہ اکھ اوس نہٕ سارِوٕے رٲژ بییِس نزدیک۔\n21. تہٕ موسیٰ ہن تروو سمندرس پیٹھ اتھہٕ۔ تہٕ خداوند کٔر سٲرۍسٕے رٲژ تیز مشرقی واو سٍتـ̡ سمندرس {واپس}، تہٕ بنووُن سمندرس خشک {زمین}، تہٕ آب گۆو تقسیم۔\n22.\\tتہٕ بنی اسرائیل گٔیہِ خشک زمینس پیٹھ سمندرس منز، تہٕ آب اوس تِہندِ دچھنہِ اتھس تہٕ کھوورِ طرفہٕ اکھ دیوار۔\n23.\\tتہٕ مصری لوٚگ تِمن پتہٕ سمندرس تام، فرعون سٕندِ سارِنٕے گُرۍ، تٔمۍ سٕندِس رتھ تہٕ گُرۍ سوارِ سٍتـ̡ تہِ۔\n24.\\tتہٕ سپُد یہِ زِ صُبحَس وِزِ خداوند کٔر نارٕ تہٕ اوٚبرٕ کِس تھمَس سٍتـ̡ مصری ہٕندِس لشکرس کُن نظر، تہٕ کٔرٕن مصری ہٕندِس لشکرس پریشان\n25.\\tتہٕ تُلِکھ تِمن ہٕندِس رتھٕکۍ چکر، یُتھ زن تِمو سٍتـ̡ وُچھِتھ زِ أسـ̡ أسـ̡ أسـ̡ اسرٲیلِس نِش ژلُن۔ تکیازِ خداوند چُھ تِہندِ خٲطرٕ مصرین خلاف لڑان۔ {یہ زِ تِم...: یا، تہٕ بنیوو تِم گٔژھِتھ گٔژھِتھ}\n26.\\tتہٕ خداوند ووٚن موسیٰ سٕندِس سمندرس پیٹھ پنُن اتھہٕ پھٔہلٲوِتھ یُتھ آب ییہ مصرین پیٹھ، تِہندین رتھن تہٕ تِہندین گُرِ سوارن پیٹھ۔\n27.\\tتہٕ موسىٰ کٔر سمندرس پیٹھ اتھہٕ تہٕ سمندرُک ووت سمندرس پیٹھ اتھہٕ تہٕ سمندرٕ آو پننِس طاقتس منز واپس۔ تہٕ مصری ژٔل اتھ خٕلاف ۔ تہٕ خداوند دِژ سمندرس مَنٛز مصری تختہٕ۔ {اوور تھرو: ہیب۔ شِکَر کَرنہٕ آمُت}\n28. تہٕ آب آو واپس تہٕ رتھ، تہٕ گُرۍ سوار، تہٕ فرعون سُند سٲری لشکر یُس تِمن پتہٕ سمندرس منز آو۔ تمن منز رود نہ کانہہ تہِ۔\n29.\\tمگر بنی اسرائیل پٔکۍ سمندرس منز خشک زمینس پیٹھ۔ تہٕ آب اوس تمن خٲطرٕ دچھنہٕ اتھس تہٕ کھوورِ طرفہٕ اکھ دیوار۔\n30. یِتھٕ پٲٹھـ̡ بچٲو خداوند اَمہِ دۅہہٕ اسرٲیلِس مصری ہٕندِ اتھہٕ نِش بچٲومُت۔ تہٕ اسرائیلن وچھ سمندرٕ بٹھس پیٹھ مصری مردہ۔\n31. تہٕ اسرٲیلَن وُچھ سُہ بٔڈ کٲم یُس خداوند مصرن پیٹھ کٔر، تہٕ لُکھ کٔر خداوند سُند خوف تہٕ خداوند تہٕ تٔمۍ سٕندِس بندس موسیٰ سُند پژھ۔ {کٲم: ہیب۔ اتھہٕ}","1. اَمہِ پَتہٕ گیوٚو موسیٰ تہٕ بنی اسرٲیلِیو یہِ بٲتھ خداوند سٕندِ خٲطرٕ، تہٕ وونُن زِ بہٕ گٮ۪وٕ خداوند سٍتـ̡ گٮ۪وُن، تِکیازِ تٔمِس چُھ جلال سان فتح حٲصِل کٔرمٕژ: گُرِ تہٕ تٔمۍ سٕندِس سوارِ سمندرس مَنٛز ترٛٲومُت۔\n2. خداوند چُھ میٲنۍ طاقت تہٕ نغمہٕ، تہٕ سُہ چُھ میٲنۍ نجات بنیومُت: سُہ چُھہ میٲنۍ خدا، تہٕ بہٕ کرٕ تس اکھ بستی تیار۔ میٲنِس مٲلہِ سُند خدا، تہٕ بہٕ کٔرٕ أمِس تھزر۔\n3. خداوند {چُھ} جنگُک آدمی: خداوند {چُھ} تٔمۍ سُند ناو۔\n4. فرعون سٕندِ رتھ تہٕ تٔمۍ سٕندِس لشکر سمندرس مَنٛز ترٛٲوِتھ تہٕ تٔمۍ سٕندِ منتخب کپتان تہِ گٔیہِ بحرِ احمرس مَنٛز ڈُبۍ۔\n5.\\tسرٛنٮ۪رن چھُ یِمن ؤلِتھ: تِم گٔیہِ کٔنہِ ہٕندِس بٔنِس پٲٹھۍ۔\n6. اے خداوند، تُہند دٔچھُن اَتھٕ چُھ طاقتس مَنٛز جلال حٲصِل گومُت: اے خداوند، چُھہ تُہند دٔچھُن اَتھٕ دُشمن ٹُکرٕ ٹُکرٕ کٔرِتھ۔\n7.\\tتہٕ پننہِ عظمتٕچ عظمتس منز کٔر تِم یِم پانس خلاف کھڑے گٔیہِ، ژے کٔر پنُن قہر ، یُس تِمن کھٮ۪وان چھُ۔\n8.\\tتہٕ پننہِ نستہِ ہٕندِس دھماکہٕ سٍتۍ گٔیہِ آب جمع کرنہٕ، سٔہلاب ووت أکِس ڈھیرس ہٕندۍ پٲٹھۍ، {تہٕ} سمندرٕ کِس دلس منز گٔیہِ سرٛنٮ۪ر بٔرِتھ۔\n9.\\tدُشمن ووٚن بہٕ پیچھا کٔرِتھ، بہٕ کرٕ پَتہٕ، بہٕ کرٕ غنیمت بٲگراونہٕ۔ میٲنۍ ہوس گژھہِ تمن پیٹھ پورٕ۔ بہٕ کٔرٕ پنٕنۍ تلوار، میون اتھہٕ کٔرٕ تِم تباہ کرنہٕ۔ {تباہ: یا، قبضہ کٔرِو}\n10.\\tژے واو واو سٍتـ̡ سمندرَن تِمن ؤلِتھ تہٕ تِم گٔیہِ زبردست آبس مَنٛز سیسہٕ ہٕندۍ پٲٹھۍ۔\n11. اے خداوند، دیوتاہن مَنٛز کُس چُھہ تۅہہِ ہِش ہیوٗ چُھہ؟ ژے ہیوٗ کُس چُھ، پاکیزگی مَنٛز شاندار، خوفزدہ {منز} تعریف، عجائبات کٔرِتھ؟ {دیوتا: یا، طاقتور؟}\n12.\\tژے کٔر پنُن دچھُن اتھہ، زمینہِ نِش گِلہِ۔\n13. ژے کٔر پننہِ رحمتہٕ سٍتـ̡ تِمن لوکن ہٕنز قیادت یِم ژے نجات دِژمٕژ چھِ، تہٕ ژے کٔر پننہِ طاقتہٕ سٍتـ̡ پننہِ مقدس بستی تام رہنمٲیی کٔرمٕژ۔\n14. لوکھ بوزُن، {تہٕ} کھوژُن: فلسطین کین بسکینن پیٹھ گژھہِ غم رٔٹتھ۔\n15.\\tتیلہِ گژھہِ ادوم ہٕندِس ڈیوکس حیران۔ موآبٕکۍ طاقتور نفر چھِ تِمن پیٹھ تھپھ کٔرِتھ۔ کنعانٕکۍ سٲری بسکیٖن دِنہٕ یِن۔\n16.\\tخوف تہٕ خوف گژھہِ تِمن پیٹھ۔ چانہِ نرِ ہٕنزِ عظمتٕ سٍتۍ گژھن تِم کٔنہِ ہٕندۍ پٲٹھۍ۔ یوتام نہ تہند لوکھ نیرِ، اے خدا، یوتام نہ لوکھ نیرِ، {یُس} ژے ہیوٚتمُت چھُ۔\n17. اے خداوند، یُس ژے پننہِ وراثت کِس پہاڑس مَنٛز تراوُن، اے خداوند، یُس تۅہہِ روزنہٕ خٲطرٕ بنوومُت چھُ، اے خدا، یُس تۅہہِ ہٕندِس اتھو قایم کورمُت چھُ۔\n18. خداوند کرِ ہمیشہٕ ہمیشہ خٲطرٕ بادشاہت۔\n19. تکیازِ فرعون سُند گُر دراو پننین رتھن تہٕ گُرۍ سوارن سٍتـ̡ سمندرس منز، تہٕ خداوند اوٚن تمن پیٹھ سمندرُک آب دُبارٕ۔ مگر بنی اسرائیل گٔیہِ سمندرس منز خشک زمینس پیٹھ۔\n20.\\tتہٕ ہارون سٕنزِ بینہِ مریم نبوت رٔٹِتھ اتھس منز اکھ ٹمبرل۔ تہٕ سٲری زنانہٕ گٔیہٕ أمس پتہٕ ٹمبرل تہٕ نژنہٕ سۭتۍ۔\n21. تہٕ مریمَن دِیُت تِمن جواب، یێلہِ سُہ چُھ جلال سان فتح حٲصِل کٔرمٕژ۔ گُرۍ تہٕ أمۍ سٕنٛدِ سوارِ ترٛٲوۍ سمندرس منٛز۔\n22. یێمہِ کِنۍ موسىٰ اوٚن اسرٲیلِس بحرِ احمر پیٹھٕ تہٕ تِم گٔیہِ شور کِس بیابانس مَنٛز۔ تہٕ تِم گٔیہِ تریہ دۅہن بیابانن منز، تہٕ لوٚب نہٕ کانہہ آب۔\n23.\\tییلہ تِم مارہ کِس آبس منز وٲتِتھ ہیوٚک نہٕ تِم مارہ کِس آبس منز چِھہِ، تِکیازِ تِم ٲسۍ تلخ تہٕ اَمہ کِس ناوَس اوس مارہ وننہٕ آمُت۔ {مارہ: یہِ چھُ تلخی}\n24.\\tتہٕ لوکو کٔر موسیٰ سٕندِس خلاف گڑبڑ کٔرِتھ وونُن، أسۍ کیا چیٚو؟\n25. تہٕ تٔمۍ کٔر خداوند سٕندِس کُن فریاد ۔ تہٕ خداوند ہٲو تس اکھ کُل، {یُس} ییلہ تٔمۍ آبس منز ترٛوو، آب آو موٚدُر کرنہٕ، تتہِ بنوو تِمن خٲطرٕ اکھ قانون تہٕ اکھ حکم، تہٕ تتہِ کوٚر تِم ثٲبت،\n26.\\tتہٕ وونُن، یێلہِ ژے پَنٕنـ̡ خدایہِ سٕنزِ آواز سٍتـ̡ یُس تٔمۍ سٕندِس نظرِ سٍتـ̡ صحیح آسہِ، تہٕ تٔمۍ سٕندِس حُکمن سٍتـ̡ بوزِو، تہٕ تٔمۍ سٕندِس سارِنٕے حکمن ہُند عمل کٔرِو، بہٕ چُھس نہٕ یِمو منزٕ کانہہ تہِ بٮ۪مارِ یُس میہ مصرن پیٹھ دِژمُت چُھ، تێکیازِ بہٕ چُھس خداوند یُس تُہٕندِس شفا دِوان چُھس۔\n27.\\tتہٕ تِم آیہ ایلیمس نِش، ییتہِ بہٕ آبٕکۍ کۄرٕ تہٕ تریہ تہٕ داہ کھجور کُلۍ ٲسۍ، تہٕ تِمو کٔر آبس نِش ڈیرٕ تراونہٕ۔","1.\\tتہٕ تِمو دراو ایلیم پیٹھٕ پنُن سفر، تہٕ بنی اسرٲیلِچ سارِنٕے جماعت گٔیہِ مصر کِس سرزمینہٕ منزٕ نیرنہٕ پتہٕ دٔیمہِ ریتہٕ کِس پنٛدٲہمہِ دۅہہٕ گۅناہ کِس بیابانس کُن، یُس ایلیم تہٕ سیناہس درمیان چھُ۔\n2. تہٕ بنی اسرائیل ہٕنزِ سارِنٕے جماعت کٔر بیابانن مَنٛز موسیٰ تہٕ ہارونس خلاف بڑبڑاوان:\n3. تہٕ بنی اسرٲیلیو ووٚن تِمن زِ کاش أسۍ ہا خدایہ سٕندِ اتھہٕ سٍتـ̡ مصرٕچ زمینس مَنٛز، ییلہ أسۍ ماز بانن نِش بِہتھ ٲسۍ، {تہٕ} ییلہ أسۍ پورٕ پٲٹھـ̡ روٹی کھیوٚو۔ تکیازِ ژے چھکھ اسہِ یتھ بیابانس منز انمُت، یہ سورے مجلسہ فاقہٕ سٍتـ̡ مارنہٕ خٲطرٕ۔\n4. اَمہِ پَتہٕ ووٚن خداوند موسیٰ سٕندِ خٲطرٕ، وُچھِتھ بہٕ تہٕ بہٕ تہٕ ژےٚ خٲطرٕ اسمانہٕ سٍتـ̡ روٹی برساونہٕ۔ تہٕ لوٗکھ گژھن پریتھ دۅہہ اکھ خاص ریٹ جمع کٔرِتھ، یُتھ بہٕ تِم ثٲبت کٔرِتھ، چاہے تِم میانہِ قانونس مطٲبق پکان کِنہٕ نہ۔ {اکھ یقین...: ہیب۔ تٔمۍ سٕنٛدس دۄہس منٛز اکہ دۄہُک حصہٕ}\n5.\\tتہٕ یِہ سپدِ زِ شیٚیمہِ دۅہہٕ گژھن تِم تیار یُس تِم اَنان۔ تہٕ یہ گژھہِ دۅگنہٕ کھوتہ دۅگنہٕ زیادٕ یُس تم دۅہہ جمع کران چھہِ۔\n6. تہٕ موسیٰ تہٕ ہارونن ووٚن سارنٕے بنی اسرٲیلِس زِ یێلہِ تہٕ یێلہِ تہِ گژھہِ پتاہ زِ خداوند چُھ تُہۍ مصرٕچ زمینہٕ منزٕ نیبر کڈمُت:\n7. تہٕ صُبحَس پَتہٕ وُچھِو خداوند سُند جلال ۔ یێلہِ سُہ چُھہ خداوند سٕندِس خٕلاف تُہٕنزِ بڑبڑاہ بوزان تہٕ أسـ̡ کیا چُھہ، یێلہِ چُھہ اسہِ سٍتـ̡ بُزرگ کٔرِتھ؟\n8. تہٕ موسىٰ ووٚن، {یہِ گژھہِ}، یێلہِ خداوند دِیہِ تۄہہِ شامَس ماز کھٮ۪نہٕ خٲطرٕ، تہٕ صُبحَس روٹی پوٗرٕ دِیہِ۔ یێمہِ مۅکھہ چُھہ خداوند تُہٕنزِ گُرگویی بوزان یُس تُہۍ أمِس خٕلاف بڑبڑاوان چھِو: تہٕ أسۍ کیا چھِ؟ تۅہہِ ہٕندِس گُرپھ سٍتـ̡ چُھہ نہٕ اسہِ خٕلاف، بٔلکہِ خداوند سٕندِس خٕلاف۔\n9. تہٕ موسىٰ ووٚن ہارونس سٍتـ̡ کتھ زِ بنی اسرٲیلـ̡ ہٕندِس سارِنٕے جمٲژ سٍتـ̡ وَنُن زِ خداوند سٕندِس برونہہ کُن گژھِو، تِکیازِ تٔمۍ چُھہ تُہٕنزِ کُنہِ ک\n10. تہٕ یِتھ کٔنۍ ہارون بنی اسرائیل کِس سارِنٕے جماعتس مَنٛز کتھ کٔر، زِ تِمو کٔر بیابانن کُن نظر، تہٕ وُچھِتھ گۆو خداوند سُند جلال اوٚبرس مَنٛز ظٲہر۔\n11. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن،\n12. مے چُھہ بنی اسرٲیلِچ بڑبڑاہ بوزمٕژ: تِمن سٍتـ̡ کتھ کرٕن، یێلہِ تہِ گژھہِ ماز کھٮ۪وان تہٕ صبحٲے گژھہِ بٔرِتھ بٔرِتھ۔ تہٕ ژیہ گژھہِ پتاہ زِ بہٕ چُھس خداوند تُہند خدا۔\n13.\\tتہ سپد یہ زِ بٹیر تہِ ووٚتھ تہ لوٚگ ڈیرِ تہ صبحس لوٚگ شبنم میزبانس اندۍ پکھۍ۔\n14.\\tتہ ییلہ شبنم یُس تھوٚد گوو، وچھ بیابان کِس بُتھس پیٹھ اکھ لۅکٹ گول چیز، {یُس زمینس پیٹھ کھورِ ہیو لۅکٹ۔\n15.\\tییلہ بنی اسرائیلیو وُچھ تہ تِمو وون اکھ أکِس سٍتـ̡ یہ {چُھ} مَنا، تکیازِ تِم چھہِ نہٕ زانان زِ یہِ کیا چُھ۔ تہٕ موسىٰ ووٚن تِمَن زِ یہِ چھُ سُہ روٹی یُس خداوند چُھہ کھٮ۪نہٕ خٲطرٕ دِژمُت۔ {یہٕ چُھ...: یا، یہٕ کیا چُھ؟ یا، یہٕ چُھ اکھ حصہٕ}\n16. یہِ چُھ سُہ چیز یُس خداوند چُھ حُکُم دِژمُت، پرٮ۪تھ أکِس شخصہٕ سٕندِ کھٮ۪نہٕ مُطٲبِق جمع کٔرِو، پرٮ۪تھ أکِس انسانس خٲطرٕ اکھ عمر، پنہٕ نِس نفرن ہٕندِس تعدادس مُطٲبق۔ تم نِو پرتھ کانہہ انسان {تِم} خٲطرٕ یُس {چُھ} پننین خیمن منٛز۔ {پرٮ۪تھ کُنہِ خٲطرٕ...: ہیب۔ by the poll, or, head} {persons: Heb. روح}\n17.\\tتہٕ بنی اسرٲیلِو کٔر یۅہے تہٕ کینہہ زیادٕ تہٕ کینہہ کم جمع کٔرِتھ۔\n18.\\tتہٕ یێلہِ تِمو کُنہِ عُمرس سٍتـ̡ میلہِ، یُس واریاہ زیادٕ جمع کٔرِتھ اوسُس نہٕ کانہہ تہِ کٔمی۔ تِمو کٔر پرٮ۪تھ کانٛہہ نفر أمۍ سٕنٛدِ کھٮ۪نہٕ مُطٲبِق جمع۔\n19.\\tتہٕ موسىٰ ووٚن زِ صبحس تام گژھہِ نہ کانہہ تہِ انسان امہِ نشہِ تراوُن۔\n20. باوجوٗد تہِ کٔر نہٕ تِمو موسیٰ سٕنز کتھ بوز۔ مگر یمو منزٕ رودۍ کینہہ صبحس تام اتھ منز، تہٕ أمس ووت کیمۍ تہٕ بدبو، تہٕ موسیٰ اوس تمن سٍتۍ شرارت۔\n21.\\tتہٕ تِمو اوس پرٮ۪تھ صُبحَس سٍتـ̡ سُہ جمع کٔرِتھ، پرٮ۪تھ أکِس انسان سٕندِ کھٮ۪نہٕ مُطٲبِق: تہٕ ییلہ آفتاب گرم گوو، سُہ اوس پۯاوُن۔\n22.\\tتہٕ سپُد یہِ زِ شیٚیمہِ دۅہہ کٔر تِمو دۄگنہٕ روٹی جمع کٔرِتھ، أکِس انسانس خٲطرٕ زٕ عمر: تہٕ جمٲژ ہٕندۍ سٲری حکمران آیہِ تہٕ موسیٰ ہس وونُن۔\n23. تہٕ تٔمۍ ووٚن تِمَن یہِ {سُہ} یُس خداوند چُھ ووٚنمُت، پَگہہ {چُھ} باقٕے مُقدس سبت خداوند سٕندِ خٲطرٕ: یُس تُہۍ بَنِو {از تام}، تہٕ وُچھِو یُس تہٕ وُچھِو یُس وُچھِو۔ تہٕ یُس باقٕے روزان چُھ، سُہ چُھ صُبحَس تام تھاونہٕ خٲطرٕ تھاونہٕ یِوان۔\n24. تہٕ یِمو تھوو یہِ صُبحَس تام، یِتھہٕ کٔنۍ موسیٰ سُند حُکُم اوس، تہٕ اَتھ منٛز اوس نہٕ کانٛہہ تہِ کیمہٕ۔\n25.\\tتہٕ موسىٰ ووٚن زِ یہ کھیوٚن دۅہ۔ تکیازِ از چُھہ خداوند سُند سبت دۅہہ: از تہِ میلہِ نہٕ یہِ کھاہس مَنٛز۔\n26. شیہ دۅہہٕ یِہ جمع کٔرِو۔ مگر سٔتِم دۅہہ، یُس سبت چُھ، اَتھ مَنٛز آسہِ نہٕ کانہہ تہِ۔\n27.\\tتہٕ سپُد سپُد، سٔتِمہِ دۅہہ گٔیہِ کینہہ لُکھ جمع کرنہٕ خٲطرٕ، تہٕ تِمو لوٚب نہٕ کانہہ تہِ۔\n28. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ میٲنۍ حکمن تہٕ قونونن پیٹھ عمل کرنہٕ نِش کٲتِس کالس انکار کٔرِتھ؟\n29.\\tوُچھو، یێمہِ دۅہہ چُھہ خداوند ژیہ سبت دِژمُت، تێمہِ دۅہہ چُھ سُہ دۅہہٕ دِوان۔ سٔتِمہِ دۅہہ گژھہِ نہ کانہہ تہِ انسان پننہِ جایہ نیبر نیرُن۔\n30.\\tیێلہِ لُکھ سٔتِمہِ دۅہہٕ آرام ۔\n31.\\tتہٕ اِسرٲیلِکۍ گرَن وَنُن اَمیُک ناو مَنا: تہٕ یہِ اوس دھنیا ہٕندۍ پٲٹھۍ، سفید۔ تہ امیک ذائقہ اوس ماچھہِ سیتۍ ویفر ہیو {بناونہ آمت}۔\n32.\\tتہٕ موسىٰ ووٚن زِ یہِ چُھ سُہ چیز یُس خداوند حُکُم دِوان چُھ، اَمہ سٍتـ̡ بٔرِتھ تھاوُن یُس پنہٕ نِس نسلن ہٕندِ خٲطرٕ تھاونہٕ یُن۔ یێلہِ تِم وُچھن سُہ روٹی یێمہِ سٍتـ̡ مے ژے بیابانن مَنٛز کھیوٚومُت چُھ، ییلہ بہٕ ژے مصر کہِ سرزمینہٕ پیٹھٕ نیبر کٔرِمُت۔\n33. تہٕ موسىٰ ووٚن ہارونس زِ اَکھ بانہٕ رٔٹِتھ تہٕ اَتھ مَنٛز تھووُن مَنَس سٍتـ̡ بٔرِتھ تہٕ تھاوُن خداوند سٕندِس برونہہ کُن، یُس تُہٕندِس زمانس خٲطرٕ تھاونہٕ یُن۔\n34. یِتھٕ کٔنۍ خداوند موسیٰ سُند حُکُم دِیُت، تِتھٕ کٔنۍ تھوو ہارونن یہِ گوٲہی برونہہ کُن، یُس تھاونہٕ یُن۔\n35.\\tتہٕ بنی اسرٲیلِو کھیوٚو ژتٲجی وُہرۍ منا کھٮ۪وان، یوتام تِم أکِس بستی زمینس مَنٛز وٲتۍ۔ تِمو کھیوٚو منا یوٚت تام تِم کنعان کِس سرزمینس پیٹھ وٲتۍ۔\n36.\\tوۅنۍ چھہ عمرُک دٔہِم حصہ۔","1. تہٕ بنی اسرٲیلٕچ سارِنٕے جماعت دراو خداوند سٕندِ حکمہٕ مُطٲبق گۅنہٕ کِس بیابانہٕ پیٹھٕ سفر، تہٕ رِفیدمَس مَنٛز دِنہٕ آمُت، تہٕ لُکن ہٕندِ خٲطرٕ اوس نہٕ آب چنہٕ خٲطرٕ۔\n2. اَمہِ مۄکھٕ کٔر لُکو موسیٰ سٕندِس سٍتـ̡ طعنہٕ تہٕ وونُن، اسہِ دِیُن آب یُتھ أسـ̡ چیٚو۔ تہٕ موسىٰ ووٚن تِمَن زِ ژےٚ کیازِ چھِو مےٚ سٍتـ̡ طعنہٕ دِوان۔ تہٕ کیازِ چُھکھ خداوند سٕندِس آزمائشس سٍتـ̡ دِوان؟\n3. تہٕ لُکھ گٔیہِ اَتہِ آبہٕ خٲطرٕ پیاس۔ تہٕ لوکو کٔر موسیٰ ہس خلاف بڑبڑاوان تہٕ وونُن، یہِ کیازِ چُھہ ژے اسہِ مصرہٕ منزٕ نیبر نیرِتھ، اسہِ تہٕ سانین شُرین تہٕ سانین چارواین ترشہٕ سٍتـ̡ مارنہٕ خٲطرٕ؟\n4. تہٕ موسیٰ وۆن خداہس نِش فریاد زِ بہٕ کیا کرٕ یِمن لوکن سٍتـ̡ ؟ تم چھہِ میہ کنہِ پتھرِ کرنہ خاطرہ تقریباً تیار۔\n5. تہٕ خداوند ووٚن موسیٰ زِ لوکن برونہہ گژھ تہٕ پانس سٍتـ̡ نِو اسرٲیلٕکۍ بزرگ۔ تہٕ پنٕنۍ لٔرۍ، یَتھ سٍتۍ ژےٚ دٔریاوَس مَنٛز چھُ، رٔٹِو پنُن اَتھٕ تہٕ نیرُن۔\n6. وچھ بہٕ ژے برونہہ کنہِ حوریب کِس کنہِ کنہِ پتھرس پیٹھ کھڑا روزُن۔ تہٕ تُہۍ کٔرِو کَنہِ کَنہِ ٹاس تہٕ اَتھ منٛزٕ نیرِ آب یُتھ لُکھ چیٚنہٕ یِن۔ تہٕ موسىٰ کٔر یہِ اسرٲیلِکۍ بزرگن ہٕندِس نظرس منز۔\n7.\\tتہٕ تٔمۍ ووٚن اتھ جایہِ ماسہ تہٕ مریبہ ناو، یُس بنی اسرائیلن ہٕندِ طعنہ سٍتـ̡ تہٕ تِمو خداوند سٕندِس آزمائشس سٍتـ̡ ونان چُھ، کیا خداوند چُھہ اسہِ مَنٛز کِنہٕ نہٕ؟ {مسح: یعنی فتنہٕ} {مریبہ: یعنی چِیڈنگ، یا، جھگڑ}\n8.\\tپتہٕ آو عمالیق، تہٕ لوٚڑ اِسرٲیلِس سٍتـ̡ رِفیدِمَس مَنٛز۔\n9. تہٕ موسىٰ ووٚن یشوعس زِ اسہِ نِش ژٲرِو تہٕ نیٚبرِو عمالیقس سٍتـ̡ لڑاوُن، پگاہ بہٕ کھٔسِتھ کھٔسِتھ خدایہِ سٕنز لٔر پننِس اتھس منز ہٮ۪تھ۔ {یشوع: عیسیٰ سُند وننہٕ آمُت}\n10.\\tیِتھے پٲٹھۍ کٔر یُس موسیٰ ہن أمس ووٚنمُت اوس، تہٕ لوٚگ عمالیقس سٍتـ̡ تہٕ موسیٰ، ہارون تہٕ حُور گٔیہِ بالہٕ تھزرس پیٹھ۔\n11.\\tتہٕ سپُد ییلہ موسیٰ ہن پنُن اتھہٕ تُل، اسرٲیلِچ فتح حٲصل سپٕز، تہٕ ییلہ تٔمۍ پنُن اتھہٕ ترٛوو، عملیک گوٚو غالب۔\n12.\\tمگر موسیٰ سٕندِ اتھہٕ ٲسۍ گٔبۍ۔ تہٕ تِمو تُل اکھ کٔن، تہٕ تھووُن أمِس تلہ کنہِ، تہٕ سُہ بیوٹھ اَتھ پیٹھ۔ تہٕ ہارون تہٕ حُر روٗدۍ اَتھ اَتھٕ تھوٚد، اَکھ اَکہِ طرفہٕ تہٕ بیٛاکھ دوٚیمہِ طرفہٕ۔ تہٕ تٔمۍ سٕندۍ اتھہٕ ٲسۍ آفتاب لوسنس تام ٹھہران۔\n13.\\tتہٕ یشوع کٔر عمالیق تہٕ تٔمۍ سٕندِس لُکن تلوار ہٕندِ دھار سٍتـ̡ پریشان۔\n14.\\tتہٕ خداوند ووٚن موسیٰ سٕندِس کتابس مَنٛز یہ یادگار تہٕ یشوع سٕندِس کنن مَنٛز پرناوُن، تکیازِ بہٕ کرٕ اسمانس تل عمالک سُند یاداشت پوٗرٕ پٲٹھۍ۔\n15.\\tتہٕ موسىٰ بنوو اکھ قربان گاہ، تہٕ اتھ ناو تھووُن یہوواہنیسی: {یہوواہنیسی: یعنی، خداوند میٲنۍ جھنڈٕ}\n16.\\tتکیازِ تٔمۍ ووٚن زِ خداوند چُھ عہد کورمُت زِ خداوند کرِ نسل در پیر عمالیقس سٍتـ̡ جنگ۔ {کیازِ...: یا، امہ مۅکھہ زِ امالیک سند اتھہ چھہ رب سٕندِس تختس خلاف، لہذا وغیرہ} {خداوند چُھ...: ہیب۔ خداوند سٕندِس تختس پیٹھ اتھہٕ}","1. ییلہ موسیٰ سٕندِس مٲلہِ مدیانُک پادٕرۍ یِتھ، یێلہِ یہِ بوز زِ خداین چُھ موسیٰ سٕندِ خٲطرٕ تہٕ تٔمۍ سٕندِس قومہٕ خٲطرٕ کٔرمُت، {تہٕ} زِ خداوند چُھ اسرٲیلِس مصرہٕ منزٕ نیبر کڈمُت۔\n2. اَمہِ پَتہٕ نِیوو موسىٰ سٕنز خانٛدارِنہِ زِپورہ یُس أمِس واپس سوزنہٕ پتہٕ،\n3. تہٕ تٔمۍ سٕندۍ زٕ نیچوۍ۔ یتھ منز اکھ {اوس} گرشوم سُند ناو اوس۔ تکیازِ تمۍ ووٚن میہ چھہ اکس عجیب زمینس منز اکھ اجنبی رودمُت: {گرشوم: سہ چھہ اتہِ اکھ اجنبی شخص}\n4. تہٕ بییِس {اوس} الیزر سُند ناو۔ میٲنِس مٲلہِ سٕندِ خدایہِ سٕندِ خٲطرٕ، {وۆنُن، اوسُس میٲنۍ مدد، تہٕ کٔرٕن میہ فرعون سٕنزِ تلوار نِش بچاوُن: {الیعزر: یعنی، میون خدا چُھ مدد}\n5.\\tتہٕ یتھرو، موسیٰ سُند پیہر، آو پننین نیچوین تہٕ زنانہِ سٍتـ̡ موسیٰ سٕندِس بیابانس مَنٛز، یێتہِ تٔمۍ خدایہ سٕندِس پہاڑس پیٹھ ڈیرٕ ترٲو۔\n6. تہٕ تٔمۍ ووٚن موسیٰ سٍتـ̡، بہٕ چُھس تُہند مٲلہٕ یتھرو تہٕ تٔمۍ سٕندِس زٕ نیچوِس سٍتـ̡ تہٕ تٔمۍ سٕندِس زٕ نیچوِس سٍتـ̡ آمُت۔\n7.\\tتہٕ موسیٰ گۆو پننِس مٲلس سمکھنہٕ خٲطرٕ، تہٕ کٔرٕن سَجود تہٕ بوسہ دِتھ۔ تہٕ تِمو پرژھ اکھ أکِس {تِہٕندِ} فلاح و بہبود۔ تہٕ تِم آیہ خیمہ منز۔{ویلفیئر: ہیب۔ امن}\n8. تہٕ موسىٰ ہن ووٚن پننِس مٲلس سٍتـ̡ یُس خداوند فرعونس تہٕ مصرین سٍتـ̡ اسرٲیلـ̡ خٲطرٕ کورمُت اوس، تہٕ یُس سارِنٕے مصیبت یُس تِمن وتہِ سٍتـ̡ آمُت اوس، تہٕ کِتھہٕ پٲٹھـ̡ دِژ خداوند تِمن بچاونہٕ۔ {آ...: ہیب۔ لٔبِتھ تِم لٔبۍ}\n9. تہٕ یتھرو کٔر تتھ سارِنٕے نیکی خٲطرٕ خوش یُس خداوند اسرٲیلِس سٍتـ̡ کورمُت اوس، یُس تٔمۍ مصری ہٕندِ اتھہٕ نِش نجات دِژمُت اوس۔\n10.\\tتہٕ یتھرو ووٚن، بابرکت ہو خداوند، یٔمۍ تۅہہ مصری ہٕندِ اتھہٕ نِش تہٕ فرعون سٕندِ اتھہٕ نِش نجات دِژ، یٔمۍ لوکن مصرن ہٕندِ اتھہٕ نِش نجات دِژمٕژ۔\n11.\\tوۅنۍ چھہ میہ پتاہ زِ خداوند چھہ سارِنٕے دیوتاہن کھۅتہٕ بوڈ آسان، تکیازِ یتھ چیزس منز تِمو فخر سان ورتاوان اوس، تِمن ہٕندِس پیٹھ۔\n12. تہٕ یتھرو، موسیٰ سٕندِس مٲلہِ سٕندِس مٲلس سٍتـ̡ خدایہ سٕندِ خٲطرٕ نِش دِنہٕ تہٕ قربانی دِنہٕ۔ تہٕ ہارون تہٕ سارِنٕے اسرٲیلِکۍ بزرگ آو موسیٰ سٕندِس مٲلِس سٍتـ̡ خدایہِ سٕندِس سٍتـ̡ روٹی کھٮ۪نہِ۔\n13. تہٕ پَگہہ سپُد یہِ زِ موسیٰ بِہتھ لُکن ہُند فیصلہ کرنہٕ خٲطرٕ، تہٕ لُکھ روٗد صُبحہ پیٹھٕ شامَس تام موسیٰ سٕندِس سٍتـ̡ کھڑا۔\n14.\\tتہٕ ییلہ موسیٰ سٕندِس مٲلہِ وُچھ یُس تٔمۍ لُکن سٍتـ̡ کران چُھ، تٔمۍ ووٚن یہِ کیا چُھہ یُس تُہۍ لُکن سٍتـ̡ کران چُھ؟ ژیہ کیازِ چھکھ پانس کُنی بِہتھ، تہٕ سٲری لوکھ چھہِ صبحہ پیٹھٕ توے سٍتۍ کھڑا روزان؟\n15. تہٕ موسىٰ ووٚن پننِس مٲلِس سٍتـ̡ کیازِ لُکھ چھِ میانہِ نِش خدایہ سٕندِس نِش پرژھنہٕ خٲطرٕ یِوان:\n16.\\tییلہ تِمن کانہہ معاملہ آسان چھُ، تِم چھِ میانہِ نِش یِوان۔ تہٕ بہٕ چُھس أکِس تہٕ أکِس درمیان فیصلہ کران، تہٕ بہٕ چُھس خدایہ سٕندِ قوانین، تہٕ تٔمۍ سٕندِس قوانینس زانان۔ {اکھ...: ہیب۔ اکھ انسان تہٕ تٔمۍ سُنٛد سٲتھی}\n17.\\tتہٕ موسیٰ سٕندِس مٲلس ووٚن أمِس زِ یُس تہٕ ژے کران چُھہ سُہ چُھ نہٕ اصل۔\n18.\\tژے گژھہِ پزۍ پاٹھۍ ژیہ تہ یہ لوکھ یُس ژے سیتۍ چھہِ، تکیازِ یہ چیز چھہ تۅہہِ خاطرہ واریاہ بوب۔ تُہۍ چھِو نہٕ یہ پانہٕ پانہٕ انجام دِتھ ہیکان۔ {توے وِلٹ...: ہیب۔ ژیہ چھکھ ژھیٹھ گٔژھتھ}\n19. وۅنۍ بوزو میانہِ آواز، بہٕ دِیہ ژے مشورہ، تہٕ خدا آسہِ توے سٍتۍ: لوکن ہٕندِ خٲطرٕ بٔنِو خدایہ سٍتـ̡ یُتھ تہٕ خدایس تام وجوہات واتناوُن:\n20. تہٕ تِمن ہیچھناوُن احکام تہٕ قوانین، تہٕ تِمن ہٲوِن وَتھ یتھ مَنٛز تِمن پَکُن پَکُن، تہٕ سُہ کٲم کرٕنۍ یُس تِمن کرُن۔\n21. توے کٔرِو سارِنٕے لُکن مَنٛز قٲبل انسان، یِم خدایہ سٍتـ̡ خوفزدہ چھِ، حقیقژ ہٕندِس نفرت، لالچ سٍتـ̡ نفرت۔ تہٕ یِمن پیٹھ تھاوُن {یِتھ}، {یِتھ} ساسہٕ بٔدۍ حُکُمران ، {تہٕ} ہتہٕ ہتن ہٕندِ حُکُمران ، پنژاہن ہٕندِس حُکُمران تہٕ دَہن ہٕندِس حُکُمران ۔\n22. تہٕ تِم گژھن پرٮ۪تھ وقتس منز لوکن ہُند فیصلہ کرنہٕ، تہٕ یہِ گژھہِ زِ تِم کرِ پرٮ۪تھ کانہہ بٔڈ معاملہٕ تۅہہِ نِش انن، مگر پرٮ۪تھ لۄکٹِس معاملس سٍتـ̡ تِم فٲصلہٕ کرِ، یِتھے پٲٹھۍ گژھہِ تۅہہِ ہٕندِ خٲطرٕ سہل تہٕ تِم گژھن توے سٍتـ̡ بوج۔\n23.\\tیێلہِ تہٕ خدا چُھہ یہ کٲم کٔرِتھ، تێلہِ گژھِو تۅہہِ برداشت کٔرِتھ، تہٕ یِم سارِنٕے لُکھ تہِ گژھن امن سان پننہِ جایہ گژُھن۔\n24.\\tیێلہِ بوٗز موسیٰ سٕندِس مٲلہِ سٕنز آواز تہٕ کورُن سُہ سورُے یُس تٔمۍ سُند ونُن اوس ۔\n25.\\tتہٕ موسىٰ کٔر سارِنٕے اسرٲیلِس مَنٛز قٲبل نفر ژٲرِتھ، تہٕ بنووُن تِم لُکن ہٕندِس حُکُمران، ساسہٕ بٔدۍ ہٕندِس حُکُران، ہتہٕ بٔدۍ ہٕندِس حُکُران، پنژاہن ہٕندِس حُکُمران تہٕ دَہن ہٕندِس حُکُمران سٍتـ̡ ۔\n26.\\tتہٕ تِمو کٔر پرٮ۪تھ وقتس مَنٛز لُکن ہُند فیصلہ یُس تِمو موسیٰ سٕندِس نِش أنِتھ، مگر پرٮ۪تھ لۄکٕٹِس معاملس سٍتـ̡ اوس تِمو پانہٕ فیصلہ کران۔\n27. تہٕ موسیٰ دِژ پننِس مٲلس نیرُن۔ تہٕ سُہ گوٚو پننِس سرزمینس منٛز۔","1.\\tتریمہِ ریتس منز ییلہ بنی اسرائیل مصر کِس سرزمینہِ منزہ نیبر نیرِ، تمہ دۅہہ آو تم سینا کِس بیابانس منز۔\n2.\\tتِکیازِ تِم ٲسۍ رِفیدِم نِش نیرِتھ سینا کِس صحراہس منز آمٕتۍ، تہٕ بیابانن مَنٛز گٔمٕتۍ۔ تہٕ تتہِ لوٚگ اسرائیلن پہاڑس برونہہ کُن ڈیرٕ۔\n3. تہٕ موسیٰ ووت خدایہِ نِش تہٕ خداوند دِژ پہاڑ پیٹھٕ أمِس بُلاونہٕ تہٕ وَنُن یعقوب سٕندِس گرس تہٕ بنی اسرٲیلِس وَنُن۔\n4.\\tژے وُچھمُت یُس میہ مصرین سٍتـ̡ کورمُت، تہٕ کِتھہ پٲٹھـ̡ چُھہ ژے عقاب ہٕندِس پکھس پیٹھ نِتھ تہٕ ژے پانس کُن أنِمُت۔\n5. تێلہِ یێلہِ یێلہِ ژے پٔزۍ پٲٹھۍ میانہِ آوازِ ہٕنز اطاعت کٔرِو، تہٕ میانہِ عہدٕ پورٕ کٔرِو، تێلہِ بٔنِو ژے سارِنٕے لُکن ہٕندِ کھۅتہٕ میانہِ خٲطرٕ اکھ خاص خزانہٕ: یێلہِ سارِنٕے زمینہٕ چُھہ میٲنۍ سٍتـ̡ ۔\n6. تہٕ تُہۍ بٔنِو میانہِ خٲطرٕ پادٕرین ہٕنز بادشٲہی تہٕ اکھ مقدس قوم۔ یِم لفظ چِھہ تۅہہ بنی اسرٲیلِس سٍتـ̡ کتھ کرٕنـ̡ ۔\n7. تہٕ موسیٰ آو تہٕ لُکن ہٕندٮ۪ن بزرگن بُلاونہٕ تہٕ تِمن ہٕندِس بُتھِس برونہہ کُن تھووُن یِم سٲری لفظ یِم خداوند أمِس حُکُم دِژمٕتۍ۔\n8. تہٕ سارِوٕے لُکو دِژ اِکہٕ وٹہٕ جواب تہٕ وونُن، یُس خداوند سُند کتھ چُھ کٔرمٕژ۔ تہٕ موسىٰ دِژ لُکن ہُند کلام خداوند سٕندِس نِش واپس۔\n9.\\tتہٕ خداوند ووٚن موسیٰ سٍتـ̡ یێلہِ بہٕ چُھس ژے نِش گٔنِس اوٚبرس مَنٛز آمُت، یێلہِ بہٕ چُھس ژے سٍتـ̡ کتھ کرنہٕ وِزِ بوزنہٕ یِنہٕ تہٕ تێہہِ ہمیشہٕ پٲٹھـ̡ پى۪ٹھ۔ تہٕ موسیٰ ہن ووٚن لُکن ہٕندِ کلام۔\n10. تہٕ خداوند ووٚن موسیٰ زِ لُکن نِش گژھ تہٕ تِمن دۅہہ تہٕ پگہٕ پاک کرُن، تہٕ تِم گژھن پَنٕنۍ پلو چھلاون،\n11. تہٕ تریمہِ دۅہہ گژھہِ تیار روزُن: تریمہِ دۅہہ گژھہِ خداوند سارِنٕے لُکن ہٕندِس نظرس منز کوہ سینا کِس پٲٹھۍ۔\n12.\\tتہٕ ژے کرو اندۍ پکھۍ لُکن ہٕندِس حدس تام وُچھِتھ زِ یُس تہِ پہاڑس پیٹھ اتھہٕ لاگُن، یُس تہِ پہاڑس اتھہٕ لاگہِ سُہ گژھہِ یقینا مارنہٕ۔\n13.\\tاتھ گژھہِ نہ کانہہ اتھہ اتھہ لاگُن، مگر تس گژھہِ پزۍ پاٹھۍ کنہِ کٔرِتھ یا گولۍ لگاونہ یُن۔ چاہے سُہ جانور آسہِ یا انسان، یہ روزِ نہٕ زندٕ: ییلہ بُرٕ وُجہِ زیچھر، تِم گژھن پہاڑس پیٹھ۔ {ٹرمپیٹ: یا، کارنیٹ}\n14.\\tتہٕ موسیٰ ووت پہاڑ پیٹھٕ لُکن تام تہٕ کوٚرُن لُکن پاک ۔ تہٕ تِمو ٲسۍ پنٕنۍ پلو چھلان۔\n15.\\tتہٕ تٔمۍ ووٚن لُکن زِ تریمہِ دۅہہ گژھہِ تیار روزُن: پننہِ زنانہِ نِش گژھ نہٕ۔\n16.\\tتہٕ یہ آو تریمہِ دۅہہ صبحس دۅہہ، یێلہِ گٔیہِ گرٛاے تہٕ بجلی تہٕ پہاڑس پیٹھ گۆٹ اوبر، تہٕ بُرٕچ آواز ٲس سٮ۪ٹھاہ بَڑ۔ تاکہ کیمپَس منٛز موجود سٲری لُکھ گٔیہِ تھرتھر۔\n17. تہٕ موسیٰ کٔر لُکھ خۅداہس سٍتـ̡ مُلاقات کرنہٕ خٲطرٕ خٲمہٕ منزٕ نیبر۔ تہٕ تِم ٲسۍ پہاڑ کِس بٔنِس حصس پیٹھ کھڑا۔\n18.\\tتہٕ کوہ سینا اوس پوٗرٕ پٲٹھۍ أکِس دوٚہس پیٹھ، تکیازِ خداوند آو اتھ پیٹھ نارس منز، تہٕ اَمہ سُند دوٚہہ ووت بھٹہِ ہٕندِس دھوہٕکۍ پٲٹھۍ، تہٕ سورُے پہاڑ لوٚگ سٮ۪ٹھاہ تھرتھر۔\n19.\\tییلہ بُرِ ہٕنز آواز زیٖٹھۍ بجہِ تہٕ بَڑِ بٔرِتھ گٔیہ، موسىٰ کٔر کتھ تہٕ خداین دیُت أمِس اَکہِ آوازِ سٍتـ̡ جواب۔\n20. تہٕ خداوند ووت پہاڑ سینا کِس تھزرس پیٹھ، تہٕ خداوند بُلوو موسیٰ پہاڑ کِس تینتٲلس پیٹھ۔ تہٕ موسیٰ ووت تھوٚد۔\n21. تہٕ خداوند ووٚن موسیٰ سٕندِس نِش بۄن گژھُن، لُکن ہُند حکم دِیُن، نتہٕ تِم گژھن خداوند سٕندِس نِش نظر دِنہٕ خٲطرٕ، تہٕ یِمو مَنٛز واریاہ مارٕ گٔیہِ۔ {چارج: ہیب۔ مقابلہٕ}\n22. تہٕ یِم پادٕرۍ تہِ یِم خداوند سٕندِس نزدیک یِن، گژھن پنُن پان پاک کرُن، یُس خداوند تِمن پیٹھ پھٔٹِتھ گژھِ۔\n23. تہٕ موسىٰ ووٚن خداونس زِ لُکھ ہیکو نہٕ سینا کِس پہاڑس تام وٲتِتھ، تکیازِ ژے چُھکھ اسہِ حکم دِژمُت زِ پہاڑس اندۍ پٔکھۍ کرو حدٕ تہٕ تقدس کٔرِو۔\n24. تہٕ خداوند ووٚن أمِس زِ ژٔٹِھہ، بۄن وُن تہٕ ژٕ گژھہِ پانس سٍتـ̡ ہارون سٍتـ̡ ہیوٚر کھسُن، مگر پادٕرۍ تہٕ لُکھ گژھن نہٕ خداہس نِش کھسنہٕ خٲطرٕ، یێلہِ سُہ تِمن پیٹھ پھٔٹِتھ دِنہٕ۔\n25. یێمہِ کِنۍ ووت موسیٰ لُکن نِش تہٕ تِمن سٍتـ̡ کتھ کٔرِتھ۔","1. تہٕ خداین کٔر یِم سٲری لفظ وَنُن،\n2. بہٕ چُھس خداوند تُہند خدا، یُس ژے مصر کہِ سرزمینہٕ منز، غلامی ہٕندِس گرٕ منزٕ نِش نِش نیبر کٔرِمُت۔ {غلامی: ہیب۔ خادم}\n3. چانہِ آسہِ نہٕ میانہِ برونہہ کانہہ تہِ خدا۔\n4.\\tژے بناو نہ پانس خٲطرٕ کانہہ تہِ کھٔنِتھ شبیہہ یا کُنہِ تہِ چیزُک ہشر یُس آسمانس منز {چُھ} آسہِ، یا یُس {چُھ} بۅنہ کنہِ زمینس مَنٛز، یا یُس زمینہِ تل آبس مَنٛز {چُھ}۔\n5. تہٕ ژٕ گژھ نہٕ تِمن سٍتـ̡ سجدہ کٔرِتھ، تہٕ تِمن ہٕنز خدمت کٔرٕن: کیازِ بہٕ چُھس خداوند تُہند خدا چُھس اکھ حسد کرن وول خدا، یُس میہ سٍتـ̡ نفرت کرن وٲلِس بچن سٍتـ̡ مٲلن ہٕنزِ بدکاری ہُند اظہار کران چُھ، یُس میہ سٍتـ̡ نفرت کران چُھ،\n6. تہٕ یِمن منز ساسہٕ بٔدۍ یِم میہ محبت کران چھِ، تہٕ میٲنۍ حُکمن پیٹھ عمل کرٕنـ̡ ۔\n7. تُہۍ گژھ نہٕ پننِس خدایہِ سُند ناو بیکار رٔٹِتھ رٔٹِتھ ۔ تکیازِ خداوند کرِ نہٕ تس بے گناہ یُس تٔمۍ سُند ناو بیکار رٔٹِتھ آسہِ۔\n8. سبت دۅہ یاد تھاوُن، یہ پاک تھاونہٕ خٲطرٕ۔\n9. شیٚن دۅہن کٔرِو محنت، تہٕ پنٕنۍ سٲری کٲم کٔرِو:\n10. مگر سٔتِم دۅہ چُھہ خداوند تُہٕندِس خدایہِ سُند سبت دۅہہ: اَتھ مَنٛز کُنہِ تہِ کامہِ کٔرِتھ تہٕ نہ پنُن نیچو، نہ پنُن کورِ، نہ پنُن نوکر، نہ پنُن نوکر، تہٕ پنُن چاروا، تہٕ تُہند اجنبی یُس تُہٕندِس دروازس اندر چُھہ:\n11. شیٚن دۅہن خٲطرٕ بنوو خداوند اسمانس تہٕ زمین، سمندر، تہٕ تِمن مَنٛز موجود سارِنٕے چیز، تہٕ سٔتِم دۅہہٕ آرام دِژُن، تێمہِ مۅکھہٕ کٔر خداوند سبت دۅہہٕ برکت تہٕ پاکیز۔\n12. پننِس مٲلِس تہٕ ماجہِ ہُند احترام کٔرِو: یُتھ تُہٕندِس خدایہِ سٕندِس خداہس دِنہٕ آمٕژ زمینہِ پیٹھ روزِ تُہٕندِس دۅہہٕ زیٖٹھۍ۔\n13.\\tژہ گژھ نہ مارُن۔\n14.\\tزنا کرُن نہٕ۔\n15. ژٕ گژھ نہٕ ژورِ نِنہٕ۔\n16.\\tتوے گژھ نہٕ پننِس ہمساین خلاف اپُز گوٲہی دِنہٕ۔\n17.\\tتوے گژھِ نہٕ پننِس ہمساین ہٕندِس گرس ہُند لالچ کٔرِتھ، نہ ہمساین سٕنزِ خادمہ سٕنز، نہ تٔمۍ سٕندِس نوکرس سٍتۍ، نہ تٔمۍ سٕندِس نوکرس سٍتـ̡ تہٕ نہ تٔمۍ سٕندِس گٔرِس سٍتـ̡ تہٕ کُنہِ تہِ چیزس سٍتـ̡ یُس تہندِس ہمساین ہٕندِس گرس سٍتـ̡ آسہِ۔\n18.\\tتہٕ سارِوٕے لُکو وُچھ گرٛاے تہٕ بجلی تہٕ بُلہٕ ہُند شور، تہٕ پہاڑ وُچھُن، تہٕ ییلہ لوکو وُچھ، تِمو ہیوٚت تہٕ دوٗر کھڑا۔\n19. تہٕ تِمو ووٚن موسیٰ سٍتـ̡ تہٕ أسـ̡ بوزو، مگر خدایہ گژھہِ نہٕ اسہِ سٍتـ̡ کتھ کرنہٕ، نتہٕ أسـ̡ مرُن۔\n20. تہٕ موسیٰ ہن ووٚن لُکن زِ خوفہٕ نہٕ کرُن، یِکیازِ خدا چُھ تُہُند ثٲبت کرنہٕ خٲطرٕ آمُت تہٕ تٔمۍ سُند خوف گژھہِ تُہٕندِس بُتھِس برونہہ کُن، یُتھ نہٕ تُہۍ گۅناہ کٔرِو۔\n21.\\tتہٕ لُکھ گٔیہِ دوٗر تہٕ موسیٰ ووت گٔنِس گٔنِس کُن یَتھ منز خدا {اوس}۔\n22. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ یِتھٕ پٲٹھـ̡ تہٕ تُہہِ وُچھِو اسرٲیلِس سٍتـ̡ وُچھمُت زِ بہٕ چُھس اسمانہٕ پى۪ٹھٕ ژے سٍتـ̡ کتھ کٔرمٕژ۔\n23. تہٕ ژٕ بناوو نہٕ میانہِ سٍتـ̡ رۄپہٕ ہٕندِ دیوتا، تہٕ نہٕ بنٲوِو پانس سٍتـ̡ سۄنہٕ دیوتا۔\n24.\\tژٕ کٔرِکھ میٚژِ ہُند قربان گاہ، تہٕ اَتھ پؠٹھ کٔرِکھ پنٕنۍ زٲلِتھ نذران، تہٕ پنٕنۍ کۅکرٕ تہٕ پنٕنۍ بیل قربان کٔرِتھ، یێلہِ بہٕ یێلہِ تہٕ بہٕ ژے نِش دِنہٕ یِوان۔\n25. تہٕ اگر ژٕ مےٚ کنن ہُند قربان گاہ بناوُن، تہٕ ژٕ بناو نہٕ یہ ژٔٹِتھ کنن سٍتـ̡ بَناوُن، تکیازِ اگر ژے پنُن اوزار تُلِتھ تُلِتھ چُھہ سُہ آلودہ کٔرِتھ۔ {بَناوُن...: ہیب۔ تِم بناو ہیوِنگ سٍتۍ}\n26. تہٕ نہ گژھ تۅہہ میٲنۍ قربان گاہس تام ہیرن پیٹھ کھسُن، یُتھ زن تُہند ننگہٕ گژھہِ نہٕ اَتھ پیٹھ ظٲہر سپدُن۔","1.\\tوۅنۍ چھہِ یِم فیصلہٕ یِم تۅہہِ برونہہ کُن دِنہٕ یِن۔\n2. یێلہِ تہٕ یێلہِ کانہہ عبرانی نوکر ہیوٚن، سُہ گژھہِ شیہ ؤری خدمت کرُن، تہٕ سٔتِمِس مَنٛز گژھہِ سُہ کُنہِ کُنہِ وریہِ آزاد نیرُن۔\n3.\\tاگر سُہ پانَے اژُن آسہِ، سُہ گژھہِ پانَے نیبر، اگر أمِس خاندر آسہِ، تیلہِ گژھہِ تسٕنزِ زنانہٕ أمِس سٍتـ̡ نٮ۪بر۔ {پانے: ہیب۔ پننس جسمس سۭتۍ}\n4. اگر تٔمۍ سٕندِس مٲلکَس أمِس خانٛدارِنۍ دِژمٕژ آسہِ، تہٕ تٔمِس زاے نیچوۍ یا کورِ۔ خانٛدارِنۍ تہٕ تٔمۍ سٕنٛدِ شُرِ آسہِ أمۍ سٕنٛدِس مٲلکَس سٕندِ، تہٕ سُہ گژھِ پانَے نٮ۪بر۔\n5.\\tتہٕ اگر نوکر سیدِ سیود وَنُن زِ بہٕ چُھس پننِس آقا، پننہِ خانٛدارِنہِ تہٕ پننین شُرین سٍتۍ محبت کران۔ بہٕ گژھ نہٕ آزاد نیران: {شُل...: ہیب۔ وَنُن وَنُن}\n6. تیلہٕ کرِ تٔمۍ سُند آقا أمِس قاضن نِش أنِتھ۔ سُہ تہِ أنِن أمِس دروازس پیٹھ، یا دروازٕ کھورِ پیٹھ۔ تہٕ تٔمۍ سُند آقا کرِ تٔمۍ سٕندِس کَن ژٔلِتھ ژٔلِتھ۔ تہٕ سُہ کرِ ہمیشہٕ أمِس خدمت۔\n7. تہٕ اگر کانہہ مرد پنٕنۍ کورِ نوکر بننہٕ خٲطرٕ کٕنِ، سُہ گژھِ نہٕ نٮ۪بر نیرُن۔\n8.\\tاگر سۅ پننِس آقا سٍتـ̡ خۅش کرِ، یٔمۍ أمِس پانس سٍتـ̡ منگنی کٔرمٕژ آسہِ، تیلہِ گژھہِ سُہ أمِس نجات دِنہٕ: أمِس کُنہِ اجنبی قومس کٕننہٕ خٲطرٕ آسہِ نہٕ أمِس کانہہ طاقت حٲصِل کٔرِتھ، یێلہِ أمِس سٍتـ̡ دھوکہٕ دِنہٕ آمُت چُھ۔ {مہربانی...: ہیب۔ اَمہِ کِس نظرَس مَنٛز بُرٕ بٔنِتھ وَغٲرٕ}\n9.\\tتہٕ اگر أمِس پننِس نیچوِس سٍتـ̡ منگنی کٔرِتھ آسہِ، سُہ کرِ کورِ ہٕندِس طریقس سٍتـ̡ أمِس سٍتـ̡\n10. اگر سُہ أمِس بیاکھ {زنانہ} نِن۔ تٔمۍ سُند کھیٛن، تٔمۍ سُند لباس، تہٕ خانٛدرُک فرض، گژھ نہٕ سُہ کم کرنہٕ۔\n11.\\tتہٕ اگر سُہ یِم تریہ أمِس نِش کرِ، تیلہِ گژھہِ سۄ پٲنسہٕ ورٲے آزاد نیران۔\n12.\\tیُس انسان مارِ، سُہ مرُن، سُہ گژھہِ یقینا مارنہٕ یُن۔\n13. تہٕ اگر کانہہ انسان انتظار کرِ، مگر خدا کرِ سُہ تٔمِس اتھس مَنٛز۔ تیلہِ کٔرٕ بہٕ ژےٚ اکھ جاے مقرر ییتہِ سُہ ژلہِ۔\n14.\\tمگر اگر کانہہ انسان پننِس ہمساین پیٹھ بے تکلف گژھِ، تہٕ أمِس دھوکہ دِتھ مارنہٕ خٲطرٕ۔ ژے نِیُن سُہ میانہِ قربان گاہ پیٹھ، یُتھ سُہ مرُن۔\n15.\\tیُس پننِس مٲلِس یا ماجہِ ہُند مارٕ دِیہِ، سُہ گژھہِ یٔقیٖنی طور مارنہٕ یُن۔\n16.\\tیُس انسان ژوٗرِ نِتھ کٕنِتھ کٕنِتھ یا اگر سُہ أمِس اتھس مَنٛز لبنہٕ ییہِ، سُہ یِیہِ یٔقیٖنی طور مارنہٕ۔\n17.\\tیُس پننِس مٲلِس یا ماجہِ بد دُعا دِیہِ، سُہ گژھہِ یُس یٔقیٖنی طور مارنہٕ یُن۔ {لعنت: یا، بد عذاب}\n18.\\tتہٕ اگر انسان رٔلِتھ کوشش کرِ، تہٕ اَکھ أکِس کٔنہِ سٍتۍ، یا مُٹھہٕ سٍتۍ، تہٕ سُہ چُھ نہٕ مَرُن، مگر سُہ چُھہ بسترٕ تھاوُن: {بییِس: یا، تٔمۍ سٕندِس ہمساین}\n19.\\tاگر سُہ دُبارٕ وۅتھان تہٕ پنہٕ نِس لٔرِس پیٹھ نیبر نیرِ، تیلہِ گژھہِ یُس أمِس مارُن دِیہِ، صرف سُہ گژھِ پنُن وقتُک ضایع گژھنُک معاوضہٕ دِنہٕ، تہٕ سُہ کرِ پوٗرٕ پٲٹھـ̡ شفا بخشُن۔ {نقصان...: ہیب۔ تٔمۍ سُنٛد ختم}\n20. تہٕ اگر کانہہ انسان پننِس نوکرس یا پننِس نوکرس لٔرِ سٍتـ̡ مارِ تہٕ سُہ چُھہ تٔمِس اَتھٕ تَل مَرُن۔ تس گژھہِ یقینا سزا دِنہٕ۔ {سزا: ہیب۔ انتقام}\n21.\\tاَمہ باوجود اگر سُہ اکھ یا زٕ دۅہ روزِ، تٔمِس گژھہِ نہٕ سزا دِنہٕ: کیازِ سُہ چھُ تٔمِس پونسہٕ۔\n22.\\tیێلہِ مرد کوشش کرِ، تہٕ زنانہِ ہٕندِس بچہٕ سٍتـ̡ تکلیف دِیہِ، یێلہِ تٔمِس پھل نیرِ، تہٕ توتہِ گژھہِ نہٕ کانہہ شرارت سپدِ، تێلہِ گژھہِ تس یُس زنانہِ ہُند خاوند دِیہِ۔ تہٕ سُہ کرِ ججن ہٕندِ مُطٲبق معاوضہٕ۔\n23. تہٕ اگر کانہہ شرارت گژھہِ، تیلہِ دِیُن زندگی خٲطرٕ زندٕ،\n24. أچھ بدلہٕ أچھ، دندٕ بدلہٕ دند، اتھہٕ بدلہٕ اتھہٕ، کھۄر بدلہٕ کھۄر،\n25.\\tزالنہٕ خٲطرٕ زالُن، زخم بدلہٕ زخم، سٹرایپس بدلہٕ پٹی۔\n26.\\tتہٕ اگر کانہہ انسان پننِس نوکر سٕنزِ أچھ یا پننہِ دٲیرِ ہٕنزِ أچھ مارِ تہٕ سُہ گٔیہِ۔ سُہ دِیہِ أمِس أچھ ہٕندِ خٲطرٕ آزاد کرنہٕ۔\n27. تہٕ اگر سُہ پننِس نوکر سُند دند یا دٲیرِ ہُند دند کڈِ۔ سُہ دِیہِ أمِس دنٛدٕ خٲطرٕ یلہٕ تراوُن۔\n28.\\tاگر کانہہ بیل کٲنسہِ مردس یا زنانہِ ہُند گُرِ دِیہِ، تِم گژھِ نہٕ مٔرِتھ، تیلہِ گژھہِ داند کٔرِتھ تہٕ تٔمۍ سُند ماز گژھہِ نہٕ کھٮ۪نہٕ۔ مگر بیلُک مٲلک گژھہِ تراوُن۔\n29.\\tمگر اگر پتھ کالس منز بیل پننس سینگ سٍتۍ زور دِوان آسہِ، تہٕ أمِس آسہِ أمِس مٲلکَس نِش گوٲہی دِنہٕ آمٕژ، تہٕ تٔمۍ آسہِ نہٕ أمِس اندر تھوومُت، بلکہ چھُ أمِس اکھ مرد یا زنانہٕ مارمُت۔ بیلس یِیہِ کَنہٕ لاگنہٕ، تہٕ أمۍ سُنٛد مٲلِک تہِ یِیہِ مارنہٕ۔\n30.\\tاگر أمِس پٲنسہٕ دِنہٕ ییہِ، تیلہِ گژھہِ سُہ پننہِ زُو تاوان دِنہٕ یُس أمِس پیٹھ دِنہٕ ییہِ۔\n31.\\tأمِس کُنہِ نیچوِس کُنہِ نیچوِس یا کورِ ہٕندِس دٔسۍ دِنہٕ آمُت، یَتھ فیصلہٕ مُطٲبِق گژھِ أمِس سٍتۍ کرنہٕ یُن۔\n32.\\tاگر داند کٲنسہِ نوکر یا نوکرِ دِیہِ۔ سُہ دِیہِ پننِس مٲلکَس ترٕہ شیکل رۄپہٕ، تہٕ بیلس یِیہِ کَنہٕ لاگنہٕ۔\n33.\\tتہٕ اگر کانہہ انسان کھۄڈ کھٔنِتھ تہٕ اَتھ منز کانہہ بیل یا گَرٕ پییہِ۔\n34.\\tکھۅنہِ ہُند مٲلک کرِ اَمہ کِس مٲلکَس پٲنسہٕ دِنہٕ۔ تہٕ مرُن {درندٕ} آسہِ أمِس۔\n35.\\tتہٕ یێلہِ أکِس شخٕص سُند بیل بییِس سٕندِس دَگ دِیہِ، سُہ چُھ مرُن۔ پتہٕ کٕنَن تِم زندٕ داند کٕنُن، تہٕ امِکۍ پونسہٕ تقسیم کٔرِن۔ تہٕ مٔرِتھ تہِ گژھن تِم تقسیٖم کرنہٕ۔\n36. یا اگر یہ معلوم آسہِ زِ بیل اوس پتھ کالس منز زور دِوان، تہٕ تٔمۍ سٕندِس مٲلکَن اوس نہٕ أمِس اندر تھوومُت۔ سُہ کرِ یقینا بیلس بدلہٕ دِنہٕ۔ تہٕ مرُن آسہِ تٔمۍ سُند پنُن۔","1.\\tاگر کانہہ انسان کانہہ بیل یا کۅکر ژوٗرِ نِتھ مارِتھ یا کٕنُن۔ سُہ کرِ أکِس بیلس خٲطرٕ پانژھ بیل تہٕ ژور دانٛد أکِس دانٛدٕ خٲطرٕ بحال کرنہٕ۔ {یا اکھ دانٛد: یا، یا ژھاوٕل}\n2. اگر کانہہ چور پھٹان لبنہٕ ییہِ، تہٕ مارنہٕ ییہِ تہٕ سُہ مرُن، تٔمِس خٲطرٕ گژھہِ نہٕ کانہہ خون۔\n3. اگر آفتاب تس پیٹھ طلوع گژھہِ، تتہِ گژھہِ تس خٲطرٕ خون۔ {کیازِ} سُہ پزِ پوٗرٕ معاوضہٕ دِنہٕ۔ اگر نہٕ أمِس کانہہ تہِ آسہِ، تیلہِ یِیہِ سُہ ژوٗرِ خٲطرٕ کٕننہٕ۔\n4.\\tاگر ژوٗرِ یٔمۍ سٕندِس اتھس منز زِندٕ لبنہٕ ییہِ، چاہے سُہ داند آسہِ، یا گَرٕ آسہِ، یا کۅکر۔ سُہ کرِ دۄگنہٕ بحال۔\n5.\\tاگر کانہہ انسان کھیت یا انگور کھیوٚن تہ پننس درندس منز تراوِ تہ بییس انسان سٕندِس کھہس منز کھیوٚن۔ پننِس کھہٕ ہٕندِس بہتٔریٖن، تہٕ پنٕنِس انگور باغس منز کرِ سُہ معاوضہٕ۔\n6.\\tاگر نار پھوٚلِتھ تہٕ کانٹٮن منز رٔٹِتھ، یُتھ مکایہِ ہُند ڈھیر یا کھڑا مکایہ، یا کھہہ، کھٮ۪نہٕ یِن۔ یُس نار دِیُت سُہ کرِ یقینا معاوضہٕ۔\n7.\\tاگر کانہہ شخص پننِس ہمساین رژھراونہٕ خٲطرٕ پٲنسہٕ یا چیز دِیہِ، تہٕ سُہ گژھہِ أمِس مکانہٕ منزٕ ژوٗرِ نِنہٕ۔ اگر چور لبنہٕ ییہِ، سُہ دِیُن دۄگنہٕ دِنہٕ۔\n8.\\tاگر نہٕ چور لبنہٕ ییہِ، تیلہِ گژھہِ مکانُک مٲلک ججن نِش اننہٕ، {یہِ وچھنہٕ خٲطرٕ} زِ تٔمۍ چھا پننِس ہمساین ہٕندِس مالس پیٹھ اتھہٕ تھوومُت۔\n9.\\tپرٮ۪تھ قٕسمٕچ جُرمَس خٲطرٕ، {چاہے سُہ بیلہٕ خٲطرٕ، گَرٕ خٲطرٕ، دانٛدٕ خٲطرٕ، پلو خٲطرٕ، {یا} کُنہِ تہِ قٕسمٕچ رٲومٕژ چیزٕ خٲطرٕ، یُس {بییِہ} أمِس چیلنج کران آسہِ، دۄشوٕنی فریقن ہُند سبب گژھہِ قاضن برونہہ کُن یُن۔ {تہٕ} ییٚمِس جج مذمت کرِ، سُہ کرِ پننِس ہمساین دۄگنہٕ معاوضہٕ۔\n10.\\tاگر کانہہ انسان پننِس ہمساین رژھراونہٕ خٲطرٕ اکھ گَر، یا دانٛد، یا کُنہِ تہِ جانور دِیہِ۔ تہٕ سُہ چُھ مرُن، یا زخمی گژھِ، یا ژلنہٕ یِن، کانٛہہ تہِ انسان وُچھِتھ {یہ}:\n11.\\tیِمن دۅشوٕنی درمِیان گژھہِ خداوند سُند حلف زِ تٔمِس چُھہ نہٕ پننِس ہمساین ہٕندِس مالس پیٹھ اتھہٕ تھوومُت۔ تہٕ امیک مالک کرِ {امہ} قبول، تہٕ سُہ کرِ نہٕ {یہ} اصل۔\n12.\\tاگر یہ أمِس نِش ژوٗرِ نِنہٕ ییہِ، سُہ کرِ امہِ کِس مٲلکَس معاوضہٕ۔\n13.\\tاگر یہ ٹُکرٕ ٹُکرِ پھٹِتھ پھٹنہٕ ییہِ، {تیلہ} گژھہِ سُہ {شہادت} خٲطرٕ أنِتھ، {تہٕ} سُہ کرِ نہٕ سُہ یُس ژٹنہٕ آمُت چھُ۔\n14.\\tتہٕ اگر کانہہ انسان پننِس ہمساین نِش {گژھہِ} قرضہٕ نِتھ تہٕ أمِس مجروح گژھہِ، یا مٔرِتھ آسہِ، اَمہ سُند مٲلک {آسُن} نہٕ آسُن، سُہ کرِ یٔقیٖنی طور اَمہ سٍتـ̡ رٔٹِتھ ۔\n15.\\t{مگر}اگر امیک مٲلک {be} اتھ سٍتۍ آسہِ، سہ کرِ نہ {it} اصل: اگر یہ {be} کرایہ دار {چیز} آسہِ، سہ آو تمۍ سندِ کرایہ پیٹھ۔\n16.\\tتہٕ اگر کانہہ مرد کٲنسہِ نشہِ منگنی آسہِ نہٕ آمٕژ تہٕ أمِس سٍتـ̡ روزِ، سُہ کرِ أمِس پَنٕنـ̡ زنانہٕ بننہٕ خٲطرٕ۔\n17. اگر تٔمۍ سُند مول أمِس دِنہٕ نِش پوٗرٕ انکار کرِ، سُہ کرِ کُنوارٮ۪ن ہٕندِ داج مُطٲبق پٲنسہٕ۔ {تنخواہ: ہیب۔ وزن}\n18.\\tژیہ گژھہِ نہ کُنہِ ڈٲڑِ زندٕ روزُن۔\n19. یُس تہِ درندٕ سٍتـ̡ روزِ، سُہ گژھہِ یٔقیٖنی طور مارنہٕ یُن۔\n20. یُس کُنہِ تہِ خدایہ سٕندِ خٲطرٕ قربان کرِ، صرف خداوند سٕندِ خٲطرٕ، سُہ گژھہِ پوٗرٕ پٲٹھـ̡ تباہ کرنہٕ۔\n21.\\tژے کٔرِو نہٕ کٲنسہِ اجنبی سٍتـ̡ تٔمِس سٍتـ̡ ظُلم کٔرِتھ، تکیازِ تم ٲسِو مصر کِس سرزمینس مَنٛز اجنبی ۔\n22.\\tکُنہِ بیواہ یا بے باپ بچہٕ سٍتـ̡ گژھِ نہٕ تُہٕندِس سٍتـ̡ دِنہٕ یُن۔\n23.\\tاگر تِمن کُنہِ تہِ پٲٹھۍ، تہٕ تِم میہ کُنہِ تہِ فریاد دِن، بہٕ بوزٕ یٔقیٖنی طور تِہُند فریاد بوزُن۔\n24. تہٕ میون قہر گژھہِ گرم تہٕ بہٕ مارٕ ژے تلوار سٍتۍ۔ تہٕ تہنز زنانہٕ گژھن بیواہ تہٕ تہند بچہٕ یُس باپ آسن۔\n25.\\tاگر ژے میانین لوکن منز کُنہِ تہِ پٲنسہٕ دِیُن، تیلہِ گژھِو نہٕ تٔمِس سود خور سٍتـ̡ بٔنِتھ تہٕ تٔمِس سٍتـ̡ رُجوُن دِیُن۔\n26. یێلہِ تہِ ژے پننِس ہمساین ہُند پوشاک گروی نِتھ تہٕ دِیُن سُہ أمِس دِنہٕ یُس آفتاب لوسُن:\n27.\\tاَمہ مۅکھہ چُھہ تٔمۍ سُند پوشہٕ، یہ چھُ تٔمۍ سٕندِس مسلس خٲطرٕ پوشہٕ: کَتہِ گژھہِ شوٚنگنہٕ؟ تہٕ یێلہِ سُہ میانہِ کُنہِ سٍتـ̡ بوزنُک سٍتـ تکیازِ بہٕ چُھس مہربان ۔\n28. ژے گژھ نہٕ دیوتاہن بد عزتی کٔرٕن، تہٕ نہ کٔرٕن پنہٕ نِس لوکن ہٕندِس حکمرانس لعنت۔ {دیوتا: یا، جج}\n29.\\tژے کٔرِو نہٕ پنہٕ نِس پۄختہٕ مٮ۪وٕ تہٕ شرابُک گۄڈنیُک مٮ۪وٕ پیش کرنہٕ خٲطرٕ ژیر کٔرِتھ، تہٕ پنہٕ نِس نیٚچوِس سٍتـ̡ دِیُن میہ دِنہٕ۔ {گوڈنِک...: ہیب۔ تیری مکمل آسن} {شراب: عبرانی۔ اوٚش}\n30. یتھے پاٹھۍ کرو پننین بیلن سٍتۍ، تہٕ پننین دامن سٍتـ̡ سَتھ دۅہہٕ۔ ٲٹھمہِ دۅہہ دِیُن ژے مے دِنہٕ۔\n31. تہٕ تم گژھو میانہِ خٲطرٕ مقدس انسان: تہٕ نہٕ کھیٛن کھاہس منٛز درندن ہُند ماز کھٮ۪وان۔ تُہۍ ترٛٲوِو یہِ ہونین نِش۔","1.\\tژے گژھِ نہٕ اپُز خبر دِنہٕ: بدکارن سٍتـ̡ تھاوُن نہٕ پَنُن اتھہٕ بدکارن سٍتـ̡ بێیہِ گوٲہی دِنہٕ۔ {raise: or, receive}\n2. بد کار کرنہٕ خٲطرٕ گژھ نہٕ کُنہِ بٔڈِس سٍتـ̡ پیروی کٔرٕنـ̡ نۂ کُنہِ وجہٕ سٍتـ̡ کتھ کرٕنـ̡ {فیصلہٕ}: {Speak: Heb. جواب}\n3. تہٕ نہ گژھ تٔمۍ سٕندِس مقصدس منز غریبس سٍتـ̡ س�\n4.\\tاگر ژیہ پنُن دُشمن سُند بیل یا تٔمۍ سٕندِس گٔرِس گمراہ گٔژھِتھ میلہِ، تیلہِ گژھہِ یُس دُبارٕ أمِس نِش واپس۔\n5.\\tاگر ژے وُچھِو تٔمِس سُند گَردٕ یُس تۅہہِ سٕندِس بوجھس تَل لٔگِتھ آسہِ، تہٕ تٔمِس مدد کرنہٕ خٲطرٕ کرِ نہٕ، تیلہِ کٔرِو تٔمِس سٍتـ̡ مدد۔ {تہٕ...: یا کیا ژٕ کٔرِکھ أمِس مدد کرُن؟ یا، تہٕ تہٕ کرٕ تٔمِس خٲطرٕ پنُن کاربار تراوُن: ژٕ گژھ یقینا أمس سٍتۍ رٔلنہٕ خٲطرٕ تراوُن}\n6.\\tژے گژھ نہٕ پننِس غریبس سُند فیصلہ تٔمۍ سٕندِس مقصدس منز رٔٹِتھ۔\n7.\\tکُنہِ غلط معاملہٕ نِش دور تھاوُن۔ تہٕ بے گناہ تہٕ نیک چھکھ نہٕ ژے ماران: کیازِ بہٕ کٔرٕ نہٕ بدکارن ہُند جواز دِنہٕ۔\n8. تہٕ تُہۍ گژھِ نہٕ کانہہ تحفہٕ نِن، تکیازِ یہ تحفہٕ چُھ دانشمندن اوٚن کران، تہٕ نیکوکارن ہٕندِس کلامس غلط بناوان۔ {عقلمند: ہیب۔ وچھن}\n9.\\tتہِ گژھِ نہٕ کٲنسہِ اجنبی سُند دِل زانان، یێلہِ تہٕ ژے چھِو أکِس اجنبی سُند دِل زانان، یێلہِ تہٕ تُہۍ ٲسِو مصر کِس سرزمینس مَنٛز اجنبی ٲسِو۔ {دل: ہیب۔ روح}\n10. تہٕ شیہ ؤری پَنٕنۍ زمینہٕ ووت تہٕ اَمہ کِس پھلس مَنٛز جمع کٔرِو۔\n11.\\tمگر سٔتِم ؤری تہِ تراوُن تہٕ رٔٹِتھ روزُن۔ یُتھ تُہٕندِس لُکن ہٕندِس غریبَس کھٮ۪ن: تہٕ یُس تِم تراوان چھِ، تِم کھٮ۪نہٕ کھٮ۪ن۔ یِتھے پٲٹھۍ کٔرِو تُہۍ پنٕنۍ انگور سٍتۍ، {تہٕ} پنٕنِس زیتونس سٍتۍ۔ {زیتون یارڈ: یا، زیتون کُل}\n12.\\tشیہ دۅہہ کرو ژیہ پنٕنۍ کٲم تہٕ سٔتِمہِ دۅہہٕ آرام کرُن، یُتھ تُہٕندِس گَردٕ تہٕ گَرٕ آرام کرُن، تہٕ تُہٕنزِ دٲیرِ ہُند نیچو تہٕ اجنبی روزِ تازٕ۔\n13. تہٕ یِمن سارِنٕے چیزن مَنٛز یُس میہ ژےٚ ووٚنمُت چُھ، تہٕ باقین دیوتاہن ہُند ناو گژھہِ نہٕ زانہہ تہٕ نہ بوزُن۔\n14.\\tؤریَس مَنٛز تریہ لٹہِ کٔرِکھ میانہِ خٲطرٕ دعوت۔\n15.\\tژے تھاوُن خمیرٕ روٚس روٹی ہُند دعوت: (یێلہِ میہ ژے حُکُم دِژمُت چھُ، سَتَن دۅہن بێخمیر روٹی کھیوٚن، یێلہِ تۅہہ ہٕندِس مُقرر وقتس مَنٛز، تکیازِ اَتھ مَنٛز آو تُہۍ مصرہٕ پیٹھٕ درٛامُت، تہٕ کانٛہہ تہِ گژھِ نہٕ میانہِ برونہہ کُن خٲلی ظٲہر سپدُن:)\n16. تہٕ فصلُک دعوت، پننہِ محنتُک گۄڈنیُک پھل، یُس ژے کھہَس مَنٛز ووومُت چھُ، تہٕ جمع کرنُک دعوت، یُس ؤری کِس ٲخرس مَنٛز چُھ، یێلہِ ژے کھہَس مَنٛز پنٕنۍ محنتہٕ جمع کٔرِو۔\n17. ؤریس منز تریہ لٹہِ گژھن تہند سٲری مرد خداوند خدایہ سٕندِ برونہہ کُن ظٲہر۔\n18.\\tژے کٔرِو نہٕ میانہِ قربانی ہُند خوُن خمیر روٹی سٍتـ̡ پیش کرنہٕ۔ نہ روزِ میانہِ قربانی ہُند چربی صبحس تام۔ {قربانی: یا، دعوت}\n19.\\tپننہِ زمینہِ ہٕندِس گۄڈنِکِس پھلَس مَنٛز گۅڈنیُک پھلہٕ یُس تُہٕندِس خدایہ سٕندِس گَرَس مَنٛز انُن۔ ژے گژھ نہ ماجہ ہٕندِس دۄدس منز شُر وُچھُن۔\n20. وچھ بہٕ ژے برونہہ کُن اکھ فرشتہ سوزان، یُس ژے وتہِ رُکاونہٕ خٲطرٕ تہٕ ژے اَننہٕ خٲطرٕ یُس مے تیار کورمُت چھُ۔\n21.\\tأمِس نِش گژھِو خبردار تہٕ تٔمۍ سٕنزِ آوازِ ہٕنز اطاعت کٔرِو، أمِس کٔرِو نہٕ اشتعال دِنہٕ۔ تکیازِ سُہ کرِ نہٕ تۅہہِ ہٕنزِ غلطی معاف: تکیازِ میون ناو {چُھ} تس منز۔\n22. مگر اگر ژٕ پزۍ پٲٹھـ̡ تسٕنزِ آوازِ ہٕنز اطاعت کٔرِو، تہٕ یێلہِ بہٕ سُہ سُہ کتھ کٔرِتھ کٔرِو۔ تیلہٕ بنہٕ بہٕ تہندٮ۪ن دُشمنن ہُند دُشمن تہٕ تہندٮ۪ن مُخٲلفن ہُند دُشمن۔ {اکھ مخٲلف...: نتہٕ بہٕ کرٕ تِمن مُتٲثِر یِم ژےٚ مُتٲثِر کٔرِتھ}\n23.\\tمیٲنۍ فرشتہ گژھہِ توے برونہہ کُن، تہٕ ژے امورین نِش، حتی، پیرزی، کنعانی، حیوی تہٕ یبوسی نِش اننہٕ۔\n24. تہندٮ۪ن دیوتاہن برونہہ کُن کٔرِو نہٕ تِمن ہٕنز عبادت تہٕ تہندِ کامہِ پتہٕ کٔرِو نہٕ تِمن ہٕندِس بُتھِ ہُند پٲٹھۍ۔\n25. تہٕ تُہۍ کٔرِو خداوند پنُن خدا، تہٕ سُہ کرِ تُہٕنزِ روٹی تہٕ تُہٕندِس آبس برکت دِنہٕ۔ تہٕ بہٕ کٔرٕ ژے منزٕ بیمارِ نِش۔\n26. چانہِ زمینس منز گژھِ نہ کانہہ تہِ جوان تراوُن، تہٕ نہ گژھِ بنجر روزُن، چانہِ دۅہن ہُند تعداد بہٕ پورٕ کرُن۔\n27. بہٕ سوزٕ پنُن خوف تہٕ تِمن سارِنٕے لُکھ تباہ کٔرِتھ یِمن نِش ژے یِنہٕ یِن، تہٕ بہٕ کَرٕ تُہٕندِس سارِنٕے دُشمن پانس کُن پٲٹھۍ۔ {بیکس: ہیب۔ گردن}\n28.\\tتہٕ بہٕ سوزٕ ژے برونہہ کُن ہارنیٹ، یُس حوی، کنعانی تہٕ ہِٹی ژے برونہہ کُن کڈِ۔\n29. بہٕ کٔرٕ نہٕ تِم أکِس ؤریس منز ژےٚ برونہہ کُن کٔڑِتھ۔ نتہٕ زمین گژھہِ ویران تہٕ میدانُک درندٕ گژھہِ ژےٚ خٕلاف بڑان۔\n30. بہٕ کٔرٕ تِم ژےٚ برونہہ کُن ژٔٹِتھ ، یوتام نہٕ ژٕ بٔڑِتھ تہٕ زمینُک وٲرث بنِو۔\n31. تہٕ بہٕ کٔرٕ بحر احمر پیٹھٕ فلسطینن ہٕندِس سمندرس تام، تہٕ صحرا پیٹھٕ دریاوس تام تہٕ بہٕ کٔرٕ زمینہٕ کین بسکینن تہٕ تُہندس اتھس مَنٛز۔ تہٕ ژے کٔرِو تِم پانس برونہہ کُن کٔڑِتھ۔\n32. تُہۍ کٔرِو نہٕ تِمن سٍتـ̡ تہٕ تِمن سٍتـ̡ تہندِس خداہس سٍتـ̡ کانہہ عہد کرُن۔\n33. تِم گژھن نہٕ تُہٕندِس سرزمینس مَنٛز روزنہٕ، یێلہِ تِم تہندِس خداہَن ہٕنز عبادت کٔرِو، یێلہِ تہٕ یێلہِ تہٕ یێلہِ تہندِس خداہَن ہٕنز عبادت کٔرِو، یێلہِ تہٕ یێلہِ تہٕ یێلہِ تہندِس خداہس سٍتـ̡ بٔنِتھ تہٕ یێلہِ تہندِس","1. تہٕ تٔمۍ ووٚن موسیٰ سٕندِس نِش، تہٕ ہارون، نداب تہٕ ابیہو، تہٕ اسرٲیلٕکۍ ستتھ بزرگ۔ تہٕ دوٗر پوٗزا کٔرِو۔\n2. تہٕ موسیٰ گژھہِ صرف خداوند سٕندِس نزدیک، مگر تِم گژھن نہٕ نزدیک۔ نہ گژھن أمِس سٍتۍ لوٗکھ کھسنہٕ۔\n3. تہٕ موسیٰ آو تہٕ لُکن ووٚن خداوند سٕندِ سٲری کلام تہٕ سارِنٕے فیصلہٕ، تہٕ سارِنٕے لُکن دِژ اَکہٕ آوازِ سٍتـ̡ جواب تہٕ وونُن، یِم سٲری لفظ خداوند سٕندِ وَننہٕ آمٕتۍ چِھ، تِم کٔرِو أسـ̡ کرنہٕ۔\n4. تہٕ موسىٰ لیوکھ خداوند سٕندِ سٲری کلام، تہٕ ووٚتھ صبحٲے تہٕ کٔرٕن بالہٕ تَل اکھ قربان گاہ تہٕ بَہ تھَم بنوُن، یُس اسرٲیلٕکۍ بہن قبیلن ہٕندِ مطٲبق بنوو۔\n5.\\tتہٕ سوٗزۍ بنی اسرٲیلِکۍ جوان یِمو زٲلِتھ نذرانہ پیش کٔرِتھ تہٕ کٔرٕکھ خداوند سٕندِ خٲطرٕ دِنہٕ آمٕژ دِنہٕ۔\n6.\\tتہٕ موسیٰ ہن نٮ۪صف خون، تہٕ تھووُن بیسنن مَنٛز۔ تہٕ نصف خونُک یُس تٔمۍ قربان گاہس پیٹھ چھُک۔\n7. تہٕ تٔمۍ تُل عہد نامہٕ ہٕنز کتاب، تہٕ لُکن ہٕندِس سامعین مَنٛز پٔرِتھ، تہٕ تِمو ووٚن، یُس خداوند چُھ ووٚنمُت سُہ سُہ کٔرِو أسۍ کرُن، تہٕ فرمانبردار۔\n8. تہٕ موسیٰ ہن روٚٹ خون، تہٕ لُکن پیٹھ چھُکُن تہٕ وونُن، وُچھِو عہدُک خون، یُس خداوند یِمن سارِنٕے کلامَن مُتلق ژےٚ سٍتـ̡ کورمُت چُھ۔\n9. اَمہِ پَتہٕ ووت موسیٰ، ہارون، ندب تہٕ ابیہو، تہٕ اسرٲیلٕکۍ ستتھ بزرگ۔\n10.\\tتہٕ تِمو وُچھ اسرٲیلُک خدا: تہٕ تٔمۍ سٕندِس قدمن تَل اوس یہِ نیلم کٔنِچ پکی کٲم تہٕ یِتھٕ پٲٹھۍ اوس یہِ آسمانُک جسم۔\n11.\\tتہٕ بنی اسرائیل کین رئیسن پیٹھ تھوو نہٕ تٔمۍ پنُن اتھہٕ، تہٕ تِمو وُچھ خدایہ، تہٕ کھٮ۪وان تہٕ کھٮ۪وان چِھ۔\n12.\\tتہٕ خداوند ووٚن موسیٰ سٕندِس نِش یِم پہاڑس مَنٛز کھٔسِتھ تہٕ اَتہِ روزُن، تہٕ بہٕ دِیہٕ ژے کنن ہٕنزِ میزہٕ، تہٕ اکھ شریعت تہٕ حُکُم یُس مے لیوکھمُت چھُ۔ یُتھ زن تِمن ہیچھناوُن۔\n13. تہٕ موسیٰ ووٚتھ تہٕ تٔمۍ سُند وزیر یشوع تہٕ موسیٰ ووت خدایہ سٕندِس پہاڑس پیٹھ۔\n14. تہٕ تٔمۍ ووٚن بزرگن زِ یێلہِ روزو اسہِ خٲطرٕ، یوتام نہٕ أسۍ دُبارٕ تۅہہِ نِش یِن، تہٕ وُچھِو ہارون تہٕ حُور تہٕ یێلہِ کٲنٛسہِ ہُند کانہہ کٲم آسہِ، سُہ گژھہِ تِمن نِش یِنہٕ۔\n15. تہٕ موسیٰ ووت پہاڑس پیٹھ، تہٕ اوٚبرن ووت پہاڑس پیٹھ۔\n16. تہٕ خداوند سُند جلال روٗد سینا کِس پہاڑس پیٹھ، تہٕ اوٚبرن ووت اتھ شیٚن دۅہن تہٕ سٔتِم دۅہہ کوٚر تٔمۍ موسیٰ سٕندِس اوبرس منزٕ بُلوو۔\n17.\\tتہٕ خداوند سٕندِ جلال ہُند نظارٕ اوس بنی اسرٲیِل ہٕندِس نظرس مَنٛز پہاڑ کِس تینتٲلس پیٹھ نار کھٮ۪نٕکۍ پٲٹھۍ۔\n18.\\tتہٕ موسیٰ ژاو اوٚبرس منز، تہٕ ووت تس پہاڑس منز، تہٕ موسیٰ اوس ژتٲجی دۅہن تہٕ ژتٲجی رٲژ پہاڑس منز۔","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2. بنی اسرٲیلِس کٔرِو کتھ زِ تِم اَن میہ اکھ نذرانہ دِن: یُس پریتھ انسان پننہِ دِلہٕ سٍتـ̡ دِلہٕ سٍتـ̡ دِیہ، تُہۍ کٔرِو میٲنۍ نذرانہ نِنـ̡ ۔ {مے أنِو: ہیب۔ رٔٹِو میانہِ خٲطرٕ} {پیشکش: یا، ہیو پیش کَرُن}\n3. تہٕ یہِ چھُ سُہ نذرانہ یُس تِمن نِش نِیُن۔ سون تہٕ رۄپھ تہٕ پیتل، {نذران: یا، نذرانہ کٔرِتھ}\n4.\\tتہٕ نیوٗل تہٕ واگن تہٕ سرخ تہٕ باریک کُن تہٕ ژھاوٕل {مس }، {باریک ...: یا ریشم}\n5.\\tتہٕ کۅکرِ ہٕندِس کھالس رنٛگ کٔرِتھ رنٛگ کٔرِتھ، تہٕ بٔرِن ہٕنزِ کھال تہٕ لٔکرِ رنٛگ کٔرِتھ،\n6. گاشہٕ خٲطرٕ تیل، مسح کرنہٕ خٲطرٕ تہٕ مٔدٕر بخور خٲطرٕ تیل،\n7. اونکس کٔنۍ، تہٕ کٔنہِ یِن ایفوڈس منز تہٕ سینہ پلیٹس منز تھاونہٕ۔\n8. تہٕ تِم بناوُن میہ اکھ پناہ گاہ۔ تاکہ بہٕ روزٕ تمن منٛز۔\n9.\\tیُس بہٕ ژے ہاوان چُھس، خیمہ ہُند نمونہٕ تہٕ امہِ کین سارِنٕے آلاتن ہُند نمونہٕ تہٕ یِتھے پٲٹھۍ بناوُن تہِ۔\n10.\\tتہٕ تِم بناوَن اَکھ صندوق: اَمہ ہُند زیچھر زٕ ہُرٕ تہٕ اَمہ ہُند زیچھر تہٕ اَمہ ہُند اکھ کیوبِٹ تہٕ اَمہ ہُند تھزر آسہِ۔\n11.\\tتہٕ ژے کرِو اتھ اندر تہٕ نیبَر خٲلص سۄنہٕ سٍتـ̡ ؤلِتھ تہٕ اَتھ پیٹھ بناوُن سۄنہٕ سُند تاج۔\n12.\\tتہٕ ژے تراوُن اتھ خٲطرٕ ژور سۄنہٕ وٲج تہٕ ژۅشونی کونن منز تراوُن۔ تہٕ اَمہِ کِس أکِس طرفہٕ زٕ حلقہٕ تہٕ دوٚیمہِ طرفہٕ زٕ حلقہٕ۔\n13.\\tتہٕ ژے بناوُن لٔکرِ لٔکرِ سٍتـ̡ تہٕ سۄنہٕ سٍتـ̡ س�\n14. تہٕ ژے ترٲوِو صندوقہٕ کِس اندۍ پکھۍ حلقن مَنٛز، یُتھ صندوق ییہ تِمن سٍتـ̡ تُلنہٕ۔\n15.\\tڈنجہ گژھن صندوق کِس حلقس منز: تم گژھن نہ اتھ منز نِنہٕ۔\n16.\\tتہٕ ژے تھاوُن سُہ گوٲہی یُس بہٕ ژے دِیہِ۔\n17. تہٕ تُہۍ بناو رحمتٕچ نشست خٲلص سۄنہٕ: زٕ کیوبِٹ سُند زیچھر تہٕ اَمہ ہُند اکھ کیوبِٹ تہٕ نصف کھجر۔\n18. تہٕ ژے بناو زٕ کروبِم سۄن، {of} مارنہٕ آمٕژ کٲم کٔرٕن، رحمتٕچ نشستہٕ ہٕندِس دۄن اندس منز۔\n19.\\tتہٕ اَکہِ اندس پیٹھ بناوُن اکھ کروب، تہٕ بییِس اندس پیٹھ کرُب بناوُن: رحمتٕچ نشستہٕ تہٕ کرُکھ کرُن اَمہِ کِس دۄن اندس پیٹھ۔ {of...: یا، رحم کرسی سیٹ کِس معاملس منز}\n20.\\tتہٕ کرُبِم پَنٕنـ̡ پَکھہٕ سٍتـ̡ ؤلِتھ، تہٕ تِہٕندِس بُتھِس پَکھہٕ سٍتـ̡ ؤلِتھ تہٕ تِہٕندِس بُتھِس سٍتـ̡ وُچھِن اَکھ أکِس کُن نظر۔ رحمتٕچ نشستس کُن گژھن کروبن ہٕندۍ بُتھ آسن۔\n21.\\tتہٕ ژے تھاوُن رحمتٕچ کرسی ہیوٚر صندوقس پیٹھ۔ تہٕ صندوقس منز تھاو ژے گوٲہی یُس بہٕ ژے دِیہِ۔\n22. تہٕ اَتہِ میلہٕ بہٕ ژے سٍتـ̡ رحمتٕچ کرسی پیٹھ، دۄن کروبِمن درمِیان یُس گوٲہی ہٕندِس صندوقس پیٹھ چُھہ، سارِنٕے {چیزن} ہُند یُس بہٕ تُہٕندِس حُکمس مَنٛز دِیہٕ تُہٕندِس سٍتـ̡ دِنہٕ۔\n23.\\tژے بناو اکھ میز تہِ شیٹم لٔکرِ: زٕ کیوبِٹ تہٕ اکھ کیوبِٹ تہٕ اکھ کیوبِٹ تہٕ اکھ کیوبِٹ تہٕ اَمہ ہُند تھزر اکھ کیوبِٹ تہِ۔\n24.\\tتہٕ تُہۍ کٔرِو اتھ خٲلص سۄنہٕ سٍتـ̡\n25.\\tتہٕ ژے بناو اتھ اندۍ اتھہٕ کھجرُک اکھ کنارٕ، تہٕ ژے بناو اتھ اندۍ سنہٕ سنہٕ تاج۔\n26.\\tتہٕ ژے بناو اتھ خٲطرٕ ژور سۄنہٕ حلقہٕ، تہٕ ژۄن کونن مَنٛز تھووُن یِم ژۄن فٹن پیٹھ چھِ۔\n27.\\tاندس پیٹھ گژھن وٲج ڈنڈن ہنزن جایژن پیٹھ میزہ تھاونہ خاطرہ آسن۔\n28.\\tتہٕ ژے بناوُن لٔکرِ لٔکرِ سٍتـ̡ سۄنہٕ سٍتـ̡ سٍتـ̡ یُتھ تِمن سٍتـ̡ دُبارٕ تُلنہٕ ییہِ۔\n29.\\tتہٕ تُہۍ بناوِو یِمن ہٕندِس برتن تہٕ چمچۍ، تہٕ یِمن ہٕندِس پوشہٕ تہٕ پیالہٕ سٍتـ̡ بَناوُن: خٲلص سۄنہٕ سٍتـ̡ بناوُن۔ {to...: یا، تراوُن}\n30. تہٕ ژے تھاوُن ہمیشہ میانہِ برونہہ کُن میزس پیٹھ روٹی ہاونہٕ۔\n31.\\tتہٕ ژے بناو خٲلص سۄنہٕ سٍتـ̡ شمعدان سٍتـ̡ بَناوُن: تٔمۍ سٕنزِ لٔرۍ، تٔمۍ سٕنزِ لٔرۍ، تٔمۍ سٕندِس گۅپھ تہٕ پوشہٕ یِتھۍ آسن۔\n32.\\tتہٕ اَمہ کِس اندۍ پکھۍ نیرن شیہ لنجہ۔ اکہ طرفہٕ شمعدان چہ تریہ لنجہِ تہٕ دوٚیمہِ طرفہٕ شمعدان ہنزِ تریہ لنجہِ:\n33.\\tتریہ پیالہ یِم بادام ہیو بناونہٕ آمٕتۍ، اَکہِ لنجہِ منز اکھ گۅپھ تہٕ اکھ پوش۔ تہٕ دوٚیمس لنجہِ منز بادامکۍ پٲٹھۍ بناونہٕ آمٕتۍ تریہ پیالہٕ، {سۭتۍ} اکھ گۅپھ تہٕ اکھ پوش: تِتھے پٲٹھۍ چھِ شیہ لنجہِ منز یِم شمعدان منزٕ نیران چھِ۔\n34.\\tتہٕ شمعدان منز گژھن ژور پیالہٕ یِم بادام ہِش بناونہٕ آمٕتۍ، {یِمن ہٕندِس گۅپھ تہٕ پوشہٕ سٍتۍ﴾۔\n35.\\tتہِ آسہِ امی ہنزن دۅن لنجہِ تلہ کنہِ اکھ گۅنڈ تہ امی ہنزن دۅن لنجہِ تلہ کنہِ اکھ نۅپ، تہ امی ہنزن دۅن لنجہِ تلہ کنہِ اکھ گنڈ، یُس شیہ لنجہ نیبر نیران آسہِ۔\n36.\\tتِہٕندِس نِش تہٕ تِہٕنزِ لنجہِ ہِوٕے آسٕنۍ: یہ سورُے آسہِ خٲلص سۄنہٕ سٍتـ̡ اکھ مارنہٕ آمٕژ کٲم۔\n37.\\tتہٕ تُہۍ بناوِو اَمہِ سٕندِ سَتھ شمعہٕ تہٕ تِم کرِ اَتھ سٍتـ̡ گاش دِنہٕ۔ {گاش: یا، گژھہِ کھسُن} {یہ: ہیب۔ امیک بُتھ}\n38.\\tتہٕ اَمہ ہٕندِس ٹنگس تہٕ اَمہ سٍتـ̡ آسہِ خٲلص سۄنہٕ سٍتـ̡ ۔\n39.\\tیِمو سارِنٕے بانو سٍتـ̡ کرِ سُہ خالص سۄنہٕ سُند ٹیلنٹ ۔\n40.\\tتہٕ وُچھِو تہٕ تِمن ہٕندِس نمونہٕ سٍتـ̡ بناوُن، یُس تۅہہِ پہاڑس مَنٛز ہاونہٕ آمُت اوس۔ {کُس...: ہیب۔ یُس ژے وُچھُن}","1. امہِ علاوٕ بناوُن خیمہ {سٍت} دَہ پردٕ سٍتۍ، نیوٗل تہٕ واگن تہٕ سرخ رنٛگہٕ۔ {چالاکی...: ہیب۔ أکس چالاک کامہٕ سٕنٛز کٲم، یا کڑھائی کرن وٲل سٕنٛز کٲم}\n2.\\tأکِس پردُک زیچھر گژھہِ ٲٹھ تہٕ وُہ کیوبٹ تہٕ أکِس پردُک کھجر گژھہِ ژور کیوبِٹ۔\n3. پانژھ پردے گژھن اکھ أکِس سٍتۍ جوڑنہٕ یِن۔ تہٕ {باقٕے} پانژھ پردٕ {گژھِ} اکھ أکِس سٍتۍ جوڑنہٕ۔\n4. تہٕ ژے بناو کپلنگس منز سیلویجس پیٹھ اکس پردس پیٹھ نیلِس رنگک لوپ۔ تہٕ یِتھے پٲٹھۍ کرو تۅہہ {بییِہ} پردٕ کس اندس منز، دویمِس جوڑس منز۔ {سیلویج: پلوُک اکھ کنارٕ یُس تیوٗت ووُنمت چُھ زِ یہٕ ہیکہٕ نہٕ کھولِتھ}\n5.\\tاکس پردس منز گژھہِ پنژاہ لوپ بناوُن، تہ پردہ کس اندس پیٹھ بناو پنژاہ لوپ یُس دوٚیمس پردس منز {چھہ}۔ تاکہ لوپ ہیکن اکھ أکس تھپھ کٔرتھ۔\n6.\\tتہٕ ژے بناو پنژاہ سۄنہٕ تہٕ پردٕ رٔلِتھ رٔلِتھ تہٕ یہ گژھہِ اکھ خیمہ ۔\n7.\\tتہٕ ژے بناو ژھاوٕنـ̡ ہٕندِس پردٕ سٍتـ̡ یُس خیمہٕ سٍتـ̡ پردٕ بناوُن: کاہ پردٕ بناوُن۔\n8.\\tاکہ پردُک زیچھر گژھہِ ترہ کیوبٹ تہ اکس پردس ہند کھجر ژور کیوبٹ: تہ کاہ پردہ گژھن اکۍ سے پیمانس پیٹھ۔\n9.\\tتہٕ ژے کرِ پانژھ پردٕ پانژھ پردٕ، تہٕ شیہ پردٕ پانے، تہٕ خیمہ کِس برونہمس حصس منز کرُن شیٚیِم پردٕ دۄگنہٕ۔\n10.\\tتہٕ ژے بناو أکِس پردس پیٹھ پنژاہ لوپ {یعنی} جوڑس منز، تہٕ پردٕ کِس اندس پیٹھ پنژاہ لوپ یُس دویمِس جوڑس منز جوڑان چھُ۔\n11.\\tتہٕ ژے بناو پنژاہ پیتلٕچ ٹیچ، تہٕ ٹیچس تھووُن لوپس منز، تہٕ خیمہ جوڑُن یُتھ اکھ بنہِ۔ {خیمہٕ: یا، کور کٔرِتھ}\n12. تہٕ خیمہ کِس پردٕ سٍتـ̡ باقی، یُس نصف پردہ باقی، سُہ گژھہِ خیمہ کِس پٔتمِس پٔتـ̡ لٹاونہٕ یُن۔\n13. تہٕ اَکہِ طرفہٕ اکھ کیوبِٹ تہٕ دوٚیمہِ طرفہٕ یُس خیمہ کِس پردَس مَنٛز روزان آسہِ، سُہ گژھہِ خیمہ کِس اندۍ پکھۍ تہٕ اَتھ طرفہٕ اَتھ پٲٹھۍ۔ {تتھ منز...: ہیب۔ باقی، یا، اضٲفی}\n14.\\tتہٕ ژے بناوُن خیمہٕ خٲطرٕ اکھ پردٕ یُس وۄزُل رنٛگ کٔرِتھ تہٕ بٔرِن ہٕندِس کھالس پیٹھ اکھ پردٕ تہٕ بٔرِن ہٕندِس کھالس پیٹھ۔\n15.\\tتہٕ ژے بناو خیمہ خانہٕ خٲطرٕ تختہٕ کھڑا کھڑا ۔\n16.\\tداہ کیوبِٹ آسہِ اَکہِ تختُک زیچھر تہٕ ڈۅڈ کیوبِٹ آسُن اَکہِ تختُک کھجر۔\n17.\\tأکِس تختس مَنٛز زٕ ٹینن آسن، یِم أکِس أکِس خٕلاف ترتیب دِنہٕ یِن: یِتھٕ پٲٹھۍ، یِتھٕ پٲٹھـ̡ بَناوُن خیمہ کِس سارِنٕے تختن ہٕندِس خٲطرٕ۔ {ٹینن: ہیب۔ اتھہٕ}\n18.\\tتہٕ ژے بناو خیمہ خانہٕ خٲطرٕ بورڈ، جنوبس طرفہٕ وُہ تخت۔\n19. تہٕ ژے بناو وُہن تختن تل ژتٲجی رۄپہٕ ساکٹ۔ اکس بورڈس تل زٕ ساکٹ، تہٕ بییس بورڈس تل زٕ ساکٹ۔ {ٹینن: ہیب۔ اتھہٕ}\n20. تہٕ شمالس طرفہٕ خیمہ کِس دوٚیمس طرفہٕ {اتہِ گژھن} وُہ تختہٕ:\n21. تہٕ تِہٕندِ ژتٲجی ساکٹ۔ اکس بورڈس تل زٕ ساکٹ، تہٕ بییس بورڈس تل زٕ ساکٹ۔\n22.\\tتہٕ مغرب کُن خیمہ کِس اندۍ پکھۍ بناوُن ژے شیہ تخت۔\n23.\\tتہٕ دۅشوٕے طرفن ہٕندِس خیمہ کِس کونس خٲطرٕ بناوُن زٕ تختہٕ۔\n24. تہٕ یِم گژھن بۅنہ کنہِ رٔلِتھ رٔلِتھ تہٕ یِم یِن اَمہ کِس کلس پیٹھۍ أکِس وٲج سٍتـ̡ جوڑنہٕ: یِتھے پٲٹھۍ آسہِ یِمن دۄشوٕنی ہٕندِ خٲطرٕ۔ تِم آسن دۄن کونن خٲطرٕ۔ {جوڑ: ہیب۔ جڑواں }\n25.\\tتہٕ تِم گژھن ٲٹھ تختہٕ تہٕ تِہٕندِ ساکٹ رۄپہٕ ، شُراہ ساکٹ۔ اکس بورڈس تل زٕ ساکٹ، تہٕ بییس بورڈس تل زٕ ساکٹ۔\n26.\\tتہٕ تہٕ ژے کرِ شِٹِم لٔکرِ ہٕندِس بارس سٍتـ̡ خیمہ کس اکہ طرفہٕ بورڈن خٲطرٕ پانژھ،\n27. تہٕ خیمہ کہِ دوٚیمہِ طرفہٕ بورڈن خٲطرٕ پانژھ سلاخہٕ، تہٕ خیمہ کہِ طرفہٕ پانژھ سلاخہٕ، مغرب کُن دۄن طرفن خٲطرٕ۔\n28.\\tتہٕ بورڈن منز درمیانی بار گژھہِ اندس پیٹھ اندس تام واتہِ۔\n29.\\tتہٕ تُہۍ کٔرِو سۄنہٕ سٍتـ̡\n30. تہٕ تُہۍ کٔرِو خیمہ تُلِتھ یُس تۅہہِ پہاڑس مَنٛز ہاونہٕ آمُت اوس۔\n31. تہٕ ژے بناوُن نیوٗل تہٕ واگن تہٕ سرخ تہٕ چالاکی ہٕنزِ باریک پوشہٕ تہٕ کرُن کرُن:\n32.\\tتہٕ ژے تراوُن سۅنہٕ سٍتـ̡ ژۅن ستونن پیٹھ یِمن ہٕندِس کُنہِ سٍتـ̡ سۅنہٕ سٍتـ̡ لٔگـ̡ سٍتـ̡ لٔ\n33.\\tتہٕ تہٕ تُہۍ کٔرِو پردٕ تَلہٕ اَتھ مَنٛز اَننہٕ یُتھ تہٕ وَلہٕ کٔرِو مُقدس تہٕ مُقدسَس مَنٛز تقسیم۔\n34.\\tتہٕ تہٕ ژے تھاوُن رحمتُک تخت گوٲہی ہٕندِس صندوقس پیٹھ مقدس مقامس پیٹھ۔\n35.\\tتہٕ ژے تھاوُن میزہ ورٲے، تہٕ شمعدان تھاوُن شُمالس کُن شُمالس کُن۔\n36.\\tتہٕ تہٕ ژے بناو خیمہ کِس دروازس خٲطرٕ اویز، نیوٗل تہٕ واگن تہٕ سرخ رنگ، تہٕ سٕژنہٕ سٍتۍ بٔنِتھ نٔوۍ کُن۔\n37.\\tتہٕ ژے کٔرِو پانژھ تھم لٔکرِتھ تہٕ تِمن سٍتـ̡ سۄنہٕ سٍتـ̡ تہٕ یِمن ہٕندِ ہُند ہُک آسہِ سۄنہٕ سٍتـ̡ تہٕ تِمن ہٕندِ خٲطرٕ تراوُن پانژھ پیتلٕچ ساکٹ۔","1. تہٕ ژے بناو اکھ قربان گاہ یُس پانژھ کیوٹھ زیوٹھ تہٕ پانژھ کیوٹھ کھُلہٕ آسہِ۔ قربان گاہ گژھہِ ژور مربعہ: تہٕ امیک تھزر گژھہِ تریہ کیوبٹ۔\n2.\\tتہٕ ژے بناو امکۍ سینگ ژۅشونی کونن پیٹھ، تٔمۍ سٕندِ سینگ گژھن ہِشی آسن۔\n3.\\tتہٕ تٔمۍ سٕندِس پانس سٍتـ̡ تہٕ تٔمۍ سٕندِس سوٗر سٍتـ̡ تہٕ تٔمۍ سٕندِس سٍتـ̡ تہٕ تٔمۍ سٕندِس سٍتـ̡ تہٕ تٔمۍ سٕندِس سارِنٕے بانہٕ سٍتـ̡ بَناوُن۔\n4. تہٕ تُہۍ بناو اتھ خٲطرٕ پیتلُک جال۔ تہٕ جالہِ پیٹھ بناو ژۅن کونن منز ژور بریسن حلقہٕ۔\n5. تہٕ ژے تھاوُن یہ بۅنہ کنہِ قربان گاہ کِس کمپسس تل، یُتھ جال آسہِ قربان گاہس منز تہِ۔\n6.\\tتہٕ تہٕ ژے بناو قربان گاہٕ خٲطرٕ، لٔکرِ لٔکرِ سٍتـ̡ تہٕ تمن پیٹھ پیتل سٍتـ̡ سجاونہٕ یُن۔\n7. تہٕ ڈنجہ یِن حلقن مَنٛز تراونہٕ، تہٕ ڈنجہ گژھن قربان گاہ ہٕندِس دۄن طرفن پیٹھ، یہ برداشت کرنہٕ خٲطرٕ۔\n8.\\tتختو سٍتۍ کھوکھر کرُن تہٕ یِتھٕ پٲٹھۍ یہ پہاڑس منز ہاونہٕ آمُت چھُ، تِتھے پٲٹھۍ بناوِ تِم تہِ۔ {یہ اوس...: ہیب۔ تٔمۍ ہٲو ہاو}\n9. تہٕ ژے بناو خیمہ خانہٕ کِس صحنَس منز: جنوبس طرفہٕ {اتہِ گژھہِ أکِس طرفہٕ ہتھ ہاتھ ہُند زیوٗٹھ لٔٹِتھ کُنہِ ک\n10.\\tتہٕ اَمہ کِس وُہ تھم تہٕ تِمن ہٕندِ وُہ ساکٹ گژھن پیتلُک ۔ ستونن ہٕندۍ ہُک تہٕ تِمن ہٕندۍ فِلٹ گژھن رۄپہٕ ہٕندۍ۔\n11.\\tتہٕ یتھے پاٹھۍ آسہِ شمالس منز زیچھرس منز ہتھ {کیوبٹ} زیوٹھ پھانسی تہٕ تٔمۍ سٕندِ وُہ تھم تہٕ تِمن ہٕندِ وُہ ساکٹ پیتل آسن۔ ستونن ہٕندۍ ہُک تہٕ تِمن ہٕندِ فِلیٹس رۄپہٕ۔\n12.\\tتہٕ مغرب طرفہٕ صحنُک کھجرٕ آسہِ پنژاہ کیوبٹن ہٕندِس پھانس منز: تِہندِ تھم دَہ تہٕ تِہٕندِ ساکٹ دَہ۔\n13. تہٕ مشرقس طرفہٕ صحنُک کھجر آسہِ پنژاہ کیوبٹ۔\n14.\\tاَکہِ طرفہٕ گژھن پنٛدہ کیوبِٹ: تِہٕندِ تھَم ترےٚ، تہٕ تِہٕندِس ساکٹَس ترےٚ۔\n15.\\tتہٕ دوٚیمہِ طرفہٕ آسہِ پنٛداہ {کیوبٹ}: تِہٕندِ تھَم ترےٚ، تہٕ تِہٕندِ ساکٹَس ترےٚ۔\n16.\\tتہٕ دربار کِس دروازس خٲطرٕ گژھہِ وُہن کیوبِٹَن ہُند پھانسی آسُن، {منز} نیوٗل تہٕ واگن رنگ، تہٕ سٕژنہٕ سٍتۍ بٔنِتھ نٔوۍ کُن تہٕ تِہٕندِس تھم ژور تہٕ تِہٕندِس ساکٹ ژور۔\n17.\\tدربارس اندۍ تمام ستون گژھن رۅپہٕ سٍتۍ بٔرِتھ۔ تہند ہُک آسہٕ رۄپہٕ سٕتۍ، تہٕ تِہند ساکٹ آسہٕ پیتلٕک۔\n18.\\tصحنُک زیچھر گژھہِ اکھ ہتھ کیوبِٹ، تہٕ کھجر آسہِ پنژاہ تہٕ تھزر آسہِ پانژھ کیوبِٹ باریک کُن تہٕ تِمن ہٕندِس ساکٹَس آسہِ۔ {پنژاہ...: ہیب۔ پنژاہ بائی پنژاہ}\n19.\\tخیمہ ہٕندِس سارِنٕے بانہٕ تہٕ اَمہِ ہٕندِس سارِنٕے پِنہٕ تہٕ دربارٕکۍ سارِنٕے پِنہٕ آسن۔\n20. تہٕ تُہہِ کٔرِو بنی اِسرٲیلِس حُکُم زِ تِم أنِن گاشہٕ خٲطرٕ خٲلِص تیٖل زیتون دِنہٕ، یُتھ شمع ہمیشہٕ زالُن۔ {دزنہٕ خٲطرٕ: ہیب۔ کھسنہٕ خٲطرٕ}\n21. یُس گوٲہی برونہہ کُن چُھہ، ہارون تہٕ تٔمۍ سٕندِس نیچوِس شامس پیٹھٕ صُبحہ تام خداوند سٕندِ برونہہ کُن حکم دِن: {یہِ} گژھہِ تِہنزن نسلن ہٕندِ خٲطرٕ ہمیشہٕ خٲطرٕ اکھ قانون آسُن۔","1. تہٕ نِیو پنُن بوے ہارون تہٕ تٔمۍ سٕندِس نیچوِس پانس سٍتۍ، یُتھ زن سُہ پادٕرۍ سٕندِس دفترس مَنٛز خدمت کرِ، حتیٰ کہ ہارون، نداب تہٕ ابیہو، الیعزار تہٕ اِتھمار، ہارون سٕندِس نیچوۍ۔\n2. تہٕ پَنٕنِس بٲیِس ہارون سٕندِ خٲطرٕ پَنٕنـ̡ پاکیزٕ پَلَو بناوُن، جلال تہٕ خوبصورتی خٲطرٕ۔\n3. تہٕ ژٕ کٔرِو سارِنٕے دٲنِس دِلس سٍتـ̡ کتھ کرنہٕ، یِمن میہ دانٲیی ہٕندِس روحس سٍتـ̡ بٔرِتھ چُھ، یُتھ تِم ہارون سٕندِس پوشاک سٍتـ̡ تٔمِس مقدس کرنہٕ خٲطرٕ بناوٕن، یُتھ سُہ کرِ پادٕرۍ سٕندِس دفترس مَنٛز میانہِ خدمت کرنہٕ۔\n4. تہٕ یِم چھِ تِم پلو یِم تِم بناوٕنۍ۔ اکھ سینہٕ، تہٕ اکھ ایفود، تہٕ اکھ پوشہٕ، تہٕ اکھ بٔرِتھ کوٹ، اکھ مِتر، تہٕ اکھ گرڈ: تہٕ تِم بناوِ ہارون سٕندِ خٲطرٕ تُہند بٲے تہٕ تٔمۍ سٕندِس نیچوِس خٲطرٕ، یُتھ سُہ پادٕرۍ سٕندِس دفترس مَنٛز میانہِ خدمت کرِ۔\n5.\\tتہٕ تِم نِن سۄنہٕ تہٕ نیوٗل تہٕ واگن تہٕ سرخ تہٕ عمدہ کُن۔\n6.\\tتہٕ تِم بناوَن سۄنہٕ سُن، {of} نیوٗل تہٕ {of} واگن رنٛگ، {of} سرخ تہٕ بارٕ لٲگِتھ کُنہِ کُنہِ کامہِ سٍتـ̡ ۔\n7.\\tاتھ منز گژھن دۅشوے پھیکس پیٹھ رلاونہ یُن۔ تہٕ {توتہٕ} یِہ گژھِ رلاونہٕ یِن۔\n8.\\tتہٕ ایفوڈُک عجیب بند، یُس اتھ پیٹھ {چُھ}، آسہِ اَمہ کامہِ مُطٲبق یۅہے آسہِ۔ {حتیٰ کہ} سۄنہٕ، {of} نیوٗل، تہٕ واگن تہٕ سرخ تہٕ باریک جڑوُن کُن۔ {متجسس: یا، کڑھائی}\n9.\\tتہٕ تُہۍ نِیُن زٕ کُنہِ کٔنہِ تہٕ تِمن پیٹھ کٔرِو بنی اِسرٲیلِیَن ہُند ناو قبر۔\n10.\\tاکس کنس پیٹھ چھہِ تہند شیہ ناو، تہ بییس کنس پیٹھ چھہِ باقین ہندۍ شیہ ناو۔\n11.\\tکنن پیٹھ نقش نگار سٕنزِ کامہِ سٍتـ̡ {یِتھٕ پٲٹھۍ} کُنہِ نشانہٕ سٍتـ̡ نقش و نگار سٍتـ̡ کھٔنِتھ کرُن دۅن کنن پیٹھ بنی اسرٲیلِن ہٕندِس ناوَس سٍتـ̡ کھٔنِتھ تہٕ تِم بناوُن سۄنہٕ سٕندِس سٍتـ̡ ۔\n12.\\tتہٕ تُہہِ تھاوُن زٕ کٔنہِ ایفود کِس پھیکس پیٹھ، تہٕ ہارون تھاوِ خداوند سٕندِس دۅن پھیکس پیٹھ تِہُند ناو یادگار خٲطرٕ۔\n13.\\tتہٕ ژے کٔرِو سۄنہٕ سٍتـ̡\n14. تہٕ اندس پیٹھ زٕ زنجیر خالص سۄنہٕ۔ ﴿﴾ گُلہٕ کٔرِتھ کٔرِو تِم بَناوُن، تہٕ گُلہٕ زنجیر لٲگِتھ گٔنڈِتھ۔\n15.\\tتہٕ ژے کرِ چالاکی سٍتـ̡ فٲصلہٕ کِس سینس پیٹھ دِنہٕ۔ ایفوڈٕچ کٲم کرنہٕ پتہٕ کرِ ژے یہ بناوُن۔ {of} سۄن، {of} نیوٗل، تہٕ {of} واگن رنگ، تہٕ {of} سرخ رنگ، تہٕ {of} باریک جڑوُن کُن، ژے بناو یہ۔\n16.\\tژور مربع گژھہِ {being} دوٚگنہ۔ اکھ عرصہ {گژھہِ امیک زیچھر} تہ اکھ عرصہ آسہِ امیک کھجر۔\n17.\\tتہٕ ژے کٔرِو اتھ منز کنن ہٕنز ژور لٲنہٕ: {گۅڈنِچہِ} لٲن {گژھہِ} ساردیس، اکھ ٹوپاز تہٕ اکھ کاربنکل: {یہِ آسہِ} گۄڈنِچ لٲنہٕ۔ {سیٹ...: ہیب۔ اتھ منز بٔرِو کنن ہنز بھرن} {سارڈیئس: یا، روبی}\n18.\\tتہٕ دۆیم لٲن آسہِ زمرد ، نیلم تہٕ ہیرہ۔\n19.\\tتہٕ تریمہِ لٲنہِ منز چھہ اکھ لیگر، اکھ ایگیٹ تہٕ اکھ امیتھیسٹ۔\n20.\\tتہٕ ژوٗرمہِ لٲنہِ ہٕندِس سٍتـ̡ چُھہ سٍتـ̡ {انکلوزنگ: ہیب۔ فِلنگس}\n21. تہٕ کٔنہِ گژھن بنی اسرٲیلِین ہٕندِس ناون سٍتـ̡ بارہ، یِمن ہٕندِ ناوٕ مُطٲبق، {یِتھٕ پٲٹھۍ} کُنہِ نشانہٕ سٍتـ̡ نقش و نگار آسن۔ پرٮ۪تھ أکِس سٕندِس ناوَس سٍتـ̡ آسہِ تِم بہن قبیلن مطٲبق۔\n22.\\tتہٕ ژے بناو سینہ پلیٹس پیٹھ خالص سۄنہٕ سٕنزِ کامہِ ہٕنز۔\n23.\\tتہٕ ژے بناو سینس پیٹھ سۄنہٕ سٕندِ زٕ وٲج تہٕ سینہٕ ہٕندِس دۄن اندس پیٹھ تھاوُن زٕ وٲج ۔\n24. تہٕ ژے تھاوُن دۅن حلقن منز سۄنہٕ سٕندِ زٕ گُلہٕ {یِم چھِ} سینہ ہٕندِس اندس پیٹھ۔\n25.\\tتہٕ {باقٕے} دۅن گلن ہٕندِس دۅشوٕے اندس {زنجیر} ژیہ ژیہ دۅن پھورن منز بند کرُن، تہٕ اتھ برونہہ کُن تھووُن ایفوڈ کِس پھیکس پیٹھ۔\n26.\\tتہٕ ژے بناو سۄنہٕ سٕندِ زٕ وٲج تہٕ تِم تھاوُن اَمہِ کِس اندس منز سینہ پوشہِ ہٕندِس دۄن اندس پیٹھ، یُس ایفود کِس اندس منز چُھ۔\n27.\\tتہٕ سۄنہٕ سٕندِ زٕ {باقٕے} وٲج یِم ژے بناوٕنۍ، تہٕ یِم تھووُن ایفوڈٕ کِس دۄن طرفن بۅنہٕ کُن، اَمہ کِس برٛونٛہمِس حصس کُن، اَمہ کِس {باقی} جوڑس پیٹھ، ایفوڈ کِس عجیب و غریب کمرس پیٹھ۔\n28.\\tتہٕ تِم گٔژھن سینہٕ پلیٹس سٍتـ̡ اِفود کِس حلقس سٍتـ̡ نیوٗل رنٛگہٕ سٍتـ̡ گٔنڈِتھ، یُتھ زِ یہِ گژھہِ ایفود کِس عجیب و غریب بندس پیٹھ، تہٕ یُتھ زِ سینہٕ پوشہٕ گژھہِ نہٕ ایفودٕ نشہِ یلہٕ تراونہٕ۔\n29.\\tتہٕ ہارون گژھہِ پننِس دِلس پیٹھ فیصلہٕ کِس سینس مَنٛز بنی اسرٲیلِین ہُند ناو تھاوُن، یێلہِ سُہ خداوند سٕندِ برونہہ کُن یادگار روزنہٕ خٲطرٕ گژھِ۔\n30. تہٕ ژے تھاوُن فیصلہٕ کِس سینس مَنٛز اُرِم تہٕ تھمِم۔ تہٕ یێلہِ سُہ خداوند سٕندِس برونہہ کُن گژھہِ، تہٕ ہارون روزِ خداوند سٕندِس دِلس پیٹھ۔\n31. تہٕ ژے بناو ایفوڈُک پوشاک سٲرۍسٕے نیوٗل۔\n32.\\tتہ اتھ منز گژھہِ اتھ منز اکھ سوراخ آسُن، اتھ اندۍ گژھہِ وونۍ کامہِ ہُند بند، یتھہ پاٹھۍ یہ ہیبرجینک سوراخ آسہِ، تاکہ یہ گژھہِ نہ کرایہ دِنہٕ۔\n33.\\tتہٕ {بۅنہ کنہِ} بَناوُن اَمہ کِس اندس اندۍ انار نیوٗل تہٕ {of} واگن تہٕ {of} سرخ رنگ۔ تہٕ اندۍ سنہٕ سۄنہٕ گھنٹۍ: {ہیم: یا، سکرٹ}\n34.\\tاکھ سۄنہٕ گھنٹی تہٕ اکھ دٲر، اکھ سۄنہٕ گھنٹی تہٕ اکھ دٲر، اندۍ اندۍ پکھۍ۔\n35. تہٕ ہارونس پیٹھ گژھہِ خدمت کرُن، تہٕ تٔمۍ سٕنز آواز گژھہِ بوزنہٕ یِنہٕ یێلہِ سُہ خداوند سٕندِس برونہہ کُن مقدس مقامس پیٹھ گژھہِ، تہٕ ییلہ سُہ نیرِ، سُہ گژھہِ نہٕ مَرُن۔\n36.\\tتہٕ تُہۍ بناوُن خٲلص سۄنہٕ سُند اکھ پلیٹ تہٕ اتھ پیٹھ قبر، یِتھ کٔنۍ زَن أکِس سِگنیٹٕچ نقش و نگار، خداوند سٕندِ خٲطرٕ پاکیزگی۔\n37.\\tتہٕ ژے تھاوُن یہِ نیوٗل فیتس پیٹھ، یُتھ یہ آسہِ مِٹرس پیٹھ۔ مِٹرس برونہہ کُن آسہِ۔\n38. تہٕ یہِ گژھہِ ہارون سٕندِس ڈٮ۪کہٕ پٲٹھۍ، یُس اِسرٲیلِکۍ بنی پَنٕنـ̡ پَنٕنـ̡ مقدس تحفہٕ سٍتـ̡ پاک کرٕنـ̡ ۔ تہٕ یہ گژھہِ ہمیشہ تٔمۍ سٕندِس ڈٮ۪کہٕ پیٹھ، یُتھ زن تِم خداوند سٕندِ برونہہ کُن قبول کرنہٕ یِن۔\n39.\\tتہٕ ژے بناوُن عمدہ کُنہِ کوٹ تہٕ ژے بناوُن نفیس کُن تہٕ سٕژِ ہٕندِس کُنہِ تہِ کُنہ\n40. تہٕ ہارون سٕندٮ۪ن نیچوٮ۪ن ہٕندِ خٲطرٕ بناوُن کوٹ تہٕ تِمن ہٕندِ خٲطرٕ بناوُن تہٕ تِمن ہٕندِ خٲطرٕ بناوُن تہٕ خوبصورتی خٲطرٕ۔\n41. تہٕ تِم تراوُن ہارون پُنِس بٲیِس تہٕ تٔمۍ سٕندِس نیچوِس سٍتـ̡ ۔ تہٕ یِمن مسح کرُن، تہٕ مقدس کرُن، تہٕ پاک کرُن، یُتھ تِم کٔرِن پادٕرۍ سٕندِس دفترس مَنٛز میانہِ خدمت کرنہٕ۔ {مقدس کرُن...: ہیب۔ تِہُند اَتھٕ بٔرِو}\n42.\\tتہٕ تِمن ہٕندِس ننگہٕ پوشہٕ خٲطرٕ بناوُن کُنہِ کمر پیٹھہ رانن تام وٲتِتھ چھہِ تم وٲتِتھ: {تِہُند...: ہیب۔ تِہُند ننگُک ماز} {وٲتِتھ: ہیب۔ be}\n43. تہٕ تِم گژھن ہارونس تہٕ تٔمۍ سٕندِس نیچوِس پیٹھ، یێلہِ تِم جماعت کِس خیمہ خانس مَنٛز یِن، یا یێلہِ تِم مقدس مقامس مَنٛز خدمت کرنہٕ خٲطرٕ قربان گاہس نزدیک یِن۔ زِ تِم گژھن نہٕ بدکار تہٕ مرُن: {یہِ آسہِ أمِس تہٕ تٔمِس پتہٕ تٔمۍ سٕندِس اولادس خٲطرٕ ہمیشہٕ خٲطرٕ اکھ قانون۔","1. تہٕ یہِ چُھہ سُہ کتھ یُس ژے تِمن مقدس کرنہٕ خٲطرٕ کرُن، پادٕرۍ سٕندِس دفترس مَنٛز میانہِ خدمت کرنہٕ خٲطرٕ: اَکھ جوان بیل تہٕ زٕ رٔٹِتھ رٔٹِتھ رٔٹِو،\n2.\\tتہٕ خمیر روٚس روٹی، تہٕ کیک یُس تیٖلہٕ سٍتـ̡ چُھہ خمیر روٚس تہٕ تیلُک مسح کٔرِتھ خمیر روٚس کٔرِتھ: ﴿﴾ کٕنکہٕ آٹِہ تہٕ کُنُک آٹا بناوُن۔\n3. تہٕ تِم أکِس ٹوٗکرِ مَنٛز تھٲوِو، تہٕ أنِو تِم ٹوٗکرِ منز، بیل تہٕ زٕ کٔرِتھ ۔\n4. تہٕ ہارون تہٕ تٔمۍ سٕندِس نیچوِس أنِو جماعت ہٕندِس خیمہ کِس دروازس تام تہٕ تِمن آبہٕ سٍتـ̡ چھلناوُن۔\n5. تہٕ تُہۍ لٲگِو پلو تہٕ ہارونس لٲگِتھ کوٹ، تہٕ ایفودُک پوشہٕ، تہٕ ایفودُک پوشہٕ تہٕ سینہ لٲگِتھ تہٕ تٔمِس لٲگِتھ ایفوڈُک عجیب بند۔\n6.\\tتہٕ تہٕ تٔمۍ سٕندِس کلَس پیٹھ لٲگِتھ تہٕ مُقدس تاج لاگُن۔\n7. تیلہٕ رٔٹِتھ تہٕ تٔمِس کلَس پیٹھ تراوُن تہٕ مسح کٔرِو۔\n8.\\tتہٕ تٔمۍ سٕندِس نیچوِس أنِتھ تہٕ تِمن لٲگِتھ کوٹ۔\n9.\\tتہٕ ہارون تہٕ تٔمۍ سٕندِس نیچوِس لٲگِتھ تہٕ تِمن پیٹھ لٲگِتھ تہٕ پادٕرۍ سُند عہدٕ گژھِ تِمن ہٕندِس دٲیمی حکمس خٲطرٕ، تہٕ ہارون تہٕ تٔمۍ سٕندِس نیچوِس کٔرِو پاکیز۔ {پُٹ: ہیب۔ bind} {consecrate: Heb. اتھہ بٔرِتھ کٔرِو\n10.\\tتہٕ ژے کٔرِو اجتماعہٕ کِس خیمہ خانس برونہہ کُن اکھ دانٛد اننہٕ، تہٕ ہارون تہٕ تٔمۍ سٕندِس نیچوۍ تھاون بیلس کِس کلس پیٹھ اتھہٕ۔\n11.\\tتہٕ ژے کٔرِو خداوند سٕندِ برونہہ کُن بیل مارُن، جماعت ہٕندِس خیمہ کِس دروازس پیٹھ۔\n12.\\tتہٕ ژے نِیُن دانٛد سُند خوُن، تہٕ تھووُن پننہِ اونگجہِ سٍتـ̡ قربان گاہٕکِس سینگس پیٹھ، تہٕ سورُے خوُن تراوُن قربان گاہ ہٕندِس دامنس سٍتـ̡ ۔\n13.\\tتہٕ ژے نِیُن سورے چربی یُس اندرمس کُن ؤلِتھ چُھہ، تہٕ کُل یُس کُنہِ {The Caul: یہ چُھ اناٹومی تہٕ عبرانی ڈاکٹرن ہٕندِ ذریعہٕ درمیانی باسان}\n14.\\tمگر بیلُک ماز تہٕ تٔمۍ سُند مَلہٕ تہٕ تٔمۍ سُند گُرُہ، یُس گۅنہٕ سٍتـ̡ دزنہٕ یُن، یہِ چُھہ گۅناہ ہُند نذرانہ ۔\n15.\\tژیہ تہِ رٔٹِتھ اکھ رٔنگۍ تہِ۔ تہٕ ہارون تہٕ تٔمۍ سٕندِس نیچوِس تھٲوِن مینڈٕ سٕندِس کلس پیٹھ اتھہٕ۔\n16.\\tتہٕ ژے کٔرِو مینڈُک مٲرِتھ، تہٕ تٔمۍ سُند خوُن نِیُن تہٕ قربان گاہس پیٹھ پھیُرُن۔\n17.\\tتہٕ ژے ژٔٹِتھ ژٔٹِتھ تہٕ أمِس أندرِم تہٕ زنگہٕ چھلناوُن تہٕ تٔمۍ سٕندِس کلس پیٹھ۔ {unto: or, upon}\n18.\\tتہٕ تہٕ ژے زٲلِو سورُے رژھ قربان گاہَس پیٹھ: یہِ چُھہ خداوند سٕندِ خٲطرٕ دزنہٕ آمُت نذرانہٕ: یہِ چُھہ مٔٹھُر مَزٕ، یُس نارٕ سٍتـ̡ خداوند سٕندِ خٲطرٕ دِنہٕ آمُت چُھ۔\n19.\\tتہٕ تُہۍ نِیُن بییِس کُنہِ کُ تہٕ ہارون تہٕ تٔمۍ سٕندِس نیچوِس تھٲوِن مینڈٕ سٕندِس کلس پیٹھ اتھہٕ۔\n20. تیلہٕ ژے مارُن تہٕ تٔمۍ سُند خوُن نِش تہٕ ہارون سٕندِس دٔچھنِس کنس پیٹھ، تہٕ تٔمۍ سٕندِس دٔچھنِس کنس پیٹھ، تہٕ تٔمۍ سٕندِس دٔچھنِس کھورِ ہٕندِس کھورِ پیٹھ، تہٕ دٔچھنِس کھورِ ہٕندِس بٔڈِس کھورِ پیٹھ، تہٕ دٔچھنِس کھورِ ہٕندِس کھورِ پیٹھ، تہٕ دٔچھنِس کھورِ ہٕندِس کھورِ ہٕندِس کھورِ پیٹھ۔\n21. تہٕ یُس خون قربان گاہس پیٹھ چُھ، تہٕ مسح کِس تیٖلس پیٹھ، تہٕ ہارونس پیٹھ، تہٕ تٔمۍ سٕندِس نیچوِس پیٹھ، تہٕ پننین نیچوین ہٕندِس پلوس پیٹھ تہٕ تس سٍتـ̡ پننین نیچوین ہٕندِس پلوس پیٹھ، تہٕ تٔمۍ سٕندِس نیچوین ہٕندِس پلوس تہٕ تٔمۍ سٕندِس نیچوین ہٕندِس پلوس سٍتـ̡ مقدس کرنہٕ یُن۔\n22.\\tتہِ ژیہ رٔٹِتھ رٔٹِتھ چربی تہٕ چربی یُس اندرمس کُن دِوان چُھ، تہٕ کۅکرِ تہٕ دٔچھنِس پھیکس پیٹھ چربی تہٕ دٔچھنِس پھیکس پیٹھ۔ تکیازِ یہ {چُھ} تقدیسُک اکھ روٚم:\n23.\\tتہٕ اکھ روٹی تہٕ اکھ تیلہٕ دار روٹی تہٕ اکھ ویفر یُس خداوند سٕندِ برونہہ کُن چُھہ:\n24. تہٕ ژے تھاوُن سارِوٕے ہارون سٕندِس اتھس منز، تہٕ تٔمۍ سٕندِس نیچوین ہٕندِس اتھس منز۔ تہٕ یِمن ہٕندِس خداہس برونہہ کُن لہراونہٕ یِنہٕ خٲطرٕ۔ {شالٹ لہر: یا، ہلٲوِتھ تہٕ یور کٔرِتھ}\n25.\\tتہٕ تُہۍ یِمن ہٕندِس اَتھٕ سٍتـ̡ رٔٹِتھ تہٕ زٲلِتھ قربان گاہس پیٹھ زالنہٕ خٲطرٕ، خداوند سٕندِ برونہہ کُن مٔٹھـ̡ مٔٹھـ̡ مَزٕ خٲطرٕ: یہِ چُھہ خداوند سٕندِ خٲطرٕ نارٕ سٍتـ̡ دِنہٕ آمُت نذرانہٕ۔\n26.\\tتہٕ تُہۍ رٔٹِو ہارون سٕندِس تقدس ہٕندِس سینس سٍتـ̡ تہٕ لہراوُن خداوند سٕندِس برونہہ کُن لہراونہٕ خٲطرٕ، تہٕ یہِ آسہِ تُہند حصہٕ۔\n27.\\tتہٕ تہٕ ژے کٔرِو لہر ہٕندِس سٍتـ̡ یُس ہارون سٕندِ خٲطرٕ {چُھ} تہٕ {یہ} یُس تٔمۍ سٕندِس نیچوین ہٕندِ خٲطرٕ چُھ، تہٕ یُس تٔمۍ سٕندِس نیچوِس خٲطرٕ چُھ:\n28.\\tتہٕ یہِ گژھہِ ہارون تہٕ تٔمۍ سٕندِس نیچوِس سٍتـ̡ بنی اسرٲیلـ̡ سٍتـ̡ ہمیشہٕ خٲطرٕ ہمیشہٕ خٲطرٕ ہُند قربانی دِنہٕ۔\n29.\\tتہٕ ہارون سٕندِ مقدس پوشاک گژھن تٔمۍ سٕندِس نیچوین ہٕندِس پَتہٕ یِن، یِمن مَنٛز مسح کرنہٕ یِن، تہٕ یِمن مَنٛز یِن مقدس کرنہٕ۔\n30.\\t{تہٕ} سُہ نیچو یُس پننہِ جایہِ پادٕرۍ آسہِ، سُہ کرِ سَتن دۅہن یێلہِ سُہ جماعت کِس خیمہ خانس مَنٛز یِیہِ مُقدس {جایہ} مَنٛز خدمت کرنہٕ خٲطرٕ۔ {سُہ نیچو: ہیب۔ سُہ چُھ پننین نیچوین منٛز}\n31.\\tتہٕ تُہۍ رٔٹِو تٔمۍ سُند ماز مقدس مقامس مَنٛز۔\n32. تہٕ ہارون تہٕ تٔمۍ سٕندِس نیچوۍ کھیوٚن رۅنگہِ ہُند ماز تہٕ ٹوٗکرِ مَنٛز روٹی یُس جمٲژ ہٕندِس خیمہ کِس دروازس سٍتـ̡ چُھ۔\n33.\\tتہٕ تِم گژھن تِم چیز کھٮ۪وان یِمن سٍتـ̡ کفارہٕ دِنہٕ آمُت چُھ، تِمن پاک کرنہٕ خٲطرٕ، مگر اجنبی گژھِ نہٕ کھٮ۪ن، تِکیازِ تِم چِھہ پاکیز۔\n34.\\tتہٕ یێلہِ تقدس ہُند ماز یا روٹی ہُند ماز صبحس تام روزُن، تیلہِ گژھہِ باقی حصہ نارٕ سٍتـ̡ زالُن: سُہ گژھہِ نہٕ کھٮ۪نہٕ یُن، تکیازِ یہِ چُھ مُقدس۔\n35. تہٕ یِتھٕ پٲٹھۍ کٔرِو ژے ہارونس تہٕ تٔمۍ سٕندِس نیچوِس سٍتۍ، یِمن سارِنٕے چیزن مُطٲبِق یِمن ہُند حُکُم مُطٲبِق کٔرِو سَتھ دۅہہٕ۔\n36.\\tتہٕ ژے کفارہٕ خٲطرٕ گۅنہٕ ہٕندِ قربانی خٲطرٕ پرٮ۪تھ دۅہٕ اکھ بیل پیش کرُن، تہٕ توے کرِو قربان گاہ پاک کرنہٕ، یێلہِ تہٕ ژے کرِو اتھ پاکیزگی مۅکھہٕ مسح کرنہٕ۔\n37.\\tسَتھ دۅہہٕ کٔرِو قربان گاہُک کفارہٕ تہٕ تقدس کٔرِو۔ تہٕ یِہ آسہِ سارِوٕے کھۄتہٕ مُقدس قربان گاہ: یُس تہِ قربان گاہَس اَتھٕ لاگہِ سُہ آسہِ مُقدس۔\n38.\\tوۅنۍ چھہ یہ {سُہ} یُس ژے قربان گاہس پیٹھ پیش کرُن۔ گۅڈنچہ ؤری کین زٕ کٹہٕ بچہٕ دۅہہ دۅہہ لگاتار ۔\n39.\\tیُس کُنہِ کۅکرِ سٍتـ̡ ژے صبحٲے پیش کرُن۔ تہٕ بیٛاکھ کۅکرٕ یُس ژے تہِ دِیُن:\n40.\\tتہٕ أکِس کۅکرِ سٍتـ̡ دٔہِم آٹُک دٔہِم سودا یُس ژوٗرِمِس تیٖلس سٍتـ̡ رلاونہٕ آمُت چُھ۔ تہٕ شرابُک ژوٗرِم حصہٕ چُھ شرابٕچ پیشکش۔\n41. تہٕ بیٛاکھ کۅٹہٕ کۅکرِ یُس تہٕ صبحُک ماز تہٕ شرابٕ مطٲبق کرُن، یُس مٔٹھہِ مٔٹھہِ مَزٕ خٲطرٕ دِنہٕ یُن، یُس خداوند سٕندِ خٲطرٕ نارٕ سٍتـ̡ دِنہٕ آمُت چھُ۔\n42. {یہِ} آسہِ تُہنزِ نسلہٕ سٍتـ̡ لگاتار زٲلِتھ نذرانہ {یێلہِ} خداوند سٕندِ برونہہ کُن جماعت کِس خیمہ کِس دروازس پیٹھ: یێتہِ بہٕ ژے سمکھہٕ تہٕ تتہِ کتھ کرنہٕ مۅکھہٕ۔\n43. تہٕ اَتہِ میلہٕ بہٕ بنی اسرٲیلِس سٍتـ̡ تہٕ {خیمہ خانہٕ} گژھہِ میانہِ جلال سٍتـ̡ پاک کرنہٕ۔ {خیمہ خیم: یا، اسرائیل}\n44. تہٕ بہٕ کَرٕ جمٲژ ہٕندِس خیمہ تہٕ قربان گاہُک پاکس، بہٕ کَرٕ ہارون تہٕ تٔمۍ سٕندِس نیچوِس تہِ پاکس، یُس پادٕرۍ سٕندِس دفترس مَنٛز میانہِ خدمت کرنہٕ خٲطرٕ۔\n45. تہٕ بہٕ روزٕ بنی اسرٲیلِس مَنٛز روزُن، تہٕ بنہٕ تِہُند خدا۔\n46. تہٕ تِمن گژھہِ پتاہ زِ بہٕ چُھس خداوند تِہُند خدا، یُس تِمن مِصر کِس سرزمینہٕ منزٕ نیبر کٔرِتھ، یُس بہٕ تِمن مَنٛز روزُن، بہٕ چُھس خداوند تِہُند خدا۔","1. تہٕ ژے بناو اکھ قربان گاہ یتھ پیٹھ بخور زالنہٕ خٲطرٕ: {of} شیٹِم لٔکرِ تہٕ ژے بناو یہٕ۔\n2. اکھ کیوبِٹ آسہِ امیک زیچھر تہٕ اکھ کیوبِٹ آسُن۔ ژور مربع آسہِ: تہٕ زٕ کیوبٹ {گژھہِ} امیک تھزر: امکۍ سینگ {گژھہِ} آسن۔\n3.\\tتہٕ تُہۍ کرِو اتھ خالص سۄنہٕ سٍتۍ، اَمہ کِس پیٹھمس حصس تہٕ اَمہ کِس اندۍ تہٕ اَمہ کِس سینگ سٍتۍ۔ تہٕ تُہۍ بناو اتھ اندۍ سنہٕ سُند تاج۔ {ٹاپ: ہیب۔ چھت} {طرف: ہیب۔ دیوار}\n4.\\tتہٕ زٕ سۄنہٕ وٲج بنٲوِو اَتھ کِس تاجس تلہ کنہِ، اَمہ کِس دۄن کونَن سٍتۍ، اَمہ کِس دۅشوٕے اندۍ پکھۍ۔ تہٕ تِم آسن لاٹھن ہٕندِ خٲطرٕ یہ برداشت کرنہٕ خٲطرٕ۔ {کون: ہیب۔ رِب}\n5.\\tتہٕ ژے کٔرِو لٔکرِ لٔکرِ سٍتـ̡\n6.\\tتہٕ ژے تھاوُن یہ گوٲہی ہٕندِس صندوقس برونہہ کُن، رحمتٕچ نشست برونہہ کُن، یُس گوٲہی ہٕندِس صندوقس پیٹھ {چُھ}، یێتہِ بہٕ ژے سٍتـ̡ مِلنہٕ ییہِ۔\n7. تہٕ ہارون دِیہِ پرٮ۪تھ صُبحَس اَتھ پیٹھ مٔدٕر اگربُب زالُن، یێلہِ سُہ چَراغ لاگہِ، سُہ دِیہِ اَتھ پیٹھ بخور زالُن۔ {میٹھی اگرب: ہیب۔ مسالہٕ ہُند اگربُب}\n8. تہٕ یێلہِ ہارون چَراغ دِیہِ، سُہ دِیہِ اَتھ پیٹھ بخور زالُن، یُس تُہٕندِس سارِنٕے نسلن ہٕندِس پٲٹھـ̡ خداوند سٕندِس برونہہ کُن دٲیرٕ بخور دِیہِ۔ {گاش: یا سیٹتھ اپ: ہیب۔ وجہٕ چُھ کھسنہٕ خٲطرٕ} {even: Heb. دۄن شامن درمیان}\n9. اَتھ پیٹھ گژھِ نہٕ عجیب اگرب، نہ زٲلِتھ قربانی، تہٕ مازٕچ نذرانہ پیش کٔرٕنۍ۔ تہٕ نہ چُھکھ اتھ پیٹھ شرابُک نذرانہ تراوُن۔\n10. تہٕ ہارون کرِ ؤریس منز اکہِ لٹہِ امہِ کِس سینگس پیٹھ کفارہٕ دِنہٕ، ؤریس مَنٛز اکہِ لٹہِ کرِ سُہ تُہنزن نسلن سٍتـ̡ اتھ پیٹھ کفارہٕ: یہِ چُھ خداوند سٕندِ خٲطرٕ سارِوٕے کھۄتہٕ مقدس آسان۔\n11. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن،\n12. یێلہِ تُہۍ بنی اِسرٲیلِس ہٕندِس تعدادس سٍتـ̡ رٔٹِو، تێلہِ دِیُن تِم پرٮ۪تھ أکِس انسانس پننہِ روحہٕ خٲطرٕ خداوند سٕندِ خٲطرٕ تاوان دِن، یێلہِ تہٕ تُہۍ تِمن ہُند شمار کرِ۔ زِ تمن منز گژھہِ نہ کانہہ وبا، ییلہ تۅہہ تمن گنزراونہ آسہِ۔ {تہند نمبر: ہیب۔ تم یم نمبر گژھن چِھ}\n13.\\tیُس پریتھ کانہہ یُس گنزراونہٕ آمُت چُھ، یُس پریتھ کانہہ یُس گنزراونہٕ آمُت چُھ، یُس مقدس مقامہٕ کِس شیکل پتہٕ نصف شیکل دِن: (اکھ شیکل {چُھ} وُہ گیرہ:) نصف شیکل {گژھہِ} خداوند سٕندِ نذرانہ سٍتـ̡ دِنہٕ۔\n14.\\tیُس پریتھ کانہہ یُس وُہُن وُہُر تہٕ اَمہِ کھۄتہٕ زیادٕ وٲنسہِ ہُند شمار آسہِ، سُہ گژھِ خداوند سٕندِ خٲطرٕ نذرانہ دِنہٕ۔\n15. امیر گژھن نہٕ زیادٕ دِنہٕ، تہٕ غریبٕ گژھن نہٕ نصف شیکل کھوتہٕ کم دِنہٕ، یێلہِ {تِم} تُہٕندِس روحس خٲطرٕ کفارہ دِنہٕ خٲطرٕ نذرانہ دِن۔ {مزید دِیو: ہیب۔ ضرب کٔرِو} {کم دِیُن: ہیب۔ کم کرُن}\n16. تہٕ تُہۍ کرو بنی اسرٲیلِن ہُند کفارہٕ ہُند پونٛسہٕ نِن، تہٕ کرُن یہِ جماعت ہٕندِس خیمہ خانہٕ سٕنزِ خدمتہٕ خٲطرٕ مقرر۔ یُتھ زِ یہِ گژھہِ خدایہِ سٕندِ برونہہ کُن بنی اسرٲیِلـ̡ خٲطرٕ یادگار بٔنِتھ، یُس تُہٕندِس روحَن ہُند کفارہ دِنہٕ ییہِ۔\n17.\\tتہٕ خداوند ووٚن موسیٰ سٍتـ̡ وۆن،\n18.\\tژے بناوُن پیتلُک تہٕ تٔمۍ سٕندِس کھورِ سٍتـ̡ تہٕ تٔمۍ سٕندِس کھورِ سٍتـ̡ چھلنہٕ خٲطرٕ، تہٕ ژے تراوُن اجتماعہٕ کِس خیمہ تہٕ قربان گاہس درمِیان تہٕ تێلہِ تراوُن آب ۔\n19.\\tہارون تہٕ تٔمۍ سٕندِس نیچوِس پَنٕنـ̡ اَتھٕ تہٕ کھۅر چھلناوٕن:\n20. یێلہِ تِم جماعت کِس خیمہ خانس مَنٛز گژان چھِ، تِم گژھن آبہٕ سٍتـ̡ چھلنہٕ، یُتھ نہٕ تِم مَرٕنـ̡ ۔ یا ییلہِ تِم قربان گاہس نزدیک یِن، خدایہِ سٕندِ خٲطرٕ نارٕ سٍتـ̡ دِنہٕ آمٕژ نذرانہ زالنہٕ خٲطرٕ:\n21. یێلہِ گژھن تِم پَنٕنـ̡ اَتھٕ تہٕ کھۅر چھلناوٕن، یێلہِ نہٕ تِم مَرٕنـ̡ تہٕ یہِ روزِ تِمن ہٕندِ خٲطرٕ ہمیشہٕ خٲطرٕ، تہٕ تٔمۍ سٕندِس نسلس سٍتـ̡ تہٕ تٔمۍ سٕندِس نسلس سٍتـ̡ ہمیشہٕ خٲطرٕ اکھ قانون۔\n22. امہِ علاوٕ چُھ خداوند موسىٰ سٕندِس سٍتـ̡ وَنُن زِ\n23.\\tپانس نِش نِیُن خالص مرہ پانژھ ہتھ تہٕ مٔدٕرِ دالچنیُک نصف تہٕ مٔدٕر دالچنیُک نصف تہِ، تہٕ مٔدٕر کالمس ہُند زٕ ہتھ پنژاہ شیکلس،\n24. تہٕ کیسیا پانژھ ہتھ {شیکل}، مقدس مقامک شیکل پتہٕ، تہٕ تیٖل زیتون آن ہن:\n25.\\tتہٕ تہٕ بَناوُن یہِ مُقدس مرہم ہُند تیٖل، یُس مرہم ہُند مرکب آسہِ، یہِ گژھہِ اکھ مقدس مسح کرنُک تیٖل۔ {apothecary: or, perfumer}\n26. تہٕ تہٕ ژے کرٕ اتھ سٍتـ̡ جماعتُک خیمہ تہٕ گوٲہی ہٕندِس صندوقس مسح کرنہٕ،\n27. تہٕ میز تہٕ تٔمۍ سٕندِ سارِنٕے بانہٕ، تہٕ شمعدان تہٕ تٔمۍ سٕندِس بانہٕ تہٕ اگربُک قربان گاہ،\n28.\\tتہٕ دزنہٕ نذرانہ ہُند قربان گاہ تہٕ تٔمۍ سٕندِس سارِنٕے بانہٕ سٍتـ̡ تہٕ تٔمۍ سٕندِس کھورِ سٍتـ̡ ۔\n29.\\tتہٕ تُہۍ کرِو تِمن پاکیز، یُس تہِ یِمن اتھہٕ لاگہِ سُہ گژھہِ پاک۔\n30.\\tتہٕ ژے کرٕ ہارون تہٕ تٔمۍ سٕندِس نیچوِس مسح کٔرِتھ، تہٕ تِم کرٕن پادٕرۍ سٕندِس دفترس مَنٛز میانہِ خدمت کرنہٕ۔\n31. تہٕ ژٕ کٔرِو بنی اِسرٲیلِس سٍتـ̡ کتھ کٔرِتھ زِ یہِ آسہِ چانہِ نسلن ہٕندِ خٲطرٕ مُقدس مسح کرنُک تیٖل۔\n32.\\tانسان سٕندِس مازس پیٹھ گژھِ نہٕ یہ تراونہٕ یُن، تہٕ نہ گژھِو تۅہہ یِتھُے یِتھُے بناوُن، یہِ {چُھ} مُقدس، {تہٕ} تہٕ یہِ آسہِ تۅہہِ خٲطرٕ پاک۔\n33.\\tیُس تہِ یِتھُے کانہہ تہِ مرکب کرِ، یا یُس تہِ اَمہ منزٕ کانہہ تہِ چیز کُنہِ اجنبی شخصس پیٹھ تراوِ، سُہ گژھِ پننین لوکن نِش تہِ ژٹنہٕ یُن۔\n34.\\tتہٕ خداوند ووٚن موسیٰ سٕندِس نِش مٔدٕرِ مسالہٕ، مٔٹھۍ مسالہٕ، تہٕ اونیچا تہٕ گلبانم۔ {یِم} خالص لوبان سٍتۍ مٔدٕر مسالہٕ: پرٮ۪تھ أکِس ہِش آسہِ {وزن}:\n35. تہٕ ژے بناو اتھ اکھ عطر، اکھ مٹھائی، یکوٹہ مزاج، خالص {تہٕ} مقدس: {tempered...: Heb. نمکین}\n36.\\tتہٕ ژے کرِ اتھ منز واریاہ لۄکٕٹ، تہٕ اتھ منز تھاوُن جماعت کِس خیمہ خانس مَنٛز گوٲہی برونہہ کُن، یتہِ بہٕ ژے سٍتـ̡ مِلُن: یہِ آسہِ تۅہہِ خٲطرٕ مقدس ۔\n37. تہٕ یُس عطر تہِ ژیہ بناوُن، سُہ گژھہِ نہٕ پانس خٲطرٕ امہِ چہ ساختہ مطٲبق بناوُن، سُہ گژھہِ تۅہہِ خٲطرٕ خداوند سٕندِ خٲطرٕ مقدس۔\n38.\\tیُس تہِ یُس تہِ یژھہِ تہِ سونگھ کرِ، سُہ گژھہِ پننین لوکن نِش تہِ ژٹنہٕ یُن۔","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2.\\tوُچھو، مے چُھہ یہوداہ قبیلہٕ کِس حُور سُند نیچو بیزلیل ناوٕ سٍتـ̡ وُننہٕ آمُت:\n3. تہٕ مے چُھ تس خدایہ سٕندِ روحہٕ سٍتـ̡ بٔرِتھ ، دانٲیی سٍتـ̡ ، تہٕ فہم سٍتـ̡ ، علمس مَنٛز تہٕ پرٮ۪تھ قٕسمٕچ کاریگری سٍتـ̡ بٔرِتھ ،\n4. چالاکی کٲم کرٕنۍ، سۄنہٕ سٍتـ̡ تہٕ رۄپہٕ سٍتـ̡ کٲم کرٕنـ̡\n5. تہٕ کَنہٕ ژٹنہٕ خٲطرٕ، تہٕ لٔکر نقش و نگارس منٛز، پرتھ قسمٕچ کاریگری منٛز کٲم کرنہٕ۔\n6.\\tتہٕ وُچھمُت میہ دِژ أمِس سٍتـ̡ دانس قبیلہٕ سُند نیچو اہولیاب، تہٕ سارِنٕے دانا دلن ہٕندِس دلس مَنٛز چُھس مے دانٲیی دِژمٕژ، یُس تِم سُہ سُہ کٔرِتھ یُس میہ تُہند حُکُم دِژمُت چھُ۔\n7. جمٲژ ہُند خیمہ تہٕ گوٲہی ہُند صندوق، تہٕ رحمتٕچ نشست یُس {چُھ} تہٕ خیمہ خانہٕ ہُند تمام فرنیچر، {فرنیچر: ہیب۔ جہاز}\n8.\\tتہٕ میز تہٕ تٔمۍ سُند فرنیچر، تہٕ خٲلص شمعدان یتھ سٍتـ̡ تٔمۍ سٕندِس سارِنٕے فرنیچرس سٍتـ̡ تہٕ بخور ہُند قربان گاہ، {فرنیچر: Heb. جہاز}\n9.\\tتہٕ دزنہٕ آمٕژ قربان گاہ سٍتـ̡ تٔمۍ سٕندِس سارِنٕے فرنیچرس سٍتـ̡ تہٕ لَور تہٕ تٔمۍ سٕندِس کھورِ سٍتـ̡ {فرنیچر: Heb. جہاز}\n10. تہٕ خدمتٕکۍ پلو، تہٕ پادٕرۍ ہارون سٕندِ خٲطرٕ مقدس لباس، تہٕ تٔمۍ سٕندٮ۪ن نیٚچوٮ۪ن ہٕندِ پَلو، پادٕرۍ سٕندِس دفترس مَنٛز خدمت کرنہٕ خٲطرٕ،\n11.\\tتہٕ مسح کرنُک تیٖل تہٕ مٔدٕر اگربتی: یُس میہ ژے حکم دِتمُت چُھ، تِم کرُن۔\n12. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن،\n13.\\tتہِ کٔرِو بنی اسرٲیلِس سٍتـ̡ کتھ تہٕ ونُن، یێلہِ پٲٹھـ̡ میٲنۍ سبت تہٕ تُہٕندِس سبت رٔٹِتھ تھاوٕنـ̡ یێلہِ چُھہ میانہِ تہٕ تُہٕندِس درمِیان چُھہ تُہٕندِس سٍتـ̡ سٍتـ̡ نِشانہٕ۔ یُتھ {تۅہہ} گژھہِ پتاہ زِ بہٕ چُھس سُہ خداوند یُس تۅہہِ پاک کران چُھ۔\n14. تَمہِ مۄکھٕ پَزِ سبت روزُن؛ تکیازِ یہِ چُھ تۅہہِ خٲطرٕ مُقدس: یُس تہٕ یہِ ناپاک کرِ، یُس تہٕ یُس اتھ منز کانہہ کٲم کرِ، سُہ گژھہِ پنہٕ نِس لوکَس مَنٛز ژٹنہٕ یِنہٕ۔\n15.\\tشیہ دۅہن گژھہِ کٲم کرنہ۔ مگر سٔتِمِس مَنٛز چُھہ آرامُک سبت یُس خداوند سٕندِ خٲطرٕ مقدس چُھ: یُس سبت دۅہہٕ کُنہِ تہِ کٲم کرِ، سُہ گژھہِ یقینا مارنہٕ یُن۔ {مقدس: ہیب۔ پاکیزگی}\n16. اَمہِ مۄکھہٕ پۯاوٕنـ̡ بنی اسرٲیلـ̡ سبت دۅہہٕ تھاوُن، یێلہِ پى۪ٹھـ̡ پى۪ٹھـ̡ سبت دِنہٕ خٲطرٕ، یێلہِ پى۪ٹھـ̡\n17. یہِ چُھ میانہِ تہٕ بنی اسرٲیلِس درمِیان ہمیشہٕ خٲطرٕ اَکھ نشانہٕ: شیٚن دۅہن بَنوو خداوند اسمانس تہٕ زمینہٕ تہٕ سٔتِمہِ دۅہہٕ آرام تہٕ تازٕ۔\n18.\\tتہٕ تٔمۍ دِژ موسیٰ ہس ییلہ تٔمِس سینا کِس پہاڑس پیٹھ أمِس سٍتـ̡ کتھ باتھ کرٕنـ̡ ختم کٔر، گواہی ہٕندِ زٕ میز، کٔنـ̡ ، یُس خدایہ سٕنزِ اونگجہِ سٍتـ̡ لیکھنہٕ آمُت اوس۔","1. تہٕ ییلہ لوکو وُچھ زِ موسیٰ چُھ پہاڑ پیٹھٕ نیرنس ژیر گومُت، لوکھ جمع ہارونس نِش تہٕ وونُن زِ اسہِ بَنوو دیوتا، یُس اسہِ برونہہ کُن گژھن۔ یێلہِ زِ یہِ موسیٰ، یُس شخٕص یُس اسہِ مصر کہِ سرزمینہٕ منزٕ نیبر کڈُن، اسہِ ٲس نہٕ زانان زِ أمِس کیا بنیوو۔\n2.\\tتہٕ ہارونن ووٚن تِمن سٍتـ̡ سۅنہٕ بالہٕ ژٔٹِتھ یُس تہنزِ زنانہِ ہٕندِس کنن منز، تہٕ چُھنہٕ کورِ ہٕندِس کنن مَنٛز موجود چھِ، تہٕ أنِو میہ نِش۔\n3.\\tتہٕ سارِوٕے لُکھ کٔرِکھ سۅنہٕ بالہٕ یِم پننین کنن منز ٲس، تہٕ أنِکھ ہارونس نِش۔\n4.\\tتہٕ تٔمۍ رٔٹِتھ تہٕ بنووُن تِمن ہٕندِس اتھہٕ سٍتـ̡ تہٕ بنووُن کھورِ ہٕندِس آلہٕ سٍتـ̡ تہٕ تِمو ووٚن، اے اسرائیل، یِمو ژے مصر کہِ سرزمینہٕ منزٕ نیبر کٔرۍ۔\n5. تہٕ ییلہ ہارونن وُچھ، تٔمۍ بنوو اتھ برونہہ کُن اکھ قربان گاہ۔ تہٕ ہارونن کٔر اعلان تہٕ وونُن، پگہہ چُھ خداوند سٕندِ خٲطرٕ دعوت۔\n6. تہٕ تِم ووٚتھ سُلہٕ سُلہٕ، تہٕ دِژٕکھ نذرانہٕ تہٕ امنٕچ نذرانہ پیش کٔرِتھ۔ تہٕ لوٗکھ بِہتھ کھٮ۪نہٕ تہٕ چیٚنہٕ خٲطرٕ، تہٕ گِنٛدنہٕ خٲطرٕ ووٚتھٕ۔\n7. تہٕ خداوند ووٚن موسیٰ سٕندِس سٍتـ̡ گژھ بۄن پٲٹھۍ۔ تِکیازِ تُہٕندِس لُکہٕ سٍتـ̡ یُس ژے مصر کہِ سرزمینہٕ منزٕ اننہٕ آمُت چُھ، تِمو چُھہ پان بد کار کٔرِمُت:\n8.\\tتِمو چُھہ تِمن پۯاوُن بَچھرٕ بَنٲومُت، تہٕ یِمو چُھکھ تِمن ہُند پوٚگُر بَنٲومُت، تہٕ کورُکھ تِمن ہٕندِ خٲطرٕ قربان تہٕ وونُن، اے اسرٲیل، یِمو چُھہ تُہٕندِس خداہس سٍتـ̡ یِمو تُہٕندِس سرزمینہٕ سٍتـ̡ نیبر کٔرِمٕتۍ۔\n9. تہٕ خداوند ووٚن موسیٰ سٕندِس سٍتـ̡ مے وُچھمُت یہِ لُکھ تہٕ وُچھِو یہِ {چُھ} اَکھ ضدی لُکہٕ:\n10. تێمہِ کِنۍ تراوُن مے کُنی، یُتھ میون غصہٕ تِمن خلاف گرم گژھہِ، تہٕ بہٕ کرٕ تِمن کھٮ۪وان، تہٕ بہٕ بناوٕ ژے اکھ بٔڈ قوم۔\n11. تہٕ موسىٰ کٔر خداوند پنہٕ نِس خداہس سٍتـ̡ التجا تہٕ وونُن، خداوند، تێہُند غضب کیازِ چُھہ پننِس لوکَس سٍتـ̡ تُہُند غضب یُس ژے سٮ۪ٹھاہ طاقتہٕ سٍتـ̡ مصر کِس سرزمینہٕ سٍتـ̡ نیبر کڈنہٕ آمُت چُھ؟ {خداوند: ہیب۔ خداوند سُند بُتھ}\n12.\\tمصری کیازِ کٔرِن کتھ تہٕ ونُن، یِم کٔرِن شرارت کٔرِتھ، پہاڑن مَنٛز مارنہٕ مۅکھہٕ تہٕ زمینہٕ پیٹھٕ کھٮ۪نہٕ خٲطرٕ۔ پنہٕ نِس شدید غصہٕ نِش پھیر تہٕ پننین لوکن خلاف گژھ اتھ بدی نِش توبہٕ۔\n13. ابراہیم، اسحاق تہٕ اسرٲیلِس یاد تھاوُن، پنٕنـ̡ خادم، یِمن سٍتـ̡ ژے پانس سٍتـ̡ دِژمُت، تہٕ تِمن وونُن زِ بہٕ کرٕ تُہند نسل آسمانٕکۍ ستارن ہٕندِس پٲٹھۍ، تہٕ یێمہِ سٍتـ̡ یێمہِ سٍتـ̡ بہٕ چُھس تُہٕندِس نسلس دِنہٕ آمُت، تہٕ تِم روزن ہمیشہٕ خٲطرٕ وارث۔\n14.\\tتہٕ خداوند کٔر تتھ بدی سٍتـ̡ توبہ یُس تٔمۍ پننین لوکن سٍتـ̡ کرُن سونچـ̡ ۔\n15.\\tتہٕ موسیٰ ووت پٔرِتھ پہاڑ پیٹھٕ بۄن، تہٕ گوٲہی ہٕندِ زٕ میز ٲسۍ أمۍ سٕندِس اتھس منز: دۅشوٕے اندۍ پکھۍ ٲسۍ لیکھِتھ دِنہٕ آمٕتۍ۔ اَکہِ طرفہٕ تہٕ دوٚیمہِ طرفہٕ ٲسۍ تِمو لیکھان۔\n16. تہٕ ٹیبل ٲس خدایہ سٕنز کٲم، تہٕ تحریر ٲس خدایہ سٕنز تحریر، یُس میزن پیٹھ کھٔنِتھ اوس۔\n17. تہٕ یشوع یَن بوز لُکن ہُند شور یُس تِم کرٛٮ۪کھ دِوان چھِ، تٔمۍ ووٚن موسیٰ سٕندِس خٲمس مَنٛز جنگُک شور۔\n18.\\tتہٕ ووٚن {یہ} چُھنہٕ تِمن ہٕنز آواز یِم غلبہٕ خٲطرٕ کرٛٮ۪کھ دِوان چھِ، تہٕ نہ چُھہ {تِمن ہٕنز آواز} یِم مغلوب گژھنہٕ خٲطرٕ فریاد کران چھِ: {مگر} چُھس {تِم} ہُند شور یُس بہٕ بوزان چُھس۔ {being...: Heb. کمزوری}\n19. تہٕ یێلہِ سُہ خٲمس نزدیک ووت، تٔمِس وُچھ بَچھرٕ تہٕ نژان تہٕ موسیٰ سُند شَرارتہٕ ہیوٚتُن تٔمۍ سٕندِ اَتھٕ نِش میزہٕ تہٕ لٔگِن پہاڑس تَل کٔرِتھ۔\n20.\\tتہٕ تٔمۍ رٔٹِتھ سُہ بَچھرٕ یُس تِمو بنوومُت اوس، تہٕ دِژُن نارس مَنٛز زٲلِتھ تہٕ دِژُن آبہٕ سٍتـ̡ تہٕ دِژُن اِسرٲیلِس سٍتـ̡ چُھنہٕ۔\n21. تہٕ موسىٰ ووٚن ہارونس زِ یِمو لُکھ کیا کوٚر تۅہہِ سٍتـ̡ یُس تِمن سٍتـ̡ یوتاہ بوٚڈ گۅناہ کورمُت؟\n22.\\tتہٕ ہارون ووٚن زِ میانہِ آقا سُند غصہٕ گژھہِ نہٕ تُلُن، تہٕ تُہۍ چھِو لوٗکن زانان زِ تِم چھِ شرارت کٔرِتھ۔\n23.\\tتِمو ووٚن میہ زِ اسہِ بنوو خدا، یُس اسہِ برونہہ کُن گژھِ، یُس اسہِ برونہہ کُن گژھِ، کیازِ یُس موسیٰ سُند یُس اسہِ مصرٕچ سرزمینہٕ منزٕ نیبر کٔر، اسہِ اوس نہٕ زانان زِ تس کیا بنیوو۔\n24.\\tتہٕ مے ووٚن تِمَن زِ یٔمِس سٍتـ̡ سۄنہٕ آسہِ، سُہ پھُٹراوُن سُہ پھُٹراوُن۔ تہٕ تِمو دِژ میہ نارس منز، تہٕ تتہِ دراو یہِ بَچھرٕ نیبر۔\n25.\\tتہٕ ییلہ موسیٰ وُچھ زِ لُکھ ٲسۍ ننگہٕ۔ (تکیازِ ہارون اوس تِمن دُشمنن منز شرمندہ کرنہٕ مۅکھہ ننگہٕ بنٲومُت:) {تہند دشمن: ہیب۔ تِم یِم تِمن خٕلاف کھڑا گٔیہِ}\n26.\\tاَمہِ پَتہٕ ووت موسیٰ کیمپ کِس دروازس مَنٛز کھڑا تہٕ وونُن، خداوند سٕندِ طرفہٕ کُس چُھ؟ {سُہ یِن} میانہِ نِش۔ تہٕ لیوی سٕندِ سٲری نیچوۍ گٔیہِ أمِس سٍتـ̡ جمع ۔\n27. تہٕ تٔمۍ ووٚن تِمن یِتھٕ پٲٹھۍ، یِتھٕ پٲٹھۍ چُھ اسرٲیلُک خدا، پرٮ۪تھ أکِس انسانس پَنٕنۍ تلوار پانس نِش تھووُن، تہٕ سٲرِسٕے خٲمس منٛز گٔژِھکھ دروازٕ پتہٕ دروازٕ پتہٕ اژُن، تہٕ پرٮ۪تھ أکِس شخٕص سُند بٲے تہٕ پرٮ۪تھ أکِس نفر سُند سٲتھی تہٕ پرٮ۪تھ أکِس ہمسایہ سُند مٲرِتھ۔\n28.\\tتہٕ لاوی سٕندیو اولادو کٔر موسیٰ سٕندِ کلامَس مطٲبق، تہٕ تمہِ دۅہہ گٔیہِ لُکھ تقریباً ترے ساس نفر۔\n29.\\tکیازِ موسیٰ اوس ووٚنمُت، از تام کرو پان خداوند سٕندِ خٲطرٕ، حتیٰ کہ پرٮ۪تھ کانہہ انسان تہٕ پننِس بٲیِس خٲطرٕ تہِ۔ تاکہ سُہ کرِ از دۅہہ دُعا دِنہٕ۔ {موسیٰ سٕندِ خٲطرٕ...: یا، تہٕ موسیٰ ہن ووٚن، از کل کرو پان خداوند سٕندِ خٲطرٕ مقدس، کیازِ پرتھ کانہہ انسان چُھ پننِس بٲیس خلاف رودمُت، وغیرہ} {مقدس کرُن...: ہیب۔ پَنٕنۍ اَتھٕ بٔرِو}\n30. تہٕ پَگہہ سپدُن زِ موسىٰ ووٚن لُکن زِ تہٕ چُھہ بٔڈ گۅناہ کورمُت، تہٕ وۅنۍ گژھہٕ بہٕ خداوند سٕندِس نِش۔ شاید بہٕ کٔرٕ چانہِ گۅناہ ہُند کفارہ۔\n31.\\tتہٕ موسیٰ آو خداہس نِش واپس، تہٕ وونُن، اے یِمو لوکو چُھ اکھ بوٚڈ گۅناہ کورمُت، تہٕ بنووُکھ تِم سۄنہٕ سُند دیوتا۔\n32.\\tتوتہِ اگر تہِ تِہُند گۅناہ معافی دِیہِ۔ تہٕ اگر نہٕ تیلہِ کٔرِو مے مُختلِف، بہٕ چھُس ژے پننہِ کتابہِ منزٕ دُعا کران یُس ژے لیوکھمُت چھُ۔\n33. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ یێمہِ سٍتـ̡ گۅناہ آسہِ، سُہ کرٕ بہٕ پننہِ کتابہِ منزٕ مِٹاونہٕ۔\n34. تێمہِ کِنۍ گژھ وُن، لُکن نِش یێمہِ جایہ یێمہِ مُتلق میہ ژے سٍتـ̡ کتھ کٔرمٕژ چُھ، وُچھِو، میٲنۍ فرشتہ گژھہِ ژے برونہہ کُن، توتہِ ییلہ بہٕ یِمن ہٕندِس گۅناہ سٍتـ̡ یێلہِ بہٕ یێلہِ تہِ یێلہِ بہٕ یِمن ہُند گۅناہ سپدِ۔\n35.\\tتہٕ خداوند کٔر لُکن مُتٲثِر، تِکیازِ تِمو بَنوو بَچھرٕ یُس ہارون بنوومُت۔","1. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ نیرُن، تہٕ یێمہِ لُکھ یُس ژے مصر کہِ سرزمینہٕ منزٕ نِش نِش نیرِمُت چُھ، تتھ زمینس کُن یُس بہٕ ابراہیم، اسحاق تہٕ یعقوبس سٍتـ̡ حلف دِوان چُھس، تہٕ وونُن زِ بہٕ دِیہٕ تہندِس نولس سٍتـ̡ ۔\n2. تہٕ بہٕ سوزٕ ژےٚ برونہہ کُن اکھ فرشتہٕ۔ تہٕ بہٕ کٔرٕ کنعانی، اموری تہٕ حتی، تہٕ پیرزی، حِویت تہٕ یبوسی کٔڑِتھ:\n3. دۄدٕ تہٕ ماچھ سٍتـ̡ وسان وٲلِس زمینس تام: کیازِ بہٕ ہلہٕ نہٕ ژے منزٕ ہیوٚر کھسُن۔ تکیازِ ژے چُھکھ اکھ ضدی لوک: میہ گژھہِ ژیہ وتہِ منز کھیوان۔\n4. تہٕ ییلہ لوکو یِم بد بشارت بوٗز، تِمو کٔر ماتم تہٕ کٲنسہ تہِ لوگُن أمِس پَنٕنہِ زیور۔\n5.\\tکیازِ خداوند اوس موسیٰ ہس ووٚنمُت، بنی اسرٲیلِس وَنُن زِ تُہۍ چھِو اکھ ضدی لُکھ تہٕ بہٕ یِم ژے ژٔٹِتھ ژٔٹِتھ تہٕ ژے کھٮ۪وان تہٕ تێلہِ کٔرِو ژے نِش پَنٕنہِ زیور تہٕ یُتھ بہٕ زانہٕ زِ ژے کیا کرُن۔\n6.\\tتہٕ بنی اسرٲیلِیو کٔر کوہ حوربس نِش پنٕنۍ زیور نِش نِنہٕ۔\n7. تہٕ موسیٰ ین رٔٹ خیمہ تہٕ کورُن خیمہٕ نِش دوٗر تہٕ وونُن اتھ جمٲژ ہُند خیمہ ۔ تہٕ سپُد یہِ سپُد، {یہ} یُس پرٮ۪تھ کانہہ یُس خداوند سٕندِس خیمہ خانس کُن نیران اوس، یُس خٲمہٕ ورٲے اوس۔\n8.\\tتہٕ سپُد ییلہ موسیٰ خیمہ خانس کُن نیرِ، سارِوٕے لُکھ ووٚتھ، تہٕ پرٮ۪تھ أکِس شخصس کھڑا گٔیہِ خیمہ کِس دروازس پیٹھ، تہٕ موسىٰ سٕنز رٲچھ کٔرِتھ یوتام سُہ خیمہ خانس مَنٛز گٔیہِ۔\n9.\\tتہٕ سپُد یێلہِ موسیٰ خیمہ خانس مَنٛز دٲخل سپُد، اوٚبرُن تھَم ووٚتھ تہٕ کھڑا خیمہٕ کِس دروازس پیٹھ، تہٕ {خدا} کٔر موسیٰ سٍتـ̡ کتھ باتھ۔\n10.\\tتہٕ سارِوٕے لُکھ وُچھ اوٚبرُن تھَم خیمہ کِس دروازس پیٹھ کھڑا تہٕ سارِوٕے لُکھ ووٚتھ تہٕ کٔرٕکھ پرٮ۪تھ أکِس خیمہٕ کِس دروازس پیٹھ۔\n11. تہٕ خداوند کٔر موسیٰ سٕندِس بُتھِس سٍتـ̡ کتھ یِتھٕ پٲٹھۍ انسان پننِس یارس سٍتـ̡ کتھ کران چُھ۔ تہٕ سُہ گوٚو دُبارٕ خٲمس منز، مگر تٔمۍ سُند نوکر یشوع، یُس نون سُند نیچو، اکھ نوجوان اوس، دراو نہٕ خیمہ منزہ نیبر۔\n12. تہٕ موسىٰ ووٚن خداوند سٍتـ̡ وُچھمُت، تہٕ ژے چُھکھ نہٕ مے زانان زِ ژٕ کُس کُس سوزُن میانہِ سٍتـ̡ سوزُن۔ توتہِ چُھہ ژے ووٚنمُت، بہٕ چُھس ژے ناو زانان، تہٕ ژے تہِ چھُکھ میانہِ نظرِ منز فضل میلان۔\n13. تێلہِ چُھس بہٕ ژے دُعا کران، یێلہِ بہٕ تێہٕنزِ نظرِ مَنٛز فضل میلہِ، تێلہِ ہٲوِو میہ پنٕنۍ وَتھ، یُتھ بہٕ ژے زانہٕ تہٕ تێہٕنزِ نظرِ مَنٛز فضل میلہٕ، تہٕ سمجھ زِ یہِ قوم چُھہ تُہند لوک۔\n14. تہٕ تٔمۍ ووٚن، میٲنۍ حٲضِری گژھہِ ژےٚ سٍتۍ، تہٕ بہٕ دِیہٕ ژےٚ آرام دِنہٕ۔\n15.\\tتہٕ تٔمۍ ووٚن أمِس زِ اگر نہٕ تُہٕنز موجودگی میہ سٍتـ̡ نیرِ، اسہِ نِش ہیوٚر نہٕ۔\n16. یێتہِ کَمہِ سٍتـ̡ گژھہِ یہِ زاننہٕ زِ میہ تہٕ تُہٕندِس لُکہٕ سٍتـ̡ چُھہ تُہٕندِس نظرس مَنٛز فضل میلمُت؟ {کیا یہ} چھُنہٕ تَتھ مَنٛز زِ تُہۍ چھِو اَسہ سٍتـ̡ گَژھان۔ یِتھے پٲٹھۍ گژھو أسۍ تہٕ تُہند لوک، تِمن سارِنٕے لُکن نِش الگ یِم زمینہِ پیٹھ چھِ۔\n17.\\tتہٕ خداوند ووٚن موسیٰ سٍتـ̡ بہٕ کٔرٕ سُہ تہِ یُس ژے کتھ کٔرمٕژ چُھ، تہٕ بہٕ چُھس ژے ناوٕ سٍتـ̡ زانان۔\n18.\\tتہٕ تٔمۍ ووٚن، بہٕ چُھس ژےٚ التجا کٔرِتھ، مے ہٲو پنُن جلال ۔\n19. تہٕ تٔمۍ ووٚن، بہٕ کَرٕ پنٕنۍ سٲرٕے نیکی ژےٚ برونہہ کُن، تہٕ بہٕ کرٕ ژے برونہہ کُن خداوند سُند ناو اعلان کرنہٕ۔ تہٕ بہٕ کرٕ مہربان یٔمِس سٍتـ̡ بہٕ رحم کٔرِتھ، تہٕ یٔمِس سٍتـ̡ بہٕ رحم کٔرِ۔\n20.\\tتہٕ ووٚن ژے ہیوٚک نہٕ میون بُتھ وُچھِتھ، تکیازِ کانہہ تہِ انسان گژھِ نہ میہ وُچھِتھ تہٕ زندٕ۔\n21. تہٕ خداوند ووٚن، وُچھ، {اَکہِ} چھُ میانہِ طرفہٕ اکھ جاے، تہٕ تُہۍ گژھِو أکِس پتھرس پیٹھ کھڑا روزُن:\n22. تہٕ یێلہِ یێلہِ میون جلال نیرِ، بہٕ ژے کٔنہِ کُنہِ سٍتـ̡ تھپھ کٔرِتھ، تہٕ یێلہِ بہٕ تێلہِ نیرِتھ تہٕ تێلہِ کٔرٕ ژے پنُن اتھہ\n23. تہٕ بہٕ نِش پنُن اَتھٕ نِش تہٕ ژے وُچھکھ میٲنۍ پٔتِم حصہٕ، مگر میون بُتھ گژھہِ نہٕ نظر۔","1.\\tتہٕ خداوند ووٚن موسیٰ سٕندِس پٲٹھۍ، ژے کٔرِو گۅڈنِکِس پٲٹھـ̡ کنن ہٕندِس زٕ تختہٕ تہٕ بہٕ لیکھہٕ تِم لفظ یِم گۄڈنِکِس میزس مَنٛز ٲسۍ، یِم ژے پھُٹرٲوِتھ چھِ۔\n2. تہٕ صبحٲے تیار روزُن، تہٕ صبحٲے گژھ سینا کِس پہاڑس پیٹھ کھسنہٕ خٲطرٕ، تہٕ کُنہِ پہاڑ کِس تھزرس پیٹھ گژھ میہ برونہہ کُن پیش۔\n3. تہٕ کانہہ تہِ انسان گژھہِ نہٕ توے سٍتـ̡ وُچھنہٕ یُن۔ نہ دِیُن ریوڑ تہٕ نہ کھیٚلہٕ تَمہِ بالہٕ برونہہ کُن۔\n4.\\tتہٕ تٔمۍ کٔر گۅڈنِکِس پٲٹھـ̡ زٕ کٔنـ̡ کٔنـ̡ ۔ تہٕ موسیٰ ووت صبحٲے ووٚتھ، تہٕ ووت سینا کِس پہاڑس کُن، یُتھ زن رب سُند حُکُم اوس کوٚرمُت، تہٕ رٔٹِن پننِس اتھس منز کنن ہٕنزِ زٕ میز۔\n5. تہٕ خداوند ووت اوٚبرس مَنٛز، تہٕ تٔمِس سٍتـ̡ کھڑا تہٕ کورُن خداوند سُند ناو۔\n6. تہٕ خداوند آو أمِس برونہہ کُن تہٕ اعلان کٔرِن، خدا، خداوند خدا، رحم دل تہٕ مہربان تہٕ سُہ چھُ نیکی تہٕ سچٲئی سٍتـ̡ بٔرِتھ،\n7. ساسہٕ بٔدین ہٕندِ خٲطرٕ رحم کرُن، گناہ تہٕ گناہ تہٕ گناہ معاف کرُن، تہٕ یُس نہٕ کُنہِ تہِ قصور سٍتـ̡ صاف سپدِ۔ شُرین تہٕ بچن ہٕندِس شُرین سٍتـ̡ تہٕ شُرین ہٕندِس شُرین سٍتـ̡ تریمہِ تہٕ ژوٗرمہِ نسلہٕ سٍتـ̡ باپَن ہٕنزِ بدکاری ہُند دورٕ کرُن۔\n8. تہٕ موسیٰ کٔر جلدی تہٕ کلہٕ کٔرِن زمینس کُن تہٕ کٔرٕن عبادت کرنہٕ۔\n9.\\tتہٕ وۆنُن، اگر وُنہِ تہِ چُھہ میہ چانہِ نظرِ منز فضل میلہِ، اے خداوند، بہٕ چُھس ژے دُعا کٔرِتھ اسہِ سٍتـ̡ گٔژھِتھ ۔ تکیازِ یہ چھہ اکھ سخت لوکھ ۔ تہٕ سانہِ گناہ تہٕ سٲنـ̡ گۅناہ معاف، تہٕ نِو اسہِ پنُن وراثت۔\n10. تہٕ تٔمۍ ووٚن، وُچھ، بہٕ چُھس اکھ عہد کٔرِتھ، یُس نہٕ سارِنٕے زمینس مَنٛز، تہٕ کُنہِ تہِ قومس مَنٛز کرنہٕ آمُت چُھ، تہٕ یِمن سارِنٕے لُکن مَنٛز تہٕ یِمن مَنٛز تہٕ یِمن مَنٛز تُہۍ خداوند سٕنز کٲم وُچھِو، تِکیازِ یہِ چُھہ اکھ خوفناک کٲم یُس بہٕ ژے سٍتـ̡ کرِ۔\n11.\\tیُس بہٕ از ژے حکم دِوان چُھس تہٕ وچھ بہٕ ژے برونہہ کُن اموری تہٕ کنعانی، تہٕ حتی، تہٕ پیرزی، تہٕ حوی تہٕ یبوسی ژٔلِتھ ژٔلِتھ۔\n12.\\tپانس سٍتـ̡ ہوشیار روزُن، یێلہِ تہِ تہِ گژھِو تۅہہِ سٍتـ̡ زمینہٕ کین بسکینن سٍتـ̡ کانہہ عہد کرُن، نتہٕ گژھہِ ژے منزٕ پھنس۔\n13.\\tمگر تِہٕندِ قربان گاہ تباہ کٔرِو، تِہٕنزِ شکلہٕ پھُٹرٲوِو، تہٕ تِہٕندِس باغس ژٹِوُن: {image: Heb. مجسمہٕ}\n14. تِکیازِ تُہۍ کٔرِو نہٕ کُنہِ بییِس خداہٕچ پوٗزا کٔرِتھ، یُس ناو {چُھ} حسد کَرُن، {چُھ} حسد کرن وول خدا:\n15. یێلہِ کٔرِو تۅہہ زمینہٕ کین بسکینن سٍتـ̡ عہد کرُن، تہٕ تِم گژھن پننین دیوتاہن ہٕندِ خٲطرٕ قربانی دِن، تہٕ تُہۍ کرِ تٔمۍ سٕنزِ قربانی ہُند کھٮ۪ن۔\n16.\\tتہٕ تہٕ تِہٕنزِ کورِ نِش نِوان تہٕ تِہٕنزِ کورِ چھِ پننین دیوتاہن پتہٕ بدکاری کٔرِتھ تہٕ پنٕنۍ نیچو بناوُن تہندٮ۪ن دیوتاہن پتہٕ بدکاری کران۔\n17. ژٕ بناو نہٕ پانس پگلہٕ دیوتا۔\n18.\\tخمیر روٚس روٹی ہُند دعوت۔ سَتھ دۅہہٕ کھیوٚو خمیر روٚس روٹی، یِتھہٕ کٔنۍ مے ژے حُکُم دِژمُت، اَبِب کِس رٮ۪تس مَنٛز، تِکیازِ اَبِس رٮ۪تس مَنٛز آو تُہۍ مصرہٕ پیٹھٕ نیران۔\n19. سُہ سورُے یُس میٹرکس کھولان چُھ {چُھ} میون ؛ تہٕ تُہٕندِس چارواین مَنٛز چھُ پرٮ۪تھ کُنہِ گۅڈنچہ کُنہِ {شیپ: یا، بچہ}\n20.\\tمگر گَرٕ سُند گۅڈنیُک بچہ کٔرِو کۅکرِ سٍتـ̡ تہٕ یێلہِ نہٕ تٔمِس کٔرِو تٔمِس گردن پھُٹراوُن۔ تُہۍ کٔرِو پنٕنٮ۪ن نیٚچوٮ۪ن ہٕنٛدِ سارِنٕے نیٚچوِس چھُکھ نجات دِنہٕ۔ تہٕ کانٛہہ تہِ گژھِ نہٕ میہ برونہہ کُن خٲلی ظٲہر۔ {لیمب: یا، بچہ}\n21. شیہ دۅہ کرو کٲم مگر سٔتِم دۅہہ روزِ آرام تہ ژیہ آرام کرُن۔\n22.\\tتہٕ ژے کٔرِو ہفتن ہُند دعوت، کٕنکہٕ فصلٕچ گۄڈنِکہِ پھلٕچ تہٕ ؤری کِس ٲخرس پیٹھ جمع کرنُک عید مناونہٕ۔ {ؤری کس اختتام: ہیب۔ اَمہِ ؤرِیُک انقلاب}\n23. ؤریس مَنٛز تریہ لٹہِ گژھن تُہند سارِنٕے مرد بچہٕ خداوند خدایہ، یُس اسرٲیلُک خدایہ سٕندِس برونہہ کُن ظٲہر سپدُن۔\n24. تِکیازِ بہٕ کٔرٕ تۅہہِ برونہہ کُن قومن کڈِتھ تہٕ تُہٕندِس سرحدس بٔڑاوٕ تہٕ کُنہِ تہِ کرِ تُہٕنزِ زمینہِ ہُند خواہش، یێلہِ تہٕ ژٕ ؤریس مَنٛز تریہِ لٹہِ خداوند پنُن خدایہ سٕندِ برونہہ کُن ظٲہر گژھِ۔\n25. ژے کٔرِو نہٕ میانہِ قربانی ہُند خوُن خمیرٕ سٍتـ̡ پیش کرنہٕ۔ نَہ گژھِ فسح کِس عیدٕچ قربانی صبحس تام تراونہٕ۔\n26. پننہِ زمینہِ ہٕندِس گۄڈنِکِس پھلَس مَنٛز گۅڈنیُک پھلہٕ یُس تُہۍ خداوند سٕندِس گَرَس مَنٛز انُن۔ ژے گژھ نہ ماجہ ہٕندِس دۄدس منز شُر وُچھُن۔\n27.\\tتہٕ خداوند ووٚن موسیٰ سٍتـ̡ یِم لفظ لیکھِو، یێلہِ یێمہِ کَتھِ ہٕندِس مُتعلِق چُھہ مے ژے تہٕ اسرٲیلِس سٍتـ̡ عہد کورمُت۔\n28.\\tتہٕ سُہ اوس خداوند سٕندِس سٍتـ̡ ژتٲجی دۅہن تہٕ ژتٲجی رٲژ سٍتـ̡ تتہِ موجود۔ سُہ اوس نہٕ روٹی کھٮ۪وان تہٕ نہ آب چیٚوان۔ تہٕ تٔمۍ لیکھۍ میزن پیٹھ معاہدٕکۍ الفاظ، داہ حکم۔ {حکم: حب۔ لفظ}\n29.\\tتہ سپد ییلہ موسیٰ پہاڑ سینا پیٹھہ حضرت موسیٰ سندِ اتھس منز گواہی ہندۍ زہ میز ہیتھ ووٚتھ، ییلہ سہ پہاڑ پیٹھہ ووٚتھ تہ موسیٰ اوس نہ تس سیتۍ کتھ کرنہ وزِ تسند بُتھ چمک۔\n30.\\tییلہ ہارون تہٕ سارِوٕے بنی اسرٲیلیو موسیٰ وُچھ، وُچھ تٔمۍ سٕندِس بُتھِس ہُند چمک۔ تہٕ تِم ٲسۍ أمِس نزدیک یِنہٕ نِش کھوژان۔\n31.\\tتہٕ موسىٰ کٔر تِمن بُلاونہٕ۔ تہٕ ہارون تہٕ جماعتٕکۍ سٲری حکمران گٔیہِ أمِس نِش واپس، تہٕ موسىٰ کٔر تمن سٍتـ̡ کتھ باتھ۔\n32.\\tتہٕ امہ پتہ وٲتۍ سارِنٕے بنی اسرائیل نزدیک، تہٕ تٔمۍ دِژ تِمن سُہ سورُے حُکُم یُس خداوند سٍتـ̡ کُنہِ سینا پہاڑس مَنٛز أمِس سٍتـ̡ کتھ کٔرمٕژ ٲس۔\n33.\\tتہٕ یوتام موسیٰ علیہ السلامن تمن سٍتۍ کتھ کٔر، تٔمۍ تھوو پننِس بُتھِس پیٹھ پردٕ۔\n34. مگر ییلہ موسیٰ خدایہ سٕندِ برونہہ کنہِ أمِس سٍتـ̡ کتھ کرنہٕ خٲطرٕ اژِو، تٔمۍ کٔر پردٕ تُلِتھ یوٚت تام سُہ نیبر نیرِ۔ تہٕ سُہ آو نیٚبر، تہٕ کٔرٕن بنی اِسرٲیلِس سٍتـ̡ کتھ یُس أمِس حُکُم اوس دِنہٕ آمُت۔\n35.\\tتہٕ بنی اسرٲیلِیو وُچھ موسیٰ سُند بُتھ تہ موسیٰ سٕندِس بُتھِس سٍتـ̡ چمکان۔","1. تہٕ موسىٰ کٔر بنی اسرائیلٕچ سارِنٕے جماعت جمع تہٕ تِمن وونُن، یِم چھِ تِم لفظ یِم خداوند دِیُت حُکُم دِژمُت، یُس تِم کرُن یِم کرنہٕ یِن۔\n2. شیہ دۅہ گژھہِ کٲم کرنہٕ، مگر سٔتِمہِ دۅہہ گژھہِ تۅہہِ خٲطرٕ اکھ مقدس دۅہہ، یُس تہِ اتھ منز کٲم کرِ، سہ گژھہِ مارنہٕ۔ {an...: Heb. پاکیزگی}\n3. سبت دۅہہٕ پَنٕنـ̡ سٍتـ̡ نار دِنہٕ یِنہٕ۔\n4. تہٕ موسىٰ کٔر بنی اسرائیل کین سارنٕے جماعتن سٍتـ̡ وونُن، یہِ چُھ سُہ چیز یُس خداوند حُکُم دِیُتمُت چُھ،\n5. یُس تہٕ یُس تہِ رضامند آسہِ، سُہ گژھہِ خداوند سٕندِ خٲطرٕ نذرانہ دِنہٕ۔ سۄن، رۄپھ تہٕ پیتل،\n6. تہٕ نیوٗل تہٕ واگن تہٕ سرخ تہٕ باریک کُن تہٕ ژھاوٕل ہُند {مست}،\n7.\\tتہٕ کۅکرِ ہٕنزِ کھال رنٛگ کٔرِتھ رنٛگ کٔرِتھ، تہٕ کٔرِتھ لٔکرِ رنٛگ کٔرِتھ،\n8. تہٕ گاشہٕ خٲطرٕ تیٖل تہٕ تیٖل مسح کرنہٕ خٲطرٕ تہٕ مٔدٕر بخور خٲطرٕ مَسالہٕ،\n9. تہٕ اونکس کٔنہِ، تہٕ کٔنہِ یِن ایفوڈ تہٕ سینہ خٲطرٕ تھاونہٕ۔\n10. تہٕ تێلہِ گژھہِ پرتھ کانہہ عقلمند دِل یُس خداوند سُند حکم دِیُتمُت چھُ، تہٕ کرِ سُہ سُہ سُہ یُس خداوند سُند حکم دِیُتمُت چھُ۔\n11. خیمہ ، تٔمۍ سُند خیمہ تہٕ تٔمۍ سُند پردٕ ، تٔمۍ سٕندِ ٹیچ، تہٕ تٔمۍ سٕندِس تختہٕ، تٔمۍ سٕندِس ڈنڈٕ، تہٕ تٔمۍ سٕندِ ساکٹ،\n12.\\tصندوق تہٕ اَمہ سٍتـ̡ رحمتٕچ کرسی تہٕ پردٕ سٍتـ̡\n13.\\tمیز، تہٕ تٔمۍ سٕندِ سارِنٕے بانہٕ، تہٕ شیوبرڈ،\n14.\\tگاشہٕ خٲطرٕ تہٕ تٔمۍ سٕندِ فرنیچر تہٕ تٔمۍ سٕندِس لیمپ سٍتـ̡ گاشہٕ خٲطرٕ تیٖل تہِ،\n15. تہٕ اگربُک قربان گاہ، تہٕ تٔمۍ سٕنزِ لٔرۍ، تہٕ مسح کرنُک تیٖل تہٕ مٔدٕر بُور، تہٕ خیمہ کِس اژنہٕ وِزِ دروازٕ خٲطرٕ پھانسی دِنہٕ،\n16.\\tدزنہٕ نذرانہ ہُند قربان گاہ، تٔمۍ سٕندِس بٔرِس سٍتـ̡ تہٕ تٔمۍ سٕندِس سارِنٕے بانہٕ سٍتـ̡ تہٕ تٔمۍ سٕندِس کھورِ سٍتـ̡\n17.\\tدربارُک پھانسی ، تٔمۍ سٕندِ تھم تہٕ تِہٕندِ ساکٹ، تہٕ دربارٕ کِس دروازس پیٹھ پھانسی دِنہٕ،\n18.\\tخیمہ ہٕندِ پِنہٕ تہٕ دربارٕچ پِنہٕ تہٕ تِہٕنزِ ڈورِ\n19.\\tخدمت ہٕندِ پلو، مقدس مقامس مَنٛز خدمت کرنہٕ خٲطرٕ، ہارون پادٕرۍ سٕندِ خٲطرٕ مقدس پوشاک، تہٕ تٔمۍ سٕندِس نیچوین ہٕندِ پَلَو، پادٕرۍ سٕندِس دفترس مَنٛز خدمت کرنہٕ خٲطرٕ۔\n20. تہٕ بنی اسرٲیلٕچ سارِنٕے جماعت گٔیہِ موسىٰ سٕندِ حٲضِری نِش روانہٕ۔\n21.\\tتہٕ تِم آیہ، پرٮ۪تھ کانہہ یٔمۍ سُند دِل دِل دِیُت، تہٕ پرٮ۪تھ کانہہ یُس تٔمۍ سٕندِس روحس خۅش کٔرِتھ، تہٕ تِمو اَن خداوند سٕنز قربانی جماعت ہٕندِس خیمہ کِس کامہِ خٲطرٕ، تہٕ تٔمۍ سٕنزِ سارِنٕے خدمتہٕ خٲطرٕ، تہٕ مقدس لباسن خٲطرٕ۔\n22.\\tتہٕ تِم آیہِ، مرد تہٕ زنانہٕ، یِمو دِل دِل ٲسۍ، {تہٕ} أنِکھ کٔرٕن، بالہٕ، وٲج تہٕ گولہٕ، سٲری سۄنہٕ سٕندِ جوٲہر: تہٕ پرٮ۪تھ کانہہ نفر یُس خداوند سٍتـ̡ سۄنہٕ سُند نذرانہ پیش کٔرِ۔\n23.\\tتہٕ پرٮ۪تھ کانہہ شخٕص یٔمِس سٍتۍ نیوٗل تہٕ واگن رنٛگ تہٕ سرخ تہٕ بارٕ کُن تہٕ ژھاوٕل کھال تہٕ کۅکرِ ہٕندِ کھال تہٕ کۅکرِ ہٕندِس کھالس تہٕ بٔرِن ہٕندِس کھالس سٍتـ̡ لبنہٕ آو۔\n24.\\tپریتھ کانہہ یُس رۅپہٕ تہٕ پیتلُک نذرانہ پیش کران اوس، سُہ آو رب سُند نذرانہ تہٕ پرٮ۪تھ کانہہ شخص، یٔمِس سٍتـ̡ کُنہِ تہِ کامہِ خٲطرٕ لٔکرِ لٔبنہٕ آمُت اوس، سُہ اوٚن یہِ۔\n25.\\tتہٕ سارِنٕے دِل زنانہٕ یِمو دِل دِل آسہٕ تِمو اَتھٕ سٍتۍ نژان تہٕ یُس تِمو کُن کٔرِمُت اوس، یُس تِمو نیوٗل تہٕ واگن رنگُک تہٕ سرخ رنگُک تہٕ عمدہ کُنہِ سٍتـ̡ کٔرِتھ۔\n26.\\tتہٕ سارِنٕے زنانہٕ یِمن ہُند دِل دِوان چھُ، تِمو کٔرِکھ ژھاوٕلؠن ہٕندِس مَس۔\n27.\\tتہٕ حکمرانو أنۍ اونکس کٔنہِ تہٕ کٔنہِ یِنہٕ خٲطرٕ، ایفود تہٕ سینہٕ خٲطرٕ۔\n28. تہٕ گاشہٕ خٲطرٕ تہٕ تیٖل تہٕ مسح کرنہٕ خٲطرٕ تہٕ مٔدٕر بخور خٲطرٕ۔\n29.\\tبنی بنی اَن خداوند سٕندِ خٲطرٕ اکھ رضامندی سان قربانی، پرٮ۪تھ مرد تہٕ زنانہٕ، یٔمۍ سُند دِل تِم پرٮ۪تھ قٕسمٕچ کامہِ خٲطرٕ تیار بنیوو، یُس خداوند موسىٰ سٕندِ اتھہٕ سٍتـ̡ دِیُتمُت اوس ۔\n30. تہٕ موسىٰ ہن ووٚن بنی اسرٲیلِس وُچھِو، خداوند چُھ یہوداہ قبیلہٕ سُند نیچو حُور سُند نیچو بیزلیل ناوٕ سٍتـ̡ بُنٲومُت۔\n31. تہٕ تٔمۍ چُھ أمِس خدایہِ سٕندِ روحہٕ سٍتـ̡ بٔرِتھ، حکمتس منز، فہم سٍتـ̡ تہٕ علمس مَنٛز، تہٕ پرٮ۪تھ قٕسمٕچ کاریگری سٍتـ̡ بٔرِتھ۔\n32.\\tتہٕ سۄنہٕ سٍتـ̡ تہٕ رۄپہٕ سٍتـ̡ تہٕ پیتلَس سٍتـ̡ کٲم کرٕنـ̡\n33.\\tتہٕ کنہِ ژٹنس منز، تہٕ لٔکرِ نقش و نگارس منز، کُنہِ تہِ طریقہٕ کُنہِ تہِ چالاکی ہٕنز کٲم کرنہٕ خٲطرٕ۔\n34.\\tتہٕ تٔمۍ چُھ پننِس دِلس مَنٛز تھوومُت زِ سُہ تہٕ دۅشوے ہیچھناوُن تہٕ دۅشوے یُس احیسامچ نیچو ڈین قبیلہٕ سُند اوس۔\n35.\\tتِمن چھُ دِلٕچ حکمت سٍتۍ بٔرِتھ، یُس پرٮ۪تھ قٕسمٕچ کٲم کٔرِتھ، نقش نگار تہٕ چالاک کامہِ سٕنز، تہٕ کٔرِتھ، نیوٗل تہٕ واگن رنگس منز، سرخ رنگس منز، تہٕ عمدہ کُنہِ کُنہِ کامہِ منز، تہٕ یِمن ہٕندِس کامہِ سٍتـ̡ تہٕ یِمن ہٕندِس کامہِ سٍتـ̡ کٲم کٔرِتھ۔","1.\\tاَمہِ پَتہٕ کٔرٕن بیزلیل تہٕ اہولیاب تہٕ پرٮ۪تھ کانہہ عقلمند انسان، یٔمِس مَنٛز خداوند سٕندِ حُکُم مُطٲبِق کِتھہٕ پٲٹھۍ چھِ مقدس مقامہٕ چہِ خدمتہٕ خٲطرٕ پرٮ۪تھ قٕسمٕچ کٲم کرنہٕ یِوان۔\n2.\\tتہٕ موسىٰ بُلوو بیزلیل تہٕ احولیاب، تہٕ پرٮ۪تھ کانہہ عقلمند انسان، یٔمۍ سٕندِس دِلس مَنٛز خداوند حکمت دِژمٕژ ٲس، {حتیٰ کہ} پرٮ۪تھ کانہہ یمۍ سُند دِل اوس أمِس یہِ کرنہٕ خٲطرٕ کامہِ ہٕندِس دِلس پیٹھ یِنہٕ خٲطرٕ ہُریر دِژمُت:\n3.\\tتہٕ تِمو مِیوُل موسیٰ سٕندِ طرفہٕ سٲرِے نذرانہ یُس بنی اسرٲیلِیو مقدس خانہٕ چہِ خدمتہٕ خٲطرٕ أنِمُت اوس۔ تہٕ تِم ٲسۍ پرٮ۪تھ صُبحٲے أمِس نِش مُفت نذرانہ انان۔\n4.\\tتہٕ سارِوٕے دانا یِمو مقدس مقامٕچ سارِوٕے کٲم کٔر، تِمو دِژ پرٮ۪تھ کانہہ انسان پننہِ کامہِ سٍتـ̡ یُس تمو بنوومُت اوس۔\n5.\\tتہٕ تِمو ووٚن موسیٰ سٍتـ̡ کامہِ ہٕنزِ خدمتہٕ خٲطرٕ واریاہ زیادٕ انان، یُس خداوند سُند حُکُم دِیُتمُت چھُ۔\n6.\\tتہٕ موسىٰ دِیُت حُکُم، تہٕ تِمو دِژ سٲرۍسٕے خٲمس منز یہِ اعلان کٔرِتھ زِ نہٕ مرد تہٕ زنانہٕ گژھِ نہٕ مقدس مقامہٕ خٲطرٕ مزید کٲم کرنہٕ۔ لہذا آیہ لوٗکھ اننہٕ نِش رُکاونہٕ۔\n7.\\tیُس چیز تمن نِش اوس، سہ اوس سارِنٕے کامہِ خٲطرٕ کٲفی، تہٕ واریاہ زیادٕ۔\n8.\\tتہٕ یِمو منزٕ پرٮ۪تھ کانہہ عقلمند دِل انسان یُس خیمہ ہٕنز کٲم کٔرِتھ، تٔمۍ بنٲوۍ داہ پردٕ نٔوۍ رٔٹِتھ کُن، تہٕ نیوٗل تہٕ واگن تہٕ سرخ رنگ۔\n9.\\tاکہ پردک زیچھر اوس وُہ ٲٹھ کیوبٹ، تہ اکس پردک کھجر اوس ژور کیوبٹ: پردٕ ٲسۍ اکۍ سے سائزس منز۔\n10.\\tتہٕ پانژھ پردٕ رٔٹِتھ اکھ أکِس سٍتـ̡ تہٕ پانژھ پردٕ رٔٹِتھ اکھ أکِس سٍتـ̡ جوڑان۔\n11.\\tتہ تمۍ بنوو کپلنگس منز سیلویج پیٹھہ اکس پردس ہندس اندس پیٹھ نیول رنگ لوپ: یتھے پاٹھۍ بنوو سہ {بییِہ} پردہ کس اندس پیٹھ، دویمہ کِس جوڑس منز۔ {سیلویج: پلوُک اکھ کنارٕ یُس تیوٗت ووُنمت چُھ زِ یہٕ ہیکہٕ نہٕ کھولِتھ}\n12.\\tپنژاہ لوپ بنوو سہ اکس پردس منز، تہ پنژاہ لوپ بنوو سہ پردہ کس اندس پیٹھ یُس {اوس} دوٚیمس کِس جوڑس منز: لوپس اوس اکھ {پردہ} بییس سیتۍ رٔٹتھ۔\n13.\\tتہٕ تٔمۍ بنوو پنژاہ سۄنہٕ سٍتـ̡ تہٕ پردٕ لٲگِتھ اکھ أکِس سٍتـ̡ رٔلِتھ تہٕ یِتھٕ پٲٹھۍ بنیوو یہِ اَکھ خیمہ ۔\n14.\\tتہٕ تٔمۍ بنوو خیمہ خٲطرٕ ژھاوٮ۪ن ہٕندِ {مست} پردٕ۔\n15.\\tاکہ پردُک زیچھر اوس ترہ کیوبِٹ تہ ژور کیوبِٹ اکہ پردُک کھجر: کاہ پردٕ ٲسۍ اکۍ سے سائزس منز۔\n16.\\tتہٕ تٔمۍ کٔر پانژھ پردٕ پانے، تہٕ شیہ پردٕ پانے۔\n17.\\tتہٕ تمۍ بنوو پردہ کس اندس پیٹھ پنژاہ لوپ تہ پنژاہ لوپ بنوو پردہ کس اندس پیٹھ یُس دویمِس جوڑس پیٹھ جوڑان چھہ۔\n18.\\tتہٕ تٔمۍ بنوو پنژاہ پیتل پیتل یُس خیمہٕ رلاونہٕ خٲطرٕ، یُتھ زن یہ اکھ آسہِ۔\n19.\\tتہٕ تٔمۍ بنوو خیمہ خٲطرٕ اکھ پردٕ {of} ریمسن ہٕنزِ کھالہٕ وۄزل رنٛگ کٔرِتھ، تہٕ ہیرِ کُن بٔرِن ہٕندِس کھالس ہُند پردٕ۔\n20. تہٕ تٔمۍ بنوو خیمہ {of} شیٹِم لٔکرِ خٲطرٕ بورڈ۔\n21.\\tتختُک زیچھر اوس داہ کیوبِٹ، تہٕ تختُک کھجر اوس ڈۅڈ کیوبِٹ۔\n22.\\tأکِس تختس منز ٲس زٕ ٹینن، یُس بییِس نِش برابر دور، یِتھٕ پٲٹھۍ بنوو تٔمۍ خیمہ کین سارنٕے تختن ہٕندِ۔\n23. تہٕ تٔمۍ بنٲو خیمہ خٲطرٕ تختہٕ۔ جنوبس طرفہٕ وُہ بورڈ:\n24. تہٕ ژتٲجی رۄپہٕ ساکٹ بنٲو تٔمۍ وُہن تختن تل۔ اکس بورڈس تل زٕ ساکٹ، تہٕ بییس بورڈس تل زٕ ساکٹ۔\n25. تہٕ خیمہ کِس دوٚیمہِ طرفہٕ، {یُس} شمٲلی کونس کُن، تٔمۍ بنٲوۍ وُہ تختہٕ،\n26.\\tتہٕ تِہٕندِ ژتٲجی رۄپہٕ سٕندِس ساکٹ۔ اکس بورڈس تل زٕ ساکٹ، تہٕ بییس بورڈس تل زٕ ساکٹ۔\n27. تہٕ مغرب کُن خیمہ کِس طرفن خٲطرٕ بنٲو تٔمۍ شےٚ تخت۔\n28.\\tتہٕ دۅشوٕے تختو بَنوو سُہ خیمہ کِس کونس خٲطرٕ۔\n29.\\tتہٕ تِم ٲسۍ بۅنہ کنہِ رٔلِتھ أکِس وٲج سٍتـ̡ رٔلِتھ، یِتھٕ پٲٹھۍ کٔر تٔمۍ دۄشوٕنی کونن منز۔ {جوڑ: ہیب۔ جڑواں }\n30. تہٕ اَتھ منز ٲسۍ ٲٹھ بورڈ۔ تہٕ تِہٕندِ ساکٹ ٲسۍ شُراہ ساکٹ، پرٮ۪تھ بورڈس تل زٕ ساکٹ۔ {انڈر ...: ہیب۔ زٕ ساکٹ، أکِس بورڈس تَل زٕ ساکٹ}\n31.\\tتہٕ تٔمۍ بنوو شِٹِم لٔکرِ ہٕندِ سلاخ۔ خیمہ کس اکہ طرفہٕ بورڈن خٲطرٕ پانژھ،\n32. تہٕ خیمہ کِس دوٚیمہِ طرفہٕ بورڈن خٲطرٕ پانژھ بار، تہٕ مغرب کُن خیمہ کِس بورڈن خٲطرٕ پانژھ بار۔\n33. تہٕ تٔمۍ بنوو درمیٲنی بار اکہ اندٕ پیٹھٕ دوٚیمس اندس تام بورڈن پیٹھ شوٹ کرنہٕ خٲطرٕ۔\n34. تہٕ تٔمۍ بنووُن سۄنہٕ سٍتـ̡ سٍتـ̡ تہٕ تِمن ہٕنزٕ وٲج بَنووٕنـ̡ سٍت\n35.\\tتہٕ تٔمۍ بنوو نیوٗل تہٕ واگن تہٕ سرخ تہٕ نٔوۍ رنٛگہٕ کُن: {سٍت} کرُبِمو بنوو یہِ چالاکی ہٕنز کٲم۔\n36.\\tتہٕ تٔمۍ بنوو اَتھ ژور تھَم شِٹِم {لٔکر}، تہٕ تِمن سٍتـ̡ سۄنہٕ سٍتـ̡ تہٕ تٔمۍ ترٛٲوۍ تمن خٲطرٕ ژور رۄپہٕ ساکٹ۔\n37. تہٕ تٔمۍ بنوو خیمہ کِس دروازس خٲطرٕ نیوٗل تہٕ واگن تہٕ سرخ تہٕ سٕژنہٕ کامہِ ہٕندِس باریک رنٛگہٕ دار کُن پھانسی ۔ {سٕژنہٕ کامہٕ: ہیب۔ سٕژنہٕ وٲل یا کڑھائی کرن وٲل سنٛز کٲم}\n38.\\tتہٕ اَمہ کِس پانژھ تھَم تہٕ تِمن ہٕندِس کُلِس سٍتـ̡ تہٕ تِمن ہٕندِس پٲٹھـ̡ سٍت","1.\\tتہٕ بَزلیلَن بَنوو صندوقہٕ شِٹِم لٔکرِ: اَمیُک زیچھر اوس زٕ کیوبِٹ تہٕ اَمیُک اکھ کیوبِٹ کھوٚر تہٕ اَمہ ہُند تھزر اوس ڈۅڈ کیوبِٹ ۔\n2.\\tتہٕ تٔمۍ تھووُن اتھ اندر تہٕ نیبَر خٲلص سۄنہٕ سٍتـ̡ تہٕ بنووُن اَتھ اندۍ پکھۍ سۄنہٕ سُند تاج۔\n3. تہٕ تٔمۍ ترٛٲوۍ اتھ خٲطرٕ ژور سۄنہٕ حلقہٕ، {یُس ژۄن کونن پیٹھ تھاونہٕ یُن}۔ امہِ کس اکہ طرفہ زہ حلقہ تہ دوٚیمہِ طرفہ زہ حلقہ۔\n4.\\tتہٕ تٔمۍ بنوو شِٹِم لٔکرِ سٍتـ̡ لٔکرِتھ تہٕ تمن سٍتـ̡ سۄنہٕ سٍتـ̡ تھپھ کٔرِتھ۔\n5.\\tتہٕ تٔمۍ ترٲو صندوق رٹنہٕ خٲطرٕ صندوقہٕ کِس اندۍ پکھۍ حلقن مَنٛز۔\n6.\\tتہ بنوو رحمتچ نشست خالص سۄنہٕ: زیچھر زٕ ساڑٕ تہٕ اکھ کیوبِٹ کھجر۔\n7. تہٕ تٔمۍ بنوو زٕ کرُبِم سۄنہٕ، یُس أکِس ٹُکرٕ سٍتـ̡ مارنہٕ آمُت چھُ، رحمتہٕ کِس دۄن اندس پیٹھ۔ {پیٹھ...: یا، نیبر، وغیرہ}\n8.\\tاَتھ اندس پیٹھ اکھ کرُب، تہٕ بییِس اندس پیٹھ بیاکھ کروب: رحمتٕچ نشستہٕ منزٕ بنوو سہ دۅن اندن پیٹھ کروبِم۔ {اندس پیٹھ: یا، نیبر، وغیرہ} {دوٚیمہِ اندس پیٹھ: یا، نیبر، وغیرہ}\n9. تہٕ کروبِمو پھٔہلٲوِکھ پَکھہٕ تھزرس پیٹھ، تہٕ رحمتٕچ کرسی پیٹھ پنٕنۍ پَکھہٕ ؤلِتھ، بُتھ اکھ أکِس سٍتـ̡ تھٲوِتھ۔ {حتیٰ کہ}رحمتٕچ نشستس پیٹھ ٲس کروبن ہٕندۍ بُتھۍ۔\n10.\\tتہٕ بنوو میز شیٹِم لٔکرِ: زٕ کیوبِٹ زیچھر تہٕ اکھ کیوبِٹ کھجر، تہٕ اکھ کیوبِٹ تہٕ اَمہ ہُند تھزر اکھ کیوبِٹ۔\n11. تہٕ تٔمۍ تھووُن اتھ خٲلص سۄنہٕ سٍتـ̡ تہٕ بنووُن اَتھ اندۍ اندۍ سُند تاج۔\n12.\\tتہِ بنوو تٔمۍ اَتھ اندۍ اَکھ کنارٕ۔ تہٕ بنووُن اندۍ سنہٕ خٲطرٕ سۄنہٕ سُند تاج۔\n13. تہٕ تٔمۍ ترٛٲو اتھ خٲطرٕ ژور سۄنہٕ وٲج تہٕ تھووُن ژۄن کونن پیٹھ وٲج یِم ژۄن فٹن منٛز ٲسۍ۔\n14.\\tاندس اندۍ ٲسۍ وٲج تہ لاٹھن ہٕنزِ میز رٹنہٕ خٲطرٕ جاے۔\n15.\\tتہٕ تٔمۍ بنوو لٔکرِ لٔکرِ تہٕ سۄنہٕ سٍتـ̡ لٔگِتھ لٔگِتھ دِنہٕ خٲطرٕ۔\n16.\\tتہٕ تٔمۍ بنوو تِم بانہٕ یِم میزس پیٹھ ٲسۍ، تٔمۍ سٕندِ برتن تہٕ چمچۍ، تہٕ پیالہٕ تہٕ تٔمۍ سٕندِس پوشہٕ سٍتـ̡ خٲلص سۄنہٕ سٍتـ̡ بٔنِتھ۔ {کور کرنہٕ خٲطرٕ...: یا، تراوُن}\n17.\\tتہٕ تٔمۍ بنوو شمعدان {of} خالص سۄنہٕ: {of} مارنہٕ آمٕژ کامہِ سٍتـ̡ بنیوو سُہ شمعدان تٔمۍ سٕنز لنجہ، تہٕ تٔمۍ سٕنز لنجہٕ، تٔمۍ سٕنز پیالہٕ، تٔمۍ سٕندِ گۅپھ تہٕ تٔمۍ سٕندۍ پوش ٲسۍ ہِوۍ:\n18.\\tتہٕ شیہ لنجہِ یِم اندۍ پکھۍ نیران چھِ۔ شمعدان ہندۍ تریہ لنجہِ اکہ طرفہ تہ امہِ کہ دوٚیمہِ طرفہ شمعدان ہنزہ تریہ لنجہِ:\n19.\\tأکِس لنجہِ منز بادامٕکۍ طرزِ پٲٹھۍبناونہٕ آمٕتۍ ترےٚ پیالہٕ، اکھ گُر تہٕ اکھ پوش۔ تہٕ تریہ پیالہ بیٚیِس لنجہِ منز بادامٕکۍ پٲٹھۍ بناونہٕ آمٕتۍ، اکھ گۅپھ تہٕ اکھ پوش: یِتھٕ پٲٹھۍ چھِ شیہ لنجہِ منز شمعدان منزٕ نیران۔\n20.\\tتہٕ شمعدان منز ٲسۍ ژور پیالہٕ بادام، تٔمۍ سٕندِ گۅپھ تہٕ تٔمۍ سٕندۍ پوش:\n21.\\tتہ امی ہنزن دۅن لنجہِ تلہ کنہِ اکھ نۅپ، تہ امی ہنزن دۅن لنجہِ تلہ کنہِ اکھ نۅپ، تہ امی ہنزن دۅن لنجہِ تلہ کنہِ اکھ گنڈ، امہ منزہ نیرن واجنہِ شیہ لنجہ مطٲبق۔\n22.\\tتِہٕندِ گۅپھ تہٕ تِہٕنزِ لنجہِ آسہٕ ہِشے: یہ سورُے اوس اَکھ کُنہِ کامہِ ہُند {یُس} خالص سۄنہٕ۔\n23.\\tتہٕ تٔمۍ بنوو پنٕنۍ سَتھ شمعہٕ، تہٕ پنٕنۍ نِفَر، تہٕ پَنٕنۍ نَفٕچ بَنٲوِتھ خٲلص سۄنہٕ۔\n24.\\tخالص سۅنہٕ سٍتـ̡ بنیوو سُہ تہٕ تِمن ہٕندِس سارِنٕے بانہٕ۔\n25.\\tتہٕ بنوو اگربُک قربان گاہ {of} شیٹِم لٔکرِ: اَمیُک زیچھر اوس اکھ کیوبِٹ، تہٕ اَمیُک کھجر اوس اکھ کیوبِٹ۔ {یہٕ اوس} فور سکوائر۔ تہٕ زٕ کیوبٹ {اوس} امیک تھزر؛ امکۍ سینگ ٲسۍ ہشے۔\n26.\\tتہٕ تٔمۍ بنوو اتھ خالص سۄنہٕ سٍتۍ، اَمہ کِس پیٹھمس حصس تہٕ اَمہ کِس اندۍ تہٕ اَمہ کِس سینگ سٍتـ̡ تہٕ بنووُن اَتھ سٍتـ̡ سۄنہٕ سُند تاج۔\n27.\\tتہٕ تٔمۍ بنوو امہِ کِس تاجس تلہ کنہِ دۅن کونن منز، امہِ کِس دۅن طرفن پیٹھ، یُتھ زن ڈنجہ رٹنہٕ خٲطرٕ جاے۔\n28.\\tتہٕ تٔمۍ بَنوو لٔکرِ لٔکرِ تہٕ تِمن سٍتـ̡ سۄنہٕ سٍتـ̡ تھپھ کٔرِتھ۔\n29.\\tتہٕ تٔمۍ بنوو مُقدس مسح کرنُک تیٖل تہٕ مٔدٕرِ مسالہٕ ہُند خالص اگرب۔","1. تہٕ تٔمۍ بنوو دزنہٕ نذرانہ ہُند قربان گاہ {of} شیٹِم لٔکرِ: پانژھ کیوبِٹ زیچھر تہٕ پانژھ ہُند کھجر۔ {یہٕ اوس} فور سکوائر۔ تہٕ ترے کیوبٹ تھزر۔\n2. تہٕ تٔمۍ بنوو اَمہ کِس ژۅشونی کونن پیٹھ سینگ ۔ امکۍ سینگ ٲسۍ اتھۍ سٍتۍ: تہٕ تٔمۍ کٔر اتھ پیتل سٍتۍ۔\n3. تہٕ بنوو قربان گاہٕکۍ تمام بانہٕ، بانہٕ، بیلچہٕ، تہٕ بیسن، {تہٕ} مازٕکۍ ہُکۍ، تہٕ نارٕکۍ بانہٕ: تِمو بَنوو سارِنٕے بانہٕ سٍتـ̡ پیتلُک ۔\n4. تہٕ تٔمۍ بنوو قربان گاہٕ خٲطرٕ اتھ کمپسس تل نیٹ ورک ہُند اکھ بریسن گریٹ یُس اتھ منز باگ تام اوس۔\n5. تہٕ تٔمۍ ترٛٲو پیتلٕچ گرِ ہٕندِس ژۄن اندس خٲطرٕ ژور وٲج ، یُس لٔٹِس خٲطرٕ جاۓ آسہٕ۔\n6.\\tتہٕ تٔمۍ بنوو لٔکرِ لٔکرِ سٍتـ̡ تہٕ تمن پیٹھ پیتل سٍتـ̡ تھپھ کٔرِتھ۔\n7. تہٕ تٔمۍ تھووُن قربان گاہ ہٕندِس اندۍ پکھۍ حلقن مَنٛز، یُس اتھ سٍتـ̡ برداشت کرنہٕ مۅکھہٕ۔ تم بنوو قربان گاہ بورڈو سۭتۍ کھوکھل۔\n8.\\tتہٕ تٔمۍ بنوو پیتل تہٕ اَمہ کِس پتلُک {of} پیتل، یُس جماعت کِس خیمہ کِس دروازس پیٹھ جمع گٔیہِ۔ {لوکنگ گلاسز: یا، بریسن شیش} {اسمبل: ہیب۔ فوجن ہٕنٛد ذریعہٕ جمع گژھُن}\n9. تہٕ تٔمۍ بنوو دربار: جنوبس طرفہٕ جنوبس کُن ٲس صحنٕچ پھانسی {ٲس} عمدہ جڑوٕنۍ کتان، اکھ ہتھ کیوبٹ:\n10.\\tتِہٕندِس تھَم ٲسۍ وُہ، تہٕ تِہٕندِس بریسن ساکٹ وُہ؛ ستونن ہٕندۍ ہُک تہٕ تِمن ہٕندۍ فِلٹ ٲسۍ رۄپہٕ ہٕندۍ۔\n11. تہٕ شمالہٕ طرفہٕ {پھانسی ٲس} ہتھ کیوبٹ، تہندٕ تھم {وُہ} تہٕ تِہند ساکٹ وُہ۔ ستونن ہٕندۍ ہُک تہٕ تِمن ہٕندِ فِلیٹس رۄپہٕ۔\n12.\\tتہٕ مغرب طرفہٕ ٲسۍ پنژاہ کیوبٹن ہٕندۍ پھانسی، تِہندۍ ستون داہ تہٕ تِہٕندِ ساکٹ دہ۔ ستونن ہٕندۍ ہُک تہٕ تِمن ہٕندِ فِلیٹس رۄپہٕ۔\n13. تہٕ مشرقس طرفہٕ پنژاہ کیوبٹ۔\n14.\\tاکہ طرفہ چھہ اکہ طرفہ پھانسی پندہ کیوبٹ۔ تہند ستون ترے، تہٕ تہند ساکٹ ترے۔\n15.\\tتہٕ درباری دروازٕ کِس دوٚیمہِ طرفہٕ ، اَتھ تہٕ تتھ اتھس پیٹھ ٲسۍ پنٛداہن کیوبٹن ہٕندِ پھانسی ہٕندِس لٹان۔ تہند ستون ترے، تہٕ تہند ساکٹ ترے۔\n16.\\tدربارٕکۍ سارِنٕے پھانسی ٲسۍ نٔوۍ لٔگِتھ کُنہِ\n17. تہٕ ستونن ہٕندِ ساکٹ ٲسۍ پیتلٕکۍ ۔ ستونن ہٕندۍ ہُک تہٕ تِمن ہٕندِ فِلیٹس {of} رۄپہٕ؛ تہٕ تِمن ہٕندِس چیپیٹرن ہٕندِس رۄپہٕ سٍتۍ اوورلیِنگ؛ تہٕ دربارٕکۍ سٲری تھم ٲسۍ رۄپہٕ سۭتۍ بٔرِتھ۔\n18.\\tتہٕ دربار کِس دروازس خٲطرٕ اوس سژنہٕ کامہِ، نیوٗل تہٕ واگن تہٕ سرخ تہٕ نٔوۍ لٔٹِتھ کُن، تہٕ وُہ کیوبِٹ زیچھر تہٕ کھجرس منز اوس پانژھ کیوبِٹ، یُس دربارٕ کِس پھانسی ہُند جوابدہ اوس۔\n19.\\tتہٕ تِہٕندِ تھَم ٲسۍ ژور، تہٕ تِہٕندِ ساکٹ {of} پیتل ژور۔ تہند ہُک رۄپہٕ، تہٕ تہندٕ چیپٹرن تہٕ تہندٕ فلیٹس {of} رۄپہٕ۔\n20.\\tتہٕ خیمہ خانہٕ تہٕ اندۍ پٔکۍ دربارٕکۍ سٲری پِنہٕ آسہٕ پیتلٕکۍ ۔\n21. یہِ چُھ خیمہ ہُند مجموعہٕ، یُس گوٲہی ہٕندِس خیمہ ہُند مجموعہٕ چُھ، یُس موسیٰ سٕندِس حُکمس مُطٲبق اوس شمار کرنہٕ آمُت، یُس ہارون سُند نیچو اِتھامار سٕندِ اتھہٕ سٍتـ̡ شمار کرنہٕ آمُت اوس۔\n22. تہٕ یہوداہ قبیلہٕ کِس حُور سٕندِس نیچوِس یُس اُوری سُند نیچو بیزلیلن بنوو سُہ سورُے یُس خداوند موسیٰ سُند حُکُم اوس دِتمُت۔\n23.\\tتہٕ أمِس سٍتـ̡ اوس اہولیاب، یُس اہیسامچ نیچو، دان قبیلُک اوس، اکھ نقش نگار، تہٕ اکھ چالاک کامہِ، تہٕ نیلِس رنگس منز، تہٕ سرخ رنگس منز، تہٕ نفیس کُنِس منز کٔرِتھ کٔرِتھ۔\n24.\\tسٲرۍسٕے سۄنہٕ یُس مُقدس سٕنزِ سارِنٕے کامہِ مَنٛز کٲم کرنہٕ خٲطرٕ اوس، حتیٰ کہ نذرانہٕ ہُند سۄنہٕ تہِ اوس وُہ تہٕ نوُن ٹیلنٹ تہٕ ستھ ہتھ ترہ شیکل۔\n25.\\tیِمن ہٕندِس رۄپہٕ سٍتـ̡ یُس جماعت ہُند تعداد اوس، سُہ اوس ہتھ ٹیلنٹ تہٕ ستھ ہتھ تریہ تہٕ پندہ شیکل، مقدس مقامہٕ کِس شیکل پتہٕ۔\n26.\\tپریتھ انسانس خٲطرٕ اکھ بیکا، یعنی نصف شیکل، یُس وُہن ؤرین پیٹھٕ تہٕ امہِ کھوتہ زیادٕ شیہ ساس تہٕ پانژھ ہتھ تہٕ پنژاہ انسان گنزراونہ ییہِ۔ {ہر انسان: ہیب۔ اکھ پول}\n27.\\tتہٕ رۅپہٕ ہٕندیو ہتہٕ ٹیلنٹ منزٕ آیہ مقدس مقامٕکۍ ساکٹ تہٕ پردٕکۍ ساکٹ تراونہٕ۔ ہتھ ٹیلنٹُک اکھ ہتھ ساکٹ، اکھ ٹیلنٹ اکھ ساکٹ۔\n28.\\tتہٕ ساس ستھ ستتھ پانژو شیکلو منزٕ بنوو تمٔۍ ستونن خٲطرٕ ہُک تہٕ تِمن ہٕندِس چیپٹرس پیٹھ تھووُن تہٕ بٔرِتھ۔\n۲۹. تہٕ نذرانہ ہُند پیتل اوس ستتھ ٹیلنٹ تہٕ زٕ ساس ژور ہتھ شیکل۔\n30.\\tتہٕ اَتھ سٍتـ̡ بنوو تٔمۍ جماعت ہٕندِس خیمہ کِس دروازس تام، تہٕ براسن قربان گاہٕ، تہٕ اَمہ خٲطرٕ بٔنِتھ تہٕ قربان گاہٕکۍ سارِنٕے بانہٕ،\n31.\\tتہٕ دربارٕکۍ ساکٹ، تہٕ دربارٕکۍ دروازٕکۍ ساکٹ، تہٕ خیمہ خانٕکۍ سٲری پِن، تہٕ أندۍ پٔکۍ تمام پِنہٕ۔","1. تہٕ نیوٗل تہٕ واگن تہٕ سرخ رنگہٕ سٍتـ̡ بَنوو تِمو عبادتٕکۍ پلو، یُس مقدس مقامس مَنٛز خدمت کرنہٕ مۅکھہٕ تہٕ ہارون سٕندِ خٲطرٕ بَنووُکھ مقدس پوشاک۔ یِتھ کٔنۍ خداوند موسیٰ سُند حُکُم دِیُت۔\n2. تہٕ تٔمۍ بنوو سۄنہٕ، نیوٗل تہٕ واگن تہٕ سرخ تہٕ نٔوۍ لٔگِتھ کُن۔\n3.\\tتہٕ تِمو کٔر سۄنہٕ پتلہٕ پلیٹَن مَنٛز، تہٕ ژٔٹِکھ تارن منز، نیلِس منز، واگن رنگس منز، سرخ رنگس منز، تہٕ باریک کِتابس منز، {سٍت} چالاکی سٍتۍ۔\n4.\\tتمو بنوو امہ خاطرہ پھیکس ٹُکرۍ، یکوٹہ جوڑنہ خاطرہ: دۅشوے اندو سیتۍ اوس یہ رلان۔\n5.\\tتہ امۍ سنزِ ایفوڈچ عجیب و غریب بند، یُس اتھ پیٹھ اوس، {اوس} امی سٍتۍ، امہ چہ کامہِ مطٲبق۔ {of} سۄن، نیوٗل تہٕ وانٛگنی، تہٕ سرخ رنگ، تہٕ باریک جڑواں کُن؛ یِتھ کٔنۍ خداوند موسیٰ سُند حُکُم دِیُت۔\n6.\\tتہٕ تِمو بنٲوِکھ سۄنہٕ سٕندِس سٍتـ̡ کھٔنِتھ تہٕ یِمن پیٹھ بنی اِسرٲیلِیَن ہٕندِس ناوَس سٍتـ̡ کھٔنِتھ چھِ۔\n7. تہٕ تٔمۍ تھوو تِم ایفود کِس پھیکس پیٹھ، {یُتھ زن تِم بنی اسرائیلٕچ یادگار خٲطرٕ کٔنہِ بٔنِتھ۔ یِتھ کٔنۍ خداوند موسیٰ سُند حُکُم دِیُت۔\n8.\\tتہٕ تٔمۍ بنوو سینہٕ ہٕنزِ کامہِ ہٕندۍ پٲٹھۍ، چالاکی سان کٲم۔ {of} سۄنہٕ، نیوٗل تہٕ واگن رنگ، تہٕ سرخ رنگ، تہٕ عمدہ جڑواں کُن۔\n9. یہ اوس ژور مربع۔ تمو بنوو سینہٕ پلیٹ دوگنہٕ: اکھ وقفہٕ {اوس}امیک زیچھر، تہٕ اکھ طول اوس امیک کھجر، {being} دۄگنہٕ۔\n10.\\tتہٕ تمو تھٲوۍ اتھ منز ژور لٲنہٕ کنۍ: {گوڈنِکِس صفہٕ {اوس} اکھ سارڈیئس، اکھ ٹوپاز تہٕ اکھ کاربنکل: یہِ {اوس} گۅڈنِچ لٲنہٕ۔ {سارڈیئس: یا، روبی}\n11. تہٕ دوٚیم لٲنہٕ، اکھ زمرد ، اکھ نیلم تہٕ اکھ ہیرہ۔\n12. تہٕ تریم لٲن، اکھ لیگور، اکھ ایگیٹ تہٕ اکھ امیتھیسٹ۔\n13.\\tتہِ ژورمہِ لٲنہِ منز اکھ بیرل، اکھ اونکس تہ اکھ جیسپر: {تِم ٲسۍ} پننین انکلوژنس منز سۅنہٕ سٕندِس آؤچس منز ؤلِتھ۔\n14.\\tتہٕ کٔنہِ آسہٕ بنی اسرٲیلِن ہٕندِ ناوٕ مُطٲبق، بارہ تہٕ تِہندِ ناوٕ مُطٲبق، بَہہ قبیلو مُطٲبق أکِس نِش نقش کٔرِتھ، پرٮ۪تھ أکِس سٕندِس ناوَس مُطٲبق۔\n15.\\tتہٕ تِمو بنوو سینہٕ پلیٹس پیٹھ زنجیر {of} خالص سۄنہٕ۔\n16. تہٕ تِمو بنٲوۍ زٕ سۄنہٕ تہٕ زٕ سۄنہٕ وٲج ۔ تہٕ تھٲوِو زٕ وٲج بریسٹ پلیٹ کِس دۄن اندَن منٛز۔\n17.\\tتہٕ تِمو تھووُن سۅنہٕ سٕنزِ زٕ گلہٕ زنجیر۔\n18.\\tتہ دۅن گلن ہنزن زنجیرن ہندۍ دۅشوے اند لٲگتھ تہ تھووکھ اتھ برونہہ کنہِ ایفود کس پھیکس پیٹھ۔\n19.\\tتہٕ تِمو بَنوو سۄنہٕ سٕندِس زٕ حلقہٕ، تہٕ تھووُکھ سینہ ہٕندِس دۄن اندس پیٹھ، یُس {اوس} ایفود کِس اندس پیٹھ۔\n20. تہٕ تِمو بَنوو زٕ {باقی} سۄنہٕ وٲج تہٕ تھووُکھ ایفود کِس دۄن طرفن پیٹھ، امہِ کِس برونہمہِ حصس کُن، اَمہ کِس {باقی} جوڑس خلاف، ایفوڈٕچ عجیب و غریب بندس پیٹھ۔\n21.\\tتہٕ تِمو لٲگِتھ سینہٕ ہٕندِس حلقہٕ سٍتـ̡ نیوٗل رنٛگہٕ سٍتـ̡ گٔنڈِتھ، یُتھ زِ سُہ گژھہِ ایفود کِس عجیب و غریب بندس پیٹھ، تہٕ یُتھ زِ سینہٕ پوشہٕ گژھہِ نہٕ ایفودٕ سٕندِس سٍتـ̡ یلہٕ تراونہٕ۔ یِتھ کٔنۍ خداوند موسیٰ سُند حُکُم دِیُت۔\n22.\\tتہٕ تٔمۍ بنوو ایفوڈُک پوشاک {of} ووُنُن کٲم، سارِنٕے {of} نیوٗل۔\n23.\\tتہِ اوس پوشہِ منز اکھ سوراخ، یُس زَدِ اندۍ اکھ بند اوس، یُس نہ گٔژھِتھ گژھہِ۔\n24.\\tتہٕ تِمو بنوو پوشہٕ کِس دامن پیٹھ نیوٗل تہٕ واگن تہٕ سرخ رنگہٕ، {تہٕ} جُڑِتھ {کُن}۔\n25.\\tتہٕ تِمو بَنوو خٲلِص سۄنہٕ سٕنزِ گھنٹِیہِ، تہٕ تھووُکھ دٲنَن مَنٛز گھنٹی پوشہٕ کِس دامن پیٹھ، یُس انارَن مَنٛز اندۍ پکھۍ۔\n26. اکھ گھنٹی تہٕ اکھ انار، اکھ گھنٹی تہٕ اکھ انار، پوشاک کس اندس اندۍ خدمت کرنہٕ خٲطرٕ۔ یِتھ کٔنۍ خداوند موسیٰ سُند حُکُم دِیُت۔\n27.\\tتہٕ تِمو بَنوو ہارون تہٕ تٔمۍ سٕندٮ۪ن نیٚچوٮ۪ن ہٕندِ خٲطرٕ رٔژ کُنہِ کامہِ ہٕندِ خٲطرٕ،\n28.\\tتہٕ اَکھ مِٹر {of} نفیس کُن، تہٕ اصل بونٹ {of} باریک کُن، تہٕ کُن بریچ،\n29.\\tتہٕ اکھ گرڈل {of} باریک جڑوُن کُن، تہٕ نیوٗل، تہٕ واگن تہٕ سرخ رنگ، {of} سژنہٕ کٲم۔ یِتھ کٔنۍ خداوند موسیٰ سُند حُکُم دِیُت۔\n30.\\tتہٕ تِمو بَنوو پاک تاجٕچ پلیٹ خٲلص سۄنہٕ سٍتـ̡ تہٕ اتھ پیٹھ لیکھُکھ اکھ تحریر، {یِتھ کٔنِتھ} کُنہِ نشانہٕ سٍتـ̡ نقش و نگار، پاکیزگی خداوند سٕندِس سٍتـ̡ ۔\n31.\\tتہٕ تِمو لٲگِتھ اَتھ سٍتۍ نیوٗل رنٛگُک فیتہٕ لٲگِتھ، یُس تھزرس پیٹھ تھزرس پیٹھ لٲگِتھ اوس۔ یِتھ کٔنۍ خداوند موسیٰ سُند حُکُم دِیُت۔\n32. یِتھٕ پٲٹھـ̡ سپُد جماعت کِس خیمہ کِس خیمہ ہٕنز سورے کٲم مُکمل: تہٕ بنی اسرٲیلِو کٔر سارِنٕے مُطٲبق یُس خداوند موسىٰ سُند حُکُم دِیُتمُت اوس، تِمو تہِ کٔر۔\n33. تہٕ تِمو أنۍ خیمہ موسیٰ سٕندِس نِش، خیمہ تہٕ تٔمۍ سٕندِس تمام فرنیچر، تٔمۍ سٕندِس سٲرۍسٕے کُنہِ کُنہِ تہٕ تٔمۍ سٕندِس سٲرۍسٕے سٕندِس سٍتـ̡ تہٕ تٔمۍ سٕندِس سٍتـ̡\n34.\\tتہٕ کۅکرِ ہٕندِس کھالُک پردٕ رنٛگ کٔرِتھ تہٕ بٔرِن ہٕندِس کھالہٕ سٍتـ̡ تہٕ پردٕ ہٕندِس پردٕ سٍتـ̡\n35. گوٲہی ہُند صندوق، تہٕ اَمہِ ہٕندِس لٔٹِس تہٕ رحمتٕچ نشست،\n36.\\tمیز، {تہٕ} اَمہ کِس سارِنٕے بانہٕ تہٕ شیوبریڈ\n37.\\tخالص شمعدان، {سٍت} چراغن سٍتۍ، {حتیٰ کہ} چراغ ترتیب دِنہٕ یِن، تہٕ تِمن ہٕندِس سارِنٕے برتن تہٕ گاشہٕ خٲطرٕ تیٖل\n38. تہٕ سۄنہٕ قربان گاہ، تہٕ مسح کرنُک تیٖل، تہٕ مٔدٕر اگرب، تہٕ خیمہ کِس دروازس خٲطرٕ پھانسی دِنہٕ، {مٔٹھۍ...: ہیب۔ مٔدٕر مسالہٕ ہُند اگرب}\n39.\\tبریسن قربان گاہ، تہٕ تٔمۍ سٕندِ پیتلُک گرِٹ، تٔمۍ سٕندِ لٔرۍ، تہٕ تٔمۍ سٕندِس سارِنٕے بانہٕ، لاور تہٕ تٔمۍ سٕندِس کھۅر\n40. دربارٕچ پھانسی ، تٔمۍ سٕندِ تھم تہٕ تٔمۍ سٕندِس ساکٹ، تہٕ دربارٕکِس دروازس خٲطرٕ پھانسی ، تٔمۍ سٕنزِ رزِ تہٕ تٔمۍ سٕنزِ پِنہٕ تہٕ خیمہ چہِ خدمتٕکۍ تمام بانہٕ، جماعت ہٕندِس خیمہ خٲطرٕ،\n41.\\tمقدس مقامس مَنٛز خدمت کرنہٕ خٲطرٕ تہٕ پادٕرۍ سٕندِس دفترس مَنٛز خدمت کرنہٕ خٲطرٕ ہارون سٕندِ خٲطرٕ تہٕ تٔمۍ سٕندِس نیچوٮ۪ن ہٕندِ خٲطرٕ مقدس پوشاک۔\n42. یُس خداوند موسىٰ سُند حکم دِیُت تہٕ تِتھٕ کٔنۍ کٔر بنی اسرٲیلِیو سورُے کٲم۔\n43. تہٕ موسىٰ کٔر سارِنٕے کامہِ وُچھمُت، تہٕ وُچھِتھ اوس تِمو یہِ خداوند سُند حُکُم کوٚرمُت، تہٕ موسىٰ کٔر تِمن برکت۔","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2. گۄڈنِکہِ رٮ۪تہٕ کِس گۄڈنِکہِ دۅہہٕ کٔرِو ژے جماعت ہٕندِس خیمُک خیمہ قٲیم۔\n3. تہٕ توے تھاوُن اَتھ منز گوٲہی ہٕندِس صندوقس مَنٛز، تہٕ صندوقہٕ کٔرِو پردٕ سٍتـ̡ ؤلِتھ۔\n4.\\tتہٕ تُہۍ کرِو میزس اندر انُن، تہٕ تِم چیز تھاوُن یِم اتھ پیٹھ ترتیب دِنہٕ یِن۔ تہٕ ژے اَنُن شمعدان تہٕ اَمہ کِس شمعس زالُن۔ {چیز...: ہیب۔ امچ ترتیب}\n5. تہٕ تہٕ ژے تھاوُن گوٲہی ہٕندِس صندوقس برونہہ کُن بخور خٲطرٕ سونہٕ سُند قربان گاہ، تہٕ دروازٕ تراوُن خیمہ خانس کُن۔\n6. تہٕ ژے تھاوُن زالنہٕ آمٕژ قربان گاہُک قربان گاہ جماعت کِس خیمہ کِس دروازس برونہہ کُن۔\n7. تہٕ ژے تھاوُن جمٲژ ہٕندِس خیمہ تہٕ قربان گاہس درمِیان تہٕ اَتھ مَنٛز آب تراوُن۔\n8.\\tتہٕ ژے کٔرِو دربار اندۍ بٔنِتھ، تہٕ دِیُکھ دربار کِس دروازس پیٹھ پھانسی دِنہٕ۔\n9. تہٕ ژے گژھِو مسح کرنُک تیٖل رٔٹِتھ، تہٕ خیمہ تہٕ اَتھ مَنٛز موجود سارِنٕے چیٖز مسح کٔرِتھ، تہٕ یِمن ہٕندِس سارِنٕے بانہٕ تہٕ یِمن ہٕندِس سارِنٕے بانہٕ پاک کرُن، تہٕ یہِ گژھہِ مُقدس۔\n10. تہٕ ژے کرِ دزنہٕ آمٕژ قربان گاہ تہٕ تٔمۍ سٕندِس سارِنٕے بانہٕ مسح کٔرِتھ تہٕ قربان گاہ پاک کرُن، تہٕ یہِ گژھہِ سارِوٕے کھۄتہٕ مقدس قربان گاہ آسُن۔ {انتہائی مقدس: ہیب۔ پاکیزگی ہٕنز پاکیزگی}\n11.\\tتہٕ ژے کرِ لۅتہٕ تہٕ تٔمۍ سٕندِس کھۅر مسح تہٕ تٔمِس پاکیز۔\n12.\\tتہٕ تُہۍ أنِو ہارون تہٕ تٔمۍ سٕندِس نیچوِس جماعت کِس خیمہ کِس دروازس تام تہٕ آبہٕ سٍتـ̡ چھلناوُن۔\n13.\\tتہٕ ہارونس لٲگِو مقدس پوشہٕ، تہٕ مسح کٔرِو تہٕ پاکیزہ۔ تاکہ سُہ کرِ پادٕرۍ سٕندِس دفترس منز میانہِ خدمت کرنہٕ۔\n14. تہٕ تٔمۍ سٕندِس نیچوِس أنِتھ تہٕ تِمن پلو لٲگِتھ:\n15. تہٕ تہٕ ژے کٔرِو تِمن مسح کرنہٕ، یِتھ کٔنۍ ژے تِہنٛدِس مٲلِس مسح کٔرِتھ، یُتھ زن تِم پادٕرۍ سٕندِس دفترس مَنٛز میانہِ خدمت کٔرِتھ، تِکیازِ تِہُند مسح گژھہِ یٔقیٖنی طور تِمن ہٕندِس سارِنٕے نسلن ہُند دٲیرٕ پادٕرۍ۔\n16.\\tیِتھے پٲٹھۍ کوٚر موسیٰ یُس خداوند أمس حکم دِژمُت، تِتھۍ کٔر تِتھۍ سٍتـ̡ تہِ۔\n17.\\tتہٕ سپُد دۆیمِس ؤریس مَنٛز گۅڈنِکِس ریتس مَنٛز، یێمہِ ریتہٕ کِس گۄڈنِکِس دۅہہٕ {یێلہِ} آو خیمہ بٔنِتھ کھڑا کرنہٕ۔\n18.\\tتہٕ موسیٰ کٔر خیمہ تھوٚد، تہٕ کٔرٕن پنٕنۍ ساکٹ بٔنِتھ، تہٕ لٔگِن اَتھ ہٕندِس ڈنجہٕ تہٕ تھپھ کٔرِتھ تھپھ کٔرِتھ۔\n19.\\tتہٕ تٔمۍ پھٔہلٲوِتھ خیمہ خیمہ تہٕ اتھ پیٹھ تھووُن خیمُک پردٕ۔ یِتھ کٔنۍ خداوند موسیٰ سُند حُکُم دِیُت۔\n20.\\tتہٕ تٔمۍ رٔٹِتھ گوٲہی صندوقس مَنٛز تھووُن، تہٕ تھووُن صندوقس پیٹھ تہٕ تھووُن رحمتُک تخت صندوقس پیٹھ۔\n21. تہٕ تٔمۍ أنۍ صندوقہٕ خیمہ خانس منٛز، تہٕ کورُن پردٕ تہٕ گوٲہی ہٕندِس صندوقس تھوٚپ۔ یِتھ کٔنۍ خداوند موسیٰ سُند حُکُم دِیُت۔\n22.\\tتہٕ تٔمۍ تھوو جماعت کِس خیمس مَنٛز، خیمہ کِس شمالس کُن، پردٕ ورٲے۔\n23.\\tتہٕ تٔمۍ کٔر خدایہِ سٕندِس برونہہ کُن روٹی ترتیب دِنہٕ۔ یِتھ کٔنۍ خداوند اوس موسیٰ سُند حُکُم دِتمُت۔\n24. تہٕ تٔمۍ تھوو شمعدان جماعت کِس خیمس منز، ٹیبلس پیٹھ، خیمہ کِس جنوبس کُن۔\n25. تہٕ تٔمۍ دِژ خداوند سٕندِ برونہہ کُن شمع۔ یِتھ کٔنۍ خداوند موسیٰ سُند حُکُم دِیُت۔\n26.\\tتہٕ تٔمۍ تھوو سۅنہٕ قربان گاہ جماعت کِس خیمس مَنٛز:\n27.\\tتہٕ تٔمۍ زٲلِتھ مٔدٕر اگرب۔ یِتھ کٔنۍ خداوند موسیٰ سُند حُکُم دِیُت۔\n28.\\tتہٕ تٔمۍ کٔر خیمہ کِس دروازس پیٹھ پھانسی لگاونہٕ۔\n29.\\tتہٕ تٔمۍ تھووُن جمٲژ ہٕندِس خیمہ کِس خیمہ کِس دروازس سٍتـ̡ دزنہٕ نذرانہ تہٕ مازٕچ نذرانہ پیش کرنہٕ۔ یِتھ کٔنۍ خداوند موسیٰ سُند حُکُم دِیُت۔\n30.\\tتہٕ تٔمۍ تھووُن جمٲژ ہٕندِس خیمہ تہٕ قربان گاہس درمِیان تہٕ تھووُن آب یُس چھلنہٕ مۅکھہٕ۔\n31. تہٕ موسیٰ تہٕ ہارون تہٕ تٔمۍ سٕندِس نیچویو کٔر اَتھ سٍتـ̡ اَتھٕ تہٕ کھۅر واش کٔرِتھ:\n32.\\tییلہ تِم جمٲژ ہٕندِس خیمس مَنٛز گٔیہِ، تہٕ ییلہ تِم قربان گاہس نزدیک وٲتۍ، تِمو چھلنہٕ آمٕتۍ۔ یِتھ کٔنۍ خداوند موسیٰ سُند حُکُم دِیُت۔\n33.\\tتہٕ تٔمۍ کٔر خیمہ تہٕ قربان گاہس اندۍ پٔکھۍ صحن تہٕ کورُن دربارُک دروازٕ لٹان۔ چنانچہ موسیٰ کٔر کٲم مکمل۔\n34. پَتہٕ اَکہِ اوٚبرُن لوٚگ جمٲژ ہٕندِس خیمے سٍتـ̡ تہٕ خداوند سٕندِ جلال سٍتـ̡ بٔرِتھ بٔرِتھ۔\n35.\\tتہٕ موسیٰ ہیوٚک نہٕ جماعت کِس خیمس مَنٛز اژِتھ، تِکیازِ اَتھ پیٹھ اوس اوبُر روزان، تہٕ خداوند سٕندِ جلال سٍتـ̡ اوس خیمہ بٔرِتھ۔\n36.\\tتہٕ ییلہ خیمہ پیٹھٕ اوبُر تُلنہٕ آو تہٕ بنی اسرٲیلِس پٔکِس سارِنٕے سفرس مَنٛز پٔکۍ: {پٔکۍ: حبری۔ سفر}\n37.\\tمگر اگر نہ اوبُر تُلنہٕ آو، تیلہِ رودۍ نہ تِم تتھ دۅہس تام سفر ییمہِ دۅہہ یہ تُلنہٕ آو۔\n38.\\tیِکیازِ خداوند سُند اوبر اوس دۅہلہٕ خیمہ خانس پیٹھ، تہٕ سارِنٕے اِسرٲیلِیَن ہٕندِس سارِنٕے سفرس سٍتـ̡ اوس اتھ پیٹھ راتس نار آسان۔"];
